package com.qingji.app.data.local

import com.qingji.app.data.local.entity.ExerciseEntity

/**
 * ============================================================
 * 训练中心内置动作库（Workout Guide 302 条，v1.3.0）
 * ------------------------------------------------------------
 * 来源：github.com/bryllim/workout-guide，302 条动作、906 帧本地 SVG。
 *   · 38 条 ex-*   —— 老动作 UUID 原样保留，按 slug 精确命中上游；
 *   · 264 条 wg:*  —— 新动作稳定 ID，来自 "wg:" + slug，不随机生成。
 *
 * 边界：
 *   · steps / commonMistakes 已按动作逐条撰写通用训练要点与常见错误（v2 起内置）；
 *     老库为空时由导入计划器回填，用户自己编辑过的值仍一律沿用不覆盖；
 *   · 分类是轻记展示用七类，上游 primaryMuscles / secondaryMuscles 原样保留；
 *   · attribution 保留上游逐条授权 JSON，76 条 Everkinetic 来源不泛化；
 *   · 灌库走 TrainingSeedImportPlanner + UUID 差集 + IGNORE，不清表、不 REPLACE。
 * ============================================================
 */
object TrainingSeed {

    const val CHEST = "chest"
    const val BACK = "back"
    const val SHOULDER = "shoulders"   // 保留旧常量名，实际值改为上游七类
    const val ARM = "arms"
    const val LEG = "legs"
    const val CORE = "core"
    const val STRETCH = "mobility"

    /** 当前动作库版本；写入 library_meta，避免每次启动重复导入。 */
    const val LIBRARY_VERSION = "workout-guide-302-v2"
    const val LIBRARY_VERSION_KEY = "workout_guide_library_version"

    /** 分类 key → 界面中文名（胶囊筛选与动作库分类共用）。 */
    val CATEGORY_LABELS = listOf(
        CHEST to "胸部", BACK to "背部", SHOULDER to "肩部", ARM to "手臂",
        LEG to "腿部", CORE to "核心", STRETCH to "拉伸"
    )

    private data class Seed(
        val uuid: String,
        val name: String,
        val englishName: String,
        val slug: String,
        val category: String,
        val primary: String,
        val secondary: String,
        val equipment: String,
        val exerciseType: String,
        val isStretch: Boolean,
        val assetPath: String,
        val attribution: String,
        val steps: String,
        val mistakes: String
    )

    private val SEEDS = listOf(
        Seed("ex-chest-02", "杠铃卧推", "Bench Press", "bench-press", "chest", "Chest", "Triceps,Shoulders", "Barbell", "weight_reps", false, "exercises/chest/bench-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0042-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧在平凳上，双脚踩实地面，肩胛骨收紧下沉，杠铃对准胸部上方。\n双手握距略宽于肩，手腕保持中立不后弯，起杠后让杠铃位于肩部正上方。\n缓慢下放杠铃至中胸位置，小臂在最低点大致垂直于地面。\n发力时想象用胸口把杠铃推起来，推起过程杠铃走一条微斜向上的直线。\n下放时吸气、上推时呼气，全程保持躯干稳定不耸肩。", "只用手臂硬推而不管胸部发力：想着用胸肌夹住杠铃下压，推起时胸口主动顶起来。\n杠铃下放过深或砸到胸口弹起：放到轻触胸口即可停住，控制节奏不靠反弹。\n臀部离开凳面借力：重量降到能全程贴凳的负荷，双脚踩稳地面上推。"),
        Seed("wg:incline-bench-press", "上斜杠铃卧推", "Incline Bench Press", "incline-bench-press", "chest", "Chest", "Shoulders,Triceps", "Barbell", "weight_reps", false, "exercises/chest/incline-bench-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0043-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "把凳子调到约30到45度角，背部和臀部贴紧凳面，肩胛骨后收下沉。\n握距略宽于肩，起杠后杠铃位于上胸正上方。\n下放杠铃到锁骨与上胸之间的高度，手肘略向内收。\n推起时感受上胸的挤压感，动作幅度做满但不锁死手肘。\n下放时吸气、推起时呼气，重心始终压在凳面上。", "凳子角度调得太陡变成肩推：控制在30到45度，推之前先确认身体贴凳的角度。\n下放位置太低打到中胸：让杠铃落在锁骨和上胸之间，用手肘方向引导轨迹。\n手肘完全打开与肩成一条线：下放时手肘自然内收约45度左右，保护肩关节。"),
        Seed("ex-chest-04", "上斜哑铃卧推", "Incline Dumbbell Press", "incline-dumbbell-press", "chest", "Chest", "Shoulders,Triceps", "Dumbbell", "weight_reps", false, "exercises/chest/incline-dumbbell-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0061-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "凳面调至30到45度，坐稳后肩胛骨贴紧凳面，双手各握一个哑铃举在上胸两侧。\n手肘略低于肩的位置开始下放，哑铃沿弧线缓缓下降到上胸两侧。\n最低点感受上胸轻微拉开后，沿弧线把哑铃向内上方推起。\n推到顶端时哑铃可以靠近但不相碰，胸肌持续收紧。\n下放吸气、推起呼气，全程手腕保持中立不塌。", "哑铃推起后互相碰撞泄力：顶端留一点距离让胸肌保持张力。\n手肘过度下拉到身体两侧：手肘保持约45度夹角，下放幅度以胸口有拉伸感为限。\n腰部拱起悬空借力：减小重量并把下背部贴实凳面，靠胸肩发力完成。"),
        Seed("ex-chest-01", "哑铃卧推", "Dumbbell Bench Press", "dumbbell-bench-press", "chest", "Chest", "Triceps,Shoulders", "Dumbbell", "weight_reps", false, "exercises/chest/dumbbell-bench-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0055-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧平凳，双脚踩地，肩胛骨收紧下沉，哑铃举在胸口两侧上方。\n手肘约45度角缓缓下放，让哑铃落到中胸两侧同高位置。\n最低点感受胸部轻微拉伸，然后沿弧线向上向内推起。\n顶端哑铃靠拢但不相碰，想象用胸肌把两个哑铃夹在一起。\n下放吸气、上推呼气，两个哑铃始终保持同步等速。", "两个哑铃一高一低发力不均：照着镜子或放慢速度，让两侧动作轨迹完全对称。\n下放太深猛拉肩关节：降到胸口有舒服拉伸感即停，别追求极限幅度。\n只推到手肘半程没夹胸：推到顶端时主动收紧胸肌一秒再进入下下一次。"),
        Seed("wg:decline-bench-press", "下斜杠铃卧推", "Decline Bench Press", "decline-bench-press", "chest", "Chest", "Triceps,Shoulders", "Barbell", "weight_reps", false, "exercises/chest/decline-bench-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0051-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "躺在下斜凳上，双腿勾稳固定轴，肩胛骨收紧贴凳。\n握距略宽于肩，起杠后位于下胸正上方。\n沿垂直路径下放杠铃到下胸位置，手肘自然内收。\n发力推起时想象用下胸把杠铃顶起来，顶端不锁死手肘。\n下放吸气、推起呼气，全程躯干不要左右晃。", "双腿没有勾稳导致身体下滑：起杠前先确认腿固定好，重心不稳就降低重量。\n杠铃落到颈部或腹部方向：让杠铃始终对准下胸，下放时眼睛盯住落点。\n推起时耸肩用手臂代偿：肩胛骨全程下沉后收，推起时胸口主动发力。"),
        Seed("ex-chest-05", "器械推胸", "Machine Chest Press", "machine-chest-press", "chest", "Chest", "Triceps,Shoulders", "Machine", "weight_reps", false, "exercises/chest/machine-chest-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0066-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "调整座椅高度，让握把对准胸部中上位置，背部和头贴紧靠背。\n双脚踩实地面，双手握把后手肘约与胸同高。\n匀速向前推把手，感受胸肌收紧，推到手肘接近伸直但不锁死。\n停顿一秒后控制速度缓慢还原，让配重不重重落回。\n推出时呼气、还原时吸气，全程肩胛骨保持贴紧靠背。", "耸肩含胸用手臂猛推：先把肩胛骨后收下沉坐好，推的时候想象胸肌夹紧。\n还原时配重砸到底泄力：留一点余量不让配重完全落座，保持持续张力。\n座椅高度不对导致肩部代偿：调整到握把与胸中部平齐再开始。"),
        Seed("wg:pec-deck", "蝴蝶机夹胸", "Pec Deck", "pec-deck", "chest", "Chest", "Shoulders", "Machine", "weight_reps", false, "exercises/chest/pec-deck/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "调整座椅，让手肘或把手与胸口同高，背部头贴紧靠背。\n双手握住把手，手肘微弯固定，肩胛骨下沉后收。\n用胸肌发力把手臂向内合拢，想象两侧胸肌往中间夹紧。\n夹到最紧处停顿一秒，再控制速度缓慢打开回去。\n合拢时呼气、打开时吸气，打开到胸口有舒服拉伸感即可。", "打开幅度太大拉伤肩膀：打开到胸口有轻微拉伸就停，不必追求数值上的最大行程。\n耸肩用肩膀代偿发力：肩胛骨全程下沉固定，靠夹胸而不是抬手完成动作。\n夹合速度太快靠惯性：匀速控制配重，夹拢和还原都慢半拍。"),
        Seed("wg:cable-fly", "绳索夹胸", "Cable Fly", "cable-fly", "chest", "Chest", "Shoulders", "Cable", "weight_reps", false, "exercises/chest/cable-fly/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0048-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "站在双滑轮中间，滑轮调到与肩同高或略高，一手一把弓步站稳。\n手肘保持微弯固定角度，身体微微前倾，肩胛骨下沉。\n用胸肌发力把手臂沿弧线向内合拢，想象两边胸肌夹紧在胸前。\n顶端双手可以交叠，停一秒感受胸肌挤压，再缓慢打开回去。\n合拢时呼气、打开时吸气，全程让绳索张力不断开。", "手肘弯伸变成推的动作：手肘角度从头到尾锁死不变，只做夹合的弧线。\n身体大幅前后摆借力：弓步站稳收紧核心，躯干角度保持不变。\n回到起点时配重互撞泄力：打开到张力还在的位置就反向，不要让配重落座。"),
        Seed("ex-chest-03", "俯卧撑", "Push-up", "push-up", "chest", "Chest", "Triceps,Core", "Bodyweight", "bodyweight_reps", false, "exercises/chest/push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0077-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双手撑地略宽于肩，手指朝前，从头到脚保持一条直线。\n收紧腹部和臀部，让核心像一块板一样刚性稳定。\n手肘约45度角弯曲，身体整体下降到胸口接近地面。\n用胸肌发力把身体推起，顶端手肘不锁死。\n下降时吸气、推起时呼气，全程身体不塌腰不撅臀。", "塌腰撅臀核心松掉：收紧腹部和臀部，想象身体是一块平板不折断。\n手肘完全外展贴平肩膀：手肘与躯干保持约45度，保护肩关节。\n只下去一半没到位：降到胸口快贴地再推起，幅度做满。"),
        Seed("wg:weighted-push-up", "负重俯卧撑", "Weighted Push-up", "weighted-push-up", "chest", "Chest", "Triceps,Core", "Bodyweight", "weight_reps", false, "exercises/chest/weighted-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "背上放置负重（如背包或负重板），先双手撑地摆好标准俯卧撑姿势。\n从头到脚保持一条直线，核心收紧到能稳住额外重量。\n手肘约45度角缓慢下降，胸口接近地面但不贴死。\n胸肌发力把负重整体推起，身体各部位同时离地。\n下降吸气、推起呼气，负重位置不能滑动影响重心。", "负重摆放位置偏移导致重心歪斜：把负重固定在上背中部，先空手调整好姿势再加载。\n重量太大导致塌腰：从轻负重开始，核心撑不住就减重，不硬撑。\n动作变形只追求数量：每一下都保持标准幅度，做不了就减重不凑数。"),
        Seed("wg:overhead-press", "站姿杠铃推举", "Overhead Press", "overhead-press", "shoulders", "Shoulders", "Triceps", "Barbell", "weight_reps", false, "exercises/shoulders/overhead-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与肩同宽站立，收紧臀腹，杠铃置于锁骨前方，手腕叠在肘部正上方\n将杠铃沿接近垂直的路径向上推起，过头时头部微微后移让杠铃通过，推至手臂在头顶完全伸直\n顶端肩胛向上锁定，杠铃与地面垂直，重心落在足中\n下放时控制速度回到锁骨位置，全程躯干不晃动\n推起时呼气，下放时吸气，核心持续收紧", "腰部过度反弓把推举变成上斜推：收紧臀部与腹肌，肋骨下沉，保持腰椎中立，必要时站距略窄并减轻重量\n杠铃绕头前推、轨迹前后晃动：想象把杠铃直线上推，头部让位而非身体后仰\n耸肩借力、肘部先于手腕前伸：保持肩胛下沉推起，手腕始终叠在肘部上方"),
        Seed("ex-shoulder-01", "坐姿哑铃肩推", "Dumbbell Seated Shoulder Press", "seated-dumbbell-press", "shoulders", "Shoulders", "Triceps", "Dumbbell", "weight_reps", false, "exercises/shoulders/seated-dumbbell-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐于有靠背的凳上，背部贴紧靠背，双脚踩实地面，哑铃举至肩侧，掌心朝前\n肘部略低于肩或与肩同高，垂直向上推起哑铃，顶端两哑铃接近但不相碰\n顶端手臂伸直但不锁死肘关节，肩胛保持稳定下沉\n下放时控制到大臂与地面平行或略低，肘部不过分沉到身体以下\n推起呼气，下放吸气，肋骨收紧不外翻", "背部离靠背、腰椎反弓：调高靠背并主动贴紧，收腹保持肋骨下沉，重量过大时先减重\n下放过深导致肩关节前侧受压：控制到肘约90度即可，肩有牵拉感即止\n用胸部耸肩代替肩部发力：肘向外侧约45度引导，推起时想象肘尖向上顶"),
        Seed("ex-shoulder-04", "阿诺德推举", "Arnold Press", "arnold-press", "shoulders", "Shoulders", "Triceps", "Dumbbell", "weight_reps", false, "exercises/shoulders/arnold-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐姿背贴靠背，双手持哑铃举至肩前，掌心朝向身体，肘部在手腕下方\n边向上推边旋转手腕，推到顶端时掌心完全朝前，手臂伸直\n顶端停顿感受三角肌收紧，肩胛保持下沉稳定\n下放同时反向旋转，回到掌心相对身体的起始位，全程连贯\n推起呼气，下放吸气", "旋转过快变成甩动：旋转与推起同步匀速进行，重点在控制而非重量\n腰背反弓、肋骨外翻：贴紧靠背、收腹，重量选择能完成12次内的适中哑铃\n肘部过度前移、肩峰撞击感：肘保持在手腕正下方轨迹上，出现疼痛立即停止并改用普通推举"),
        Seed("ex-shoulder-02", "哑铃侧平举", "Lateral Raise", "lateral-raise", "shoulders", "Shoulders", "Upper Back", "Dumbbell", "weight_reps", false, "exercises/shoulders/lateral-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0018-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "站立微屈膝收腹，哑铃垂于体侧，肘部微屈并保持固定角度\n以肘部为引导向侧上方抬起，肘先动、手腕跟随，抬至大臂与地面平行或略低\n想象手背沿墙面滑上，肩胛保持下沉不耸肩\n下放用三角肌控制，缓慢回到体侧，不停留在底部完全松弛\n抬起呼气，下放吸气，颈部放松", "耸肩借力用斜方肌代偿：肩胛主动下沉，抬臂前先沉肩，重量减轻至能不耸肩完成\n甩动惯性把哑铃抛上去：放慢抬起速度，可用背部贴墙辅助检测身体是否晃动\n抬得过高、手腕高于肘部：抬到大臂平行地面即可，保持肘略高于腕，避免肩峰挤压"),
        Seed("wg:cable-lateral-raise", "绳索侧平举", "Cable Lateral Raise", "cable-lateral-raise", "shoulders", "Shoulders", "Upper Back", "Cable", "weight_reps", false, "exercises/shoulders/cable-lateral-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧对绳索架站立，绳索滑轮调至低位，外侧手握把手，身体略离开滑轮保持张力\n肘微屈固定，以肘为引导向侧上方拉起，抬至大臂与地面平行\n全程绳索保持张力，底部不完全卸力，肩胛下沉不耸肩\n下放缓慢控制，感受三角肌中束持续受力\n拉起呼气，下放吸气，躯干稳定不转动借力", "身体向后仰或转体借力：减轻重量，收腹站稳，可用另一手扶住架子固定躯干\n耸肩、斜方肌上束代偿：先沉肩再起肘，注意力放在肘尖而非手\n下放过快失去张力：控制在2-3秒下放，底部保留约20%行程不停死"),
        Seed("wg:front-raise", "哑铃前平举", "Front Raise", "front-raise", "shoulders", "Shoulders", "Chest", "Dumbbell", "weight_reps", false, "exercises/shoulders/front-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0033-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "站立收腹，哑铃垂于大腿前侧，掌心朝向身体或相对\n肘微屈固定，以肩部前束发力直臂前抬至与肩同高，肘略高于腕\n顶端停顿一秒感受前束收缩，躯干不后仰\n下放缓慢控制回到起始位，全程身体稳定\n抬起呼气，下放吸气", "身体后仰甩起哑铃：减轻重量，收腹挺胸固定躯干，必要时背靠墙练习\n耸肩借助斜方肌：肩胛下沉，抬臂时肩膀远离耳朵\n抬过头顶造成肩峰挤压：抬至与肩同高即可，多数推举动作已充分刺激前束，前平举用轻重量即可"),
        Seed("wg:rear-delt-fly", "后束飞鸟", "Rear Delt Fly", "rear-delt-fly", "shoulders", "Rear Delts", "Upper Back", "Dumbbell", "weight_reps", false, "exercises/shoulders/rear-delt-fly/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与肩同宽，屈髋俯身至上身接近与地面平行，背部平直，哑铃垂于肩下\n肘微屈固定，肩胛先向脊柱方向收，再以肘为引导向两侧打开\n抬至大臂与背部同高或略高，手腕放松略低于肘\n顶端停顿感受后束挤压，下放缓慢控制\n打开时呼气，下放时吸气，颈部与地面平行不抬头", "弓背或用腰部撑起身体：屈髋而非弯腰，背部平直，可在斜凳上俯卧支撑完成\n耸肩用斜方肌代偿：肩胛先向脊柱收再抬臂，重量减轻，肘略高于腕\n幅度过大向上甩：抬至与肩平即停，重点在顶端挤压与下放控制"),
        Seed("wg:reverse-pec-deck", "反向蝴蝶机", "Reverse Pec Deck", "reverse-pec-deck", "shoulders", "Rear Delts", "Upper Back", "Machine", "weight_reps", false, "exercises/shoulders/reverse-pec-deck/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "调节座椅与把手位置，坐姿胸口贴紧靠垫，把手在肩前方\n保持手臂微屈，用后束发力将把手向两侧后方打开，想象肘尖向后画弧\n打开至手臂与肩同高略靠后，顶端肩胛向脊柱收紧停顿\n缓慢回放把手但保留张力，不完全卸力\n打开呼气，回放吸气，全程胸贴靠垫躯干不后仰", "躯干后仰借助体重：减轻配重，胸口始终贴紧靠垫\n耸肩、上斜方代偿：肩膀下沉远离耳朵，注意力集中在肘尖后移\n回放过快卸力：用2-3秒回放，配重片不完全落回"),
        Seed("ex-shoulder-03", "面拉", "Face Pull", "face-pull", "back", "Upper Back", "Rear Delts,Shoulders", "Cable", "weight_reps", false, "exercises/back/face-pull/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "将绳索调至与脸同高，双手宽握绳索两端，向后退一小步让绳索保持张力。\n起始姿势：脊柱中立、核心收紧、身体略微后倾并保持稳定。\n发力时肩胛先向后收紧，再把绳索拉向额头方向，双手向两侧分开，手肘略高于肩。\n终点让肘部接近或超过身体平面，感受上背与肩后束收紧，停顿一秒。\n缓慢还原，肩胛保持控制，不要让身体前后晃动借力。", "手肘过低、只用手臂拉：应先收肩胛，肘部引导并保持高于肩的轨迹。\n重量过大导致身体后仰摇摆：减轻重量，让躯干固定、肩胛主导发力。"),
        Seed("wg:upright-row", "直立划船", "Upright Row", "upright-row", "shoulders", "Shoulders", "Upper Back,Biceps", "Barbell", "weight_reps", false, "exercises/shoulders/upright-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0014-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双手握杠略窄于肩或与肩同宽，杠铃垂于大腿前，肩胛下沉\n肘部向上向外引导，沿身体前侧将杠铃拉至胸口上方位置\n肘部始终高于手腕，顶端停顿感受肩侧与上背收缩\n缓慢下放回起始位，全程杠铃贴近身体\n拉起呼气，下放吸气", "握距过窄、肘高过肩导致肩峰撞击：握距至少与肩同宽，拉至胸口高度即止，肩痛者改用绳索侧平举\n手腕内扣、腕部受力：保持手腕中立，肘为发力点，必要时用EZ杆\n耸肩弓背借力：减轻重量，沉肩挺胸，全程核心收紧"),
        Seed("ex-back-06", "硬拉", "Deadlift", "deadlift", "core", "Posterior Chain", "Back,Grip", "Barbell", "weight_reps", false, "exercises/core/deadlift/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0099-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双脚与髋同宽站立，杠铃贴近胫骨，双手略宽于双腿握杠\n屈髋俯身、背部平直，肩胛收紧，膝关节约与小腿呈自然角度\n蹬地起立，髋膝同步伸展，杠铃全程贴身上行，臀部收紧至站直\n下放时先屈髋后屈膝，控制杠铃沿原路贴近身体落回地面\n全程保持腰椎中立位，用腿部和臀部发力，不要用腰把重量拉起来", "弓背或过度反弓腰椎起杠，腰背部代偿受伤风险高\n杠铃离身体太远，力臂变长导致腰椎压力骤增\n起杠瞬间猛拉或耸肩，应先收紧再整体发力"),
        Seed("wg:romanian-deadlift", "罗马尼亚硬拉", "Romanian Deadlift", "romanian-deadlift", "legs", "Hamstrings", "Glutes,Lower Back", "Barbell", "weight_reps", false, "exercises/legs/romanian-deadlift/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0118-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双脚与髋同宽站立，双手握杠铃贴大腿前侧，肩胛下沉挺胸收腹。\n保持背部平直，以髋部为铰链向后推臀，杠铃沿大腿滑向膝盖下方。\n感到腘绳肌被充分拉伸后，用臀部与腘绳肌发力站直。\n顶端收紧臀部，膝盖保持微屈角度不变。", "弓背或腰部反弓下放，腰椎失去中立位，应用轻重量重新学习髋铰链。\n膝盖过度前移变成深蹲动作，腘绳肌张力消失。\n下放过深导致杠铃离身或腰部代偿，应停在自己柔韧性的极限处。"),
        Seed("ex-back-05", "杠铃划船", "Barbell Row", "barbell-row", "back", "Back", "Biceps,Rear Delts", "Barbell", "weight_reps", false, "exercises/back/barbell-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0026-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双脚与髋同宽，膝微屈，髋部向后做屈髋俯身至上身约 30-45 度，背部平直中立。\n双手略宽于肩握杠，手臂自然下垂，肩胛先向后下方收紧启动。\n肘部贴近身体方向把杠铃拉向腹部或下胸位置，感受背部收缩。\n顶端停顿一秒，缓慢下放，全程腰背保持中立，杠铃始终有控制。\n呼吸配合：拉起呼气、下放吸气，避免憋气发力。", "弓腰或塌腰：屈髋角度不够或核心无力，应减轻重量、收紧核心、保持脊柱中立。\n用爆发力甩起杠铃、身体大幅上下起伏：动作应由肩胛和肘部引导，控制节奏。\n只用手臂拉：先收肩胛再屈肘，让背部主导发力。"),
        Seed("wg:t-bar-row", "T 杠划船", "T-Bar Row", "t-bar-row", "back", "Back", "Biceps,Rear Delts", "Machine", "weight_reps", false, "exercises/back/t-bar-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0029-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双脚站稳、屈膝微屈髋，胸部轻贴胸垫（如有），双手握住把手，背部平直。\n肩胛先向后收紧，再用肘部引导把重量拉向上腹或胸口位置。\n顶端感受背部挤压一秒，缓慢有控制地下放。\n全程保持核心收紧，避免用腰部代偿摆动。\n握距和把位选择以手腕舒适、肩部无挤压感为准。", "躯干过度抬升或晃动借力：固定身体，用肩胛和肘部引导拉起。\n耸肩、肩胛未收紧就拉：先做肩胛后收，再屈肘发力。"),
        Seed("wg:dumbbell-bent-over-row", "俯身哑铃划船", "Dumbbell Bent Over Row", "dumbbell-bent-over-row", "back", "Back", "Biceps,Rear Delts", "Dumbbell", "weight_reps", false, "exercises/back/dumbbell-bent-over-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与肩同宽，屈髋俯身至上身接近与地面成 30-45 度，双手各持一哑铃自然下垂。\n肩胛先向后下方收紧，肘部贴近身体两侧把哑铃拉向腹部方向。\n顶端挤压背部一秒，缓慢下放至手臂接近伸直。\n全程腰背平直中立，核心收紧，不要抬头或低头过度。\n呼吸配合：拉起呼气、下放吸气。", "俯身时弓背：屈髋代替弯腰，臀部后坐、脊柱保持中立。\n重量过大甩起哑铃：减轻重量，控制起落速度，肩胛先行。"),
        Seed("ex-back-04", "单臂哑铃划船", "One-Arm Dumbbell Row", "one-arm-dumbbell-row", "back", "Back", "Biceps", "Dumbbell", "weight_reps", false, "exercises/back/one-arm-dumbbell-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "单手握哑铃，另一侧手膝支撑在平凳上，支撑侧手臂伸直、背部平直，身体接近平行地面。\n持铃手臂自然下垂，肩胛先向下向后收紧（让肩胛离开下沉状态再收起）。\n肘部贴近身体把哑铃拉向髋部方向，感受背部收缩，顶端停顿。\n缓慢下放至充分伸展，让背部被轻轻拉开后再拉下一次。\n躯干保持稳定，不要向拉起一侧过度旋转。", "躯干过度旋转借力：保持髋部朝前、躯干稳定，动作幅度由背部完成。\n只抬手臂不收肩胛：每次先做肩胛后收再屈肘。"),
        Seed("wg:chest-supported-row", "胸托划船", "Chest Supported Row", "chest-supported-row", "back", "Back", "Biceps,Rear Delts", "Machine", "weight_reps", false, "exercises/back/chest-supported-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "调整座椅和胸垫高度，让胸口完全贴合胸垫、双脚踩实，双手握把手。\n肩胛先向后下方收紧，再用肘部引导把把手拉向腹部位置。\n顶端背部挤压一秒，缓慢还原，手臂伸展但肩胛仍保持控制。\n全程胸口不离开胸垫，腰背保持自然中立。\n选择手腕舒适的握法，避免肩部挤压不适。", "胸口离开胸垫、抬胸借力：减轻重量，保持贴合，靠背部发力。\n动作幅度过小、只用半程：充分伸展再充分收缩，全程控制。"),
        Seed("ex-back-03", "坐姿绳索划船", "Seated Cable Row", "seated-row", "back", "Back", "Biceps,Rear Delts", "Cable", "weight_reps", false, "exercises/back/seated-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0025-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "坐稳后双脚踩实、膝微屈，脊柱中立，手臂伸直握住把手，身体自然挺直。\n肩胛先向后下方收紧，再把把手拉向腹部，肘部贴近身体后滑。\n顶端背部挤压一秒，缓慢前送还原，让背部被拉开但不弓腰塌背。\n躯干前后摆动幅度保持很小，靠肩胛和手臂完成行程。\n呼吸配合：拉回呼气、前送吸气。", "躯干大幅前后摇摆借力：减轻重量，固定躯干，动作由肩胛驱动。\n耸肩、只用手臂拉：先收肩胛降肩带，再屈肘发力。"),
        Seed("wg:machine-row", "器械划船", "Machine Row", "machine-row", "back", "Back", "Biceps", "Machine", "weight_reps", false, "exercises/back/machine-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "调整座椅高度，使把手约在胸口高度、胸口贴紧靠垫，双脚踩实地面。\n握好把手后肩胛先向后下方收紧，再用肘部引导把手向腹部方向拉。\n顶端背部挤压一秒，缓慢还原至手臂伸展。\n全程腰背贴靠垫或保持中立，不要弓背或塌腰。\n用适中的幅度和速度，感受背部发力而非手臂用力。", "身体后仰离开靠垫借力：减轻重量，保持躯干贴紧靠垫。\n只做半程、收缩不充分：充分伸肩胛再充分收肩胛，完成完整行程。"),
        Seed("ex-back-02", "高位下拉", "Lat Pulldown", "lat-pulldown", "back", "Lats", "Biceps", "Cable", "weight_reps", false, "exercises/back/lat-pulldown/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0093-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "大腿固定在挡垫下，双手略宽于肩正握横杆，坐直、脊柱中立、胸略微挺起。\n肩胛先下沉后收（想象把肩胛骨插进后裤兜），肘部向下向后引导拉杆。\n把横杆拉向锁骨附近，同时让肘部靠近身体两侧，感受背阔肌收缩。\n顶端停顿一秒，缓慢向上还原，让背部充分伸展但保持肩胛有控制。\n躯干保持稳定，仅允许轻微后倾，避免大幅摆动借力。", "身体大幅后仰、用腰腹甩动借力：减轻重量，躯干固定，肘部引导。\n只用手臂拉、肩胛未先下沉：先做肩胛下沉后收，再屈肘拉杆。\n拉到颈后：拉向锁骨/上胸位置，颈后下拉对肩部压力大且收益不多。"),
        Seed("wg:close-grip-lat-pulldown", "窄握高位下拉", "Close-Grip Lat Pulldown", "close-grip-lat-pulldown", "back", "Lats", "Biceps", "Cable", "weight_reps", false, "exercises/back/close-grip-lat-pulldown/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0096-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "采用窄握（手距约与肩同宽或略窄），大腿固定挡垫下，坐直脊柱中立。\n肩胛先下沉后收，肘部向下贴近身体两侧引导拉杆。\n把横杆拉向锁骨位置，重点感受背阔肌外侧收缩，顶端停顿。\n缓慢还原至手臂充分伸展，肩胛保持控制不上耸。\n全程躯干稳定，避免后仰借力。", "手握过窄导致手腕与肘部受压：选择肩宽或略窄的舒适握距。\n只用手臂发力：先收肩胛，肘部引导向下，让背阔肌主导。"),
        Seed("wg:straight-arm-pulldown", "直臂下压", "Straight-Arm Pulldown", "straight-arm-pulldown", "back", "Lats", "Core", "Cable", "weight_reps", false, "exercises/back/straight-arm-pulldown/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0092-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "面向绳索站立，双臂伸直、略前倾固定躯干，正握直杆或绳索，手臂与肩同高。\n核心收紧，保持肘部角度基本不变（微屈即可），肩胛先下沉。\n以肩为轴把杆沿弧线向下压至大腿前侧，感受背阔肌全程收缩。\n顶端停顿一秒，缓慢有控制地向上还原，让背阔肌被拉开。\n全程肘部不弯、躯干不晃，发力来自肩关节伸展。", "屈肘变成屈臂下压：保持肘角基本固定，幅度由肩关节完成。\n躯干大幅俯身晃动：固定身体角度，减小重量，专注背阔肌张力。"),
        Seed("ex-back-01", "引体向上", "Pull-up", "pull-up", "back", "Lats", "Biceps,Core", "Bodyweight", "bodyweight_reps", false, "exercises/back/pull-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0087-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "正握横杆略宽于肩，双脚离地、身体悬挂，肩胛先主动下沉收紧（不要死挂放松）。\n肘部向下向后引导，把身体向上拉至下巴过杆，感受背阔肌发力。\n顶端停顿一秒，缓慢下放至手臂接近伸直，肩胛保持控制。\n核心收紧、双腿可交叉或微屈，避免身体摆动借力。\n呼吸配合：拉起呼气、下放吸气。", "晃腿蹬身借力：收紧核心固定下半身，必要时做离心或辅助版本。\n肩胛死挂不激活：每次先做肩胛下沉再拉，保护肩部并提高背阔肌参与。\n只拉半程：下巴过杆、下放到接近伸直，完成全程。"),
        Seed("wg:assisted-pull-up", "辅助引体向上", "Assisted Pull-up", "assisted-pull-up", "back", "Lats", "Biceps", "Machine", "assisted_bodyweight", false, "exercises/back/assisted-pull-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "膝或脚放在辅助垫上，双手正握略宽于肩，悬挂时肩胛先下沉收紧。\n肘部向下引导把身体拉起至下巴过杆，动作节奏与自重引体一致。\n顶端停顿，缓慢下放至手臂接近伸直。\n核心收紧，身体保持垂直稳定，不借助身体摆动。\n随着力量提升逐步减少辅助重量，向标准引体过渡。", "依赖过强辅助、下放过快：控制还原速度，逐步降低辅助量。\n身体摆动借力：固定骨盆和双腿，专注肘部引导拉起。"),
        Seed("wg:weighted-pull-up", "负重引体向上", "Weighted Pull-up", "weighted-pull-up", "back", "Lats", "Biceps", "Bodyweight", "weight_reps", false, "exercises/back/weighted-pull-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "确认能标准完成 8 次以上自重引体后再加负重，负重物（腰带挂铃片等）固定牢靠。\n悬挂时肩胛先下沉收紧，肘部引导把身体拉至下巴过杆。\n顶端停顿一秒，缓慢下放至手臂接近伸直，全程控制节奏。\n核心收紧防止负重摆动，躯干保持垂直。\n每次加重幅度保守，宁可少加不影响动作质量。", "负重过大破坏动作标准：以动作质量为先，减重到全程可控。\n下放失控、靠惯性甩起：控制离心阶段，顶底两端都保持张力。"),
        Seed("wg:chin-up", "反握引体向上", "Chin-up", "chin-up", "arms", "Biceps", "Lats", "Bodyweight", "bodyweight_reps", false, "exercises/arms/chin-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0090-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双手与肩同宽反握单杠，身体自然悬垂，肩胛先下沉收紧\n呼气屈肘把身体向上拉，目标让下巴过杠，肘部朝身体方向下压\n顶端停顿片刻，缓慢下放至手臂接近伸直，保持肩胛不松掉\n全程大臂贴近躯干，用二头带动，不要靠蹬腿晃身借力\n按能力完成规定次数，下放到底再进行下一次", "靠蹬腿摆动身体借力上拉，失去对二头的刺激\n下放不彻底或肩胛松塌，幅度不足且肩部易代偿受伤\n耸肩缩脖子，让斜方肌代偿二头发力"),
        Seed("wg:shrug", "杠铃耸肩", "Barbell Shrug", "shrug", "back", "Upper Back", "Forearms", "Barbell", "weight_reps", false, "exercises/back/shrug/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手略宽于肩握杠铃自然站立，手臂伸直、肩部下沉为起点。\n肩胛向上耸起靠近耳朵方向，顶端停顿挤压一秒。\n缓慢下放还原，让斜方肌被充分拉开再耸下一次。\n全程手臂不弯、肘部不参与，发力只来自肩带上提。\n脊柱保持中立，核心收紧，头部不要前探。", "用绕环或爆发甩动代替直上直下：肩胛垂直上提下放，控制节奏。\n重量过大只用半程小幅颠动：减轻重量，做到完整幅度并在顶端停顿。"),
        Seed("ex-leg-01", "杠铃深蹲", "Squat", "squat", "legs", "Quads", "Glutes,Core", "Barbell", "weight_reps", false, "exercises/legs/squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0122-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "杠铃置于斜方肌上部，双手握距略宽于肩，双脚与肩同宽站立。\n核心收紧像被击打前一样绷紧，吸气后同时屈髋屈膝下蹲。\n下蹲至大腿与地面平行或更低，膝盖与脚尖方向一致。\n脚跟与脚掌中部均匀发力蹬地站起，髋膝同步伸直。\n顶端呼气，全程保持躯干刚性。", "膝盖内扣，与脚尖方向不一致，应主动把膝盖对准脚尖方向。\n核心松弛导致躯干前倾或弓腰，下蹲前必须先绷紧腹压。\n髋膝不同步、脚跟离地或重心移到脚尖。"),
        Seed("wg:front-squat", "前蹲", "Front Squat", "front-squat", "legs", "Quads", "Core,Glutes", "Barbell", "weight_reps", false, "exercises/legs/front-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0138-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "肘部抬起与地面平行，杠铃架在三角肌前束上，指尖扣住杠铃保持稳定。\n双脚与肩同宽，核心收紧，肘部全程保持抬高。\n屈髋屈膝同步下蹲至大腿平行或更低，躯干尽量竖直。\n中前脚掌发力站起，髋膝同步伸直，肘部不塌。", "肘部下垂导致杠铃前滚，应始终把肘尖抬向正前方。\n膝盖内扣或核心松弛，膝盖必须与脚尖同向，腹压全程绷紧。\n下蹲时髋膝不同步、躯干过度前倾。"),
        Seed("wg:hack-squat", "哈克深蹲", "Hack Squat", "hack-squat", "legs", "Quads", "Glutes", "Machine", "weight_reps", false, "exercises/legs/hack-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0123-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "肩背贴紧靠垫，双脚置于踏板中部略前，与肩同宽。\n解开安全销，屈膝下蹲至大腿接近平行，膝盖与脚尖同向。\n脚掌均匀发力蹬起，顶端接近伸直但不锁死膝盖。\n下落时控制速度，膝盖保持微屈不锁死。", "下蹲过深导致骨盆翻转、腰部离开靠垫。\n膝盖内扣，应始终与脚尖同向。\n蹬起时用爆发力猛弹而非控制发力。"),
        Seed("ex-leg-04", "腿举", "Leg Press", "leg-press", "legs", "Quads", "Glutes,Hamstrings", "Machine", "weight_reps", false, "exercises/legs/leg-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0127-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "头背臀贴紧座椅，双脚置于踏板与肩同宽。\n解开安全销，屈膝下放至大腿接近腹部，膝盖对准脚尖方向。\n用脚掌均匀发力蹬起，顶端膝盖接近伸直但不锁死。\n下放时保持控制，腰部始终贴住靠垫。", "下放过深导致骨盆离开靠垫、腰部蜷曲受伤。\n膝盖完全锁死或内扣。\n用手扶膝盖借力，动作幅度过大过快失控。"),
        Seed("wg:bulgarian-split-squat", "保加利亚分腿蹲", "Bulgarian Split Squat", "bulgarian-split-squat", "legs", "Quads", "Glutes,Core", "Dumbbell", "weight_reps", false, "exercises/legs/bulgarian-split-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "后脚脚背搭在凳上，前脚向前迈出约一大步距离。\n核心收紧，身体垂直下沉，前膝与脚尖同向。\n下蹲至前大腿接近平行地面，重心压在前脚掌与脚跟之间。\n前腿发力蹬地站起，全程躯干保持正直。", "前膝盖内扣或超过脚尖过多，应保持膝盖对准脚尖方向。\n躯干过度前倾、核心松弛，重心过多压在后腿。\n步距过近导致膝盖压力过大。"),
        Seed("wg:walking-lunge", "行走箭步蹲", "Walking Lunge", "walking-lunge", "legs", "Quads", "Glutes,Hamstrings", "Dumbbell", "weight_reps", false, "exercises/legs/walking-lunge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0121-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双手持哑铃于体侧，核心收紧站直。\n向前迈一大步，前后脚同时屈膝下沉，躯干保持正直。\n后膝接近地面但不触地，前膝与脚尖同向。\n前腿发力蹬地站起，迈出另一条腿继续前行。", "步幅过小导致前膝超过脚尖过多。\n躯干前倾或左右摇晃，核心应全程绷紧。\n膝盖落地磕碰，应控制下落速度。"),
        Seed("wg:step-up", "登阶", "Step-Up", "step-up", "legs", "Quads", "Glutes", "Dumbbell", "weight_reps", false, "exercises/legs/step-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0137-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "选择与小腿至膝盖高度相当的凳子，单脚全脚掌踩上。\n核心收紧，前腿发力把身体蹬上凳面，膝盖与脚尖同向。\n站直顶端收紧臀部，另一条腿轻触凳面保持控制。\n缓慢下放回到起始位，完成规定次数后换腿。", "后腿蹬地借力，力量应主要来自踩凳腿。\n躯干前倾塌腰，核心应保持收紧。\n下落时失控砸落，应有控制地下放。"),
        Seed("wg:leg-extension", "腿屈伸", "Leg Extension", "leg-extension", "legs", "Quads", "", "Machine", "weight_reps", false, "exercises/legs/leg-extension/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0142-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "坐姿调整靠背与滚轴位置，滚轴置于小腿前侧踝关节上方。\n双手握住把手，背部贴紧靠垫，膝盖与机器转轴对齐。\n伸直双腿至顶端停顿一秒，感受股四头肌收缩。\n缓慢下放还原但不让配重片完全落底。", "腿部完全放松让配重砸落，应全程控制速度。\n躯干后仰借力，臀部离开座椅。\n重量过大导致动作幅度缩小。"),
        Seed("wg:leg-curl", "腿弯举", "Leg Curl", "leg-curl", "legs", "Hamstrings", "Calves", "Machine", "weight_reps", false, "exercises/legs/leg-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0117-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "俯卧或坐姿调整好滚轴位置，使其贴住小腿后侧踝上方。\n双手握紧把手固定躯干，髋部贴紧靠垫。\n屈膝把滚轴拉向臀部，顶端停顿一秒收紧腘绳肌。\n缓慢放回，全程保持控制。", "髋部抬起借力，臀腰离垫说明重量过大。\n下放失控，应缓慢还原保持张力。\n动作幅度过小，未充分伸直膝盖。"),
        Seed("wg:seated-leg-curl", "坐姿腿弯举", "Seated Leg Curl", "seated-leg-curl", "legs", "Hamstrings", "Calves", "Machine", "weight_reps", false, "exercises/legs/seated-leg-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0119-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "坐进座椅，大腿被压板固定，滚轴贴住小腿后侧踝上方。\n双手握住把手，上身挺直贴靠背。\n屈膝把小腿向下向后拉，顶端停顿收紧腘绳肌。\n缓慢放回起始位，不让配重片砸落。", "大腿离开压板上抬借力。\n下放速度过快失去张力。\n重量过大导致动作幅度不完整。"),
        Seed("wg:hip-thrust", "杠铃臀推", "Hip Thrust", "hip-thrust", "legs", "Glutes", "Hamstrings", "Barbell", "weight_reps", false, "exercises/legs/hip-thrust/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "肩胛上背部靠在凳边，杠铃压在髋部，双脚踩实与肩同宽。\n核心收紧，下巴微收，臀部发力向上顶起。\n顶端躯干与大腿接近平行地面，膝盖约90度，收紧臀部一秒。\n有控制地下放回起始位，臀部不完全落地。", "腰椎过伸代替髋伸，顶端应以臀部收紧为终点而非后仰腰。\n脚位过远导致腘绳肌代偿过多。\n杠铃压到腹部或肋骨，应垫好护垫压在髋部。"),
        Seed("wg:glute-bridge", "臀桥", "Glute Bridge", "glute-bridge", "legs", "Glutes", "Hamstrings", "Bodyweight", "bodyweight_reps", false, "exercises/legs/glute-bridge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0109-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧屈膝，双脚踩实与髋同宽，脚跟距臀约一脚掌。\n核心收紧，臀部发力把髋向上顶起。\n顶端肩髋膝呈一条直线，收紧臀部一秒。\n缓慢下放，臀部轻触地面即再次上顶。", "腰椎过伸顶端后仰，应靠臀部收紧控制顶端位置。\n双脚过远导致腘绳肌主导发力。\n下放过快失去控制。"),
        Seed("wg:good-morning", "早安式", "Good Morning", "good-morning", "legs", "Hamstrings", "Glutes,Lower Back", "Barbell", "weight_reps", false, "exercises/legs/good-morning/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0101-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "杠铃置于斜方肌上部，双脚与肩同宽，膝盖微屈固定。\n核心收紧，以髋为铰链向后推臀，躯干前倾至接近与地面平行。\n保持背部平直，腘绳肌充分拉伸后发力站直。\n顶端收紧臀部，膝盖角度全程不变。", "弓背下俯，腰椎失去中立位，应用轻重量练习。\n膝盖随下俯而屈伸，应保持膝盖角度固定。\n幅度过大导致腰部代偿。"),
        Seed("wg:standing-calf-raise", "站姿提踵", "Standing Calf Raise", "standing-calf-raise", "legs", "Calves", "", "Machine", "weight_reps", false, "exercises/legs/standing-calf-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0282-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "前脚掌踩在踏板上，脚跟悬空，肩部顶住垫肩。\n核心收紧，腿伸直但不锁死膝盖。\n踮起脚尖到最高点，停顿一秒充分收缩小腿。\n缓慢下放脚跟至最低点，充分拉伸小腿后再上提。", "幅度过小只用弹跳完成，应做到全幅度。\n膝盖弯曲借力，应保持腿基本伸直。\n下放过快失去拉伸效果。"),
        Seed("wg:seated-calf-raise", "坐姿提踵", "Seated Calf Raise", "seated-calf-raise", "legs", "Calves", "", "Machine", "weight_reps", false, "exercises/legs/seated-calf-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0279-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "坐姿，前脚掌踩踏板，膝盖约90度，垫板压在大腿上。\n脚跟下放至最低点，充分拉伸小腿。\n踮起脚尖到最高点停顿一秒，收缩小腿。\n缓慢下放还原，全程控制节奏。", "用身体顶起垫板借力，手不应参与发力。\n幅度不足，脚跟未充分下放或未踮到最高。\n节奏过快靠弹震完成。"),
        Seed("ex-arm-02", "哑铃弯举", "Bicep Curl", "bicep-curl", "arms", "Biceps", "Forearms", "Dumbbell", "weight_reps", false, "exercises/arms/bicep-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0224-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "站立双脚与肩同宽，双手各持哑铃垂于体侧，掌心朝前\n大臂贴紧躯干固定不动，呼气屈肘将哑铃弯举至肩前\n顶端挤压二头一秒，缓慢下放至手臂接近伸直\n两侧交替或同时进行，保持躯干正直不晃动", "大臂随动作前后摆动，变成肩部推举而非弯举\n身体后仰、腰部代偿甩起哑铃，借力过多\n下放过快失去离心控制，效果打折且易伤肘"),
        Seed("ex-arm-05", "锤式弯举", "Hammer Curl", "hammer-curl", "arms", "Biceps", "Forearms", "Dumbbell", "weight_reps", false, "exercises/arms/hammer-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0227-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "站立双手各持哑铃垂于体侧，掌心相对呈锤握姿势\n大臂固定贴身，呼气屈肘将哑铃沿身体前侧弯举至肩高\n顶端停顿感受肱肌与前臂发力，缓慢下放还原\n全程手腕保持中立，不外翻不内扣", "手腕随动作前后晃动或翻腕，增加腕部压力\n身体摇摆甩起哑铃，大臂离开躯干\n幅度过小，只做半程导致刺激不完整"),
        Seed("wg:preacher-curl", "牧师凳弯举", "Preacher Curl", "preacher-curl", "arms", "Biceps", "Forearms", "Machine", "weight_reps", false, "exercises/arms/preacher-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0236-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "调整牧师凳坐垫高度，大臂和腋窝完全贴合斜垫\n双手握杠或哑铃，手臂在垫上接近伸直但不锁死\n呼气屈肘将重量弯举至顶端，顶峰挤压二头\n缓慢下放至手臂几乎伸直，让二头充分拉长再进行下一次", "腋窝离开垫子、大臂抬起，变成肩部借力\n下放到底部突然卸力被重量拉扯，肘部易受伤\n重量选太大，靠手腕翻折和身体后仰完成动作"),
        Seed("wg:cable-curl", "绳索弯举", "Cable Curl", "cable-curl", "arms", "Biceps", "Forearms", "Cable", "weight_reps", false, "exercises/arms/cable-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0212-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "将绳索滑轮调至低位，双手握杆/绳柄，向后退一步使绳索保持张力\n大臂固定于躯干两侧，呼气屈肘弯举至胸口高度\n顶端挤压二头一秒，缓慢放回起始位置但不停留卸力\n全程肘部位置不动，身体正直不后仰", "后退太远身体后倾，用重心对抗绳索拉力\n肘部随动作前移，大臂不再固定\n在底端完全放松停留，丢失绳索的持续张力"),
        Seed("wg:reverse-curl", "反握弯举", "Reverse Curl", "reverse-curl", "arms", "Forearms", "Biceps", "Barbell", "weight_reps", false, "exercises/arms/reverse-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站立双手与肩同宽正握（掌心朝下）握杠垂于体前\n大臂贴紧躯干固定，呼气屈肘将杠铃弯举至胸前\n顶端停顿感受前臂与肱桡肌发力，缓慢下放\n手腕保持伸直中立，不塌腕不翻腕", "重量过大导致塌腕，压力全在腕关节上\n身体后仰甩杠借力，大臂离开躯干\n用掌心翻转绕过前臂发力，失去训练意义"),
        Seed("wg:wrist-curl", "腕弯举", "Wrist Curl", "wrist-curl", "arms", "Forearms", "", "Barbell", "weight_reps", false, "exercises/arms/wrist-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐姿前臂放在大腿上，手腕悬出膝盖，正握杠铃（或反握练屈腕）\n手腕缓慢下沉让杠铃向指尖方向滚落至最低点\n呼气用力屈腕把杠铃卷起到最高点，顶峰挤压前臂\n动作幅度小但控制要全程，缓慢下放重复", "前臂离开大腿翘起，变成整个手臂发力\n重量过大靠甩腕完成，极易拉伤腕部\n幅度失控或速度过快，失去对前臂的孤立刺激"),
        Seed("ex-arm-03", "绳索下压", "Tricep Pushdown", "tricep-pushdown", "arms", "Triceps", "Shoulders", "Cable", "weight_reps", false, "exercises/arms/tricep-pushdown/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0205-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "滑轮调至高位，双手握杆/绳，上臂贴紧躯干两侧并全程固定\n吸气准备，呼气肘部不动将杆向下压至大腿前侧，手臂完全伸直\n顶端挤压三头一秒，缓慢弯曲肘部回到起始高度\n躯干微微前倾站稳，肘部始终不前后漂移", "肘部随身体前后移动，变成俯身压重而非三头下压\n身体重量下压借力，肩胸过度参与\n到底端不完全伸直，三头没有全程收缩"),
        Seed("wg:overhead-tricep-extension", "过顶臂屈伸", "Overhead Tricep Extension", "overhead-tricep-extension", "arms", "Triceps", "Shoulders", "Cable", "weight_reps", false, "exercises/arms/overhead-tricep-extension/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "背对高位滑轮（或用绳索低位过顶），双手握绳柄举过头顶\n大臂垂直固定在头两侧，肘部指向天花板\n呼气前臂向上伸直手臂，挤压三头，肘部尽量不外扩\n缓慢屈肘下放至脑后深处，让三头充分拉长再重复", "大臂前后摆动、肘部不固定，肩部代偿发力\n下放幅度过小，长头没有被充分拉伸\n腰部过度反弓，核心没收紧保护脊柱"),
        Seed("wg:skull-crusher", "碎颅者", "Skull Crusher", "skull-crusher", "arms", "Triceps", "Shoulders", "Barbell", "weight_reps", false, "exercises/arms/skull-crusher/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0183-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧于平凳，双手窄距握杠举在胸口正上方\n大臂保持垂直固定，只弯曲肘部将杠缓慢下放至额头附近\n呼气用三头发力将杠举回顶端，手臂伸直但不锁死肘关节\n全程肘部夹角内收不外张，大臂位置始终不动", "大臂前后摇摆变成类似窄距卧推，三头刺激减少\n下放过深过快砸向头部或肩部，存在受伤风险\n肘部过度外展，肩关节承受不必要的压力"),
        Seed("wg:close-grip-bench-press", "窄握卧推", "Close-Grip Bench Press", "close-grip-bench-press", "arms", "Triceps", "Chest,Shoulders", "Barbell", "weight_reps", false, "exercises/arms/close-grip-bench-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0049-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧平凳，双手略窄于肩握杠（比肩窄但不要两手相碰）\n杠铃下放到下胸/上腹位置，肘部贴近躯干下沉\n呼气推起至手臂伸直，顶端三头用力挤压\n全程肩胛后收下沉、双脚踩实，手腕保持中立叠在前臂正上方", "握距过窄导致腕部受压疼痛，正确是略窄于肩\n肘部向外张开，变成普通卧推且肩部易受伤\n杠铃下放到胸口过深反弹借力，失去离心控制"),
        Seed("wg:dip", "双杠臂屈伸", "Dip", "dip", "arms", "Triceps", "Chest,Shoulders", "Bodyweight", "bodyweight_reps", false, "exercises/arms/dip/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0172-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双手握杠撑起身体，手臂伸直，肩胛下沉收紧，躯干微前倾\n缓慢屈肘下沉身体，直到上臂大约与地面平行或肘部感到牵拉\n呼气发力撑起身体回到手臂伸直位置，顶峰挤压三头\n全程肘部朝后方贴身移动，不外张，核心收紧稳定下肢", "下沉过深导致肩部被过度拉伸，容易拉伤肩前侧\n耸肩含胸，肩胛失去稳定，压力转移到肩关节\n靠身体晃动蹬腿借力撑起，三头刺激不足"),
        Seed("wg:assisted-dip", "辅助双杠臂屈伸", "Assisted Dip", "assisted-dip", "arms", "Triceps", "Chest", "Machine", "assisted_bodyweight", false, "exercises/arms/assisted-dip/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0171-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "在辅助双杠机上设好配重（配重越大辅助越多），双膝跪上垫板\n双手握杠撑直手臂，肩胛下沉收紧\n缓慢屈肘下沉至肘部约90度或感到胸肩牵拉\n呼气发力撑起回到伸直位置，保持躯干稳定不摇摆", "辅助重量设太大，动作变成被垫板弹起而非自主动作\n下沉过深耸肩，肩部压力过大\n身体前后晃动借力，三头和胸的发力感丢失"),
        Seed("ex-core-01", "平板支撑", "Plank", "plank", "core", "Core", "Shoulders", "Bodyweight", "duration", false, "exercises/core/plank/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "俯卧，双肘撑地于肩正下方，双脚脚尖着地\n收紧腹部与臀部，身体从头到脚跟呈一条直线\n腰椎贴平：不要塌腰也不要撅臀，骨盆微微后倾锁住\n保持自然呼吸，不憋气，匀速呼吸坚持规定时间\n结束后慢速放下身体，避免突然松力", "塌腰或撅臀，腰椎失去中立位，骨盆不稳定\n憋气坚持，应在全程保持均匀呼吸\n肩胛下陷或耸肩，应推开地面让肩胛贴住胸廓"),
        Seed("wg:side-plank", "侧平板支撑", "Side Plank", "side-plank", "core", "Core", "Shoulders", "Bodyweight", "duration", false, "exercises/core/side-plank/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0113-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "侧卧，单肘撑地于肩正下方，另一手叉腰或伸向天花板\n双脚叠放或前后错开，推起身体使头、髋、脚呈一条直线\n收紧腹侧与臀部，髋部不塌不转，骨盆保持中立\n保持自然呼吸不憋气，坚持规定时间后换边\n换边时控制身体慢速落下，不要摔落", "髋部下沉或身体前后倾倒，腹侧失去张力\n憋气硬撑，全程应保持均匀呼吸\n肩未在肘正上方，肩关节受压疼痛"),
        Seed("ex-core-05", "悬垂举腿", "Hanging Leg Raise", "hanging-leg-raise", "core", "Core", "Grip", "Bodyweight", "bodyweight_reps", false, "exercises/core/hanging-leg-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手握杠悬垂，肩胛收紧下沉，身体不晃\n收紧腹部，骨盆微微后倾，双腿伸直并拢向前上方举起\n举至双腿与地面平行或更高，臀部微微卷起\n控制速度缓慢下放，避免身体摆荡\n全程自然呼吸，举腿时呼气、下放时吸气", "只抬腿不卷骨盆，骨盆未后倾导致腰椎反弓\n靠身体摆荡惯性甩腿，腹部没有主导发力\n下放过快失控，腰椎和肩部承受冲击"),
        Seed("wg:cable-crunch", "绳索卷腹", "Cable Crunch", "cable-crunch", "core", "Core", "", "Cable", "weight_reps", false, "exercises/core/cable-crunch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0288-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双膝跪地，双手握绳索把手置于头部两侧，髋部固定\n吸气预备，呼气时收紧腹肌，腰椎弯曲卷起上身\n用腹肌把肘部拉向膝盖方向，臀部保持固定不移动\n顶点稍停感受腹肌收缩，缓慢回到起始位置\n全程骨盆稳定，避免用身体重量下压", "用髋部屈伸代替卷腹，变成俯身动作而非脊柱屈曲\n下放过快或幅度过大，腰椎失去控制\n憋气发力，应呼气卷起、吸气还原"),
        Seed("wg:ab-wheel", "健腹轮", "Ab Wheel Rollout", "ab-wheel", "core", "Core", "Shoulders", "Bodyweight", "bodyweight_reps", false, "exercises/core/ab-wheel/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0285-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双膝跪垫，双手握健腹轮置于肩下，收紧腹部与臀部\n保持腰椎贴平不塌陷，缓慢向前推轮伸展身体\n推至身体接近地面但腰椎不塌的最大范围\n收紧腹肌把身体拉回起始跪姿\n全程呼吸均匀，推出时吸气、回拉时呼气", "塌腰推进过远，腰椎代偿是健腹轮最常见的受伤原因\n用髋部先回去借力，应由腹肌主导回拉\n速度过快失去控制，应全程缓慢可控"),
        Seed("wg:running", "跑步", "Running", "running", "legs", "Legs", "Cardio", "Cardio", "distance_duration", false, "exercises/legs/running/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "身体微前倾，目视前方，肩部放松。\n以髋部发力带动腿部，脚掌中部先着地，着地点靠近重心下方。\n步频保持每分钟170-180步左右，手臂自然前后摆动。\n呼吸节奏稳定，强度以能维持目标配速为准。", "脚跟重重着地或跨步过大，着地点远离重心增加制动冲击。\n躯干后仰或左右摇摆，核心应保持稳定。\n步频过低、步幅过大，容易过度疲劳。"),
        Seed("wg:walking", "步行", "Walking", "walking", "legs", "Legs", "Cardio", "Cardio", "distance_duration", false, "exercises/legs/walking/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "抬头挺胸，目视前方，肩部自然放松。\n核心轻微收紧，从髋部摆动双腿迈步。\n脚跟先着地过渡到脚掌蹬地，步幅自然。\n手臂随步伐自然摆动，保持稳定节奏。", "低头看手机导致含胸驼背。\n步幅刻意过大导致重心不稳。\n手臂僵直下垂不参与摆动。"),
        Seed("wg:cycling", "骑行", "Cycling", "cycling", "legs", "Legs", "Cardio", "Cardio", "distance_duration", false, "exercises/legs/cycling/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "调整座垫高度，蹬至最低点时膝盖保留约25-30度弯曲。\n双手轻握车把，肩肘放松，核心稳定。\n蹬踏画圆发力，下踩与上提衔接流畅。\n保持踏频稳定，强度按目标心率或功率控制。", "座垫过低导致膝盖压力过大或过高导致骨盆晃动。\n膝盖内扣，应保持膝盖与脚尖同向。\n只靠下踩死蹬，踏频忽快忽慢。"),
        Seed("wg:rowing", "划船机", "Rowing", "rowing", "back", "Back", "Legs,Cardio", "Cardio", "distance_duration", false, "exercises/back/rowing/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "划船机启动姿势：小腿垂直、躯干前倾、手臂伸直握桨（抓水位）。\n发力顺序：先蹬腿，随后身体略后倾，最后屈肘把桨柄拉到下胸位置。\n还原顺序相反：先伸手臂，再前倾躯干，最后屈膝回到起始位。\n全程背部保持平直中立，核心收紧，节奏稳定。\n拉桨有力、还原放松，呼吸与节奏配合自然。", "先拉臂后蹬腿（顺序错误）：记住腿-身-臂的发力顺序。\n弓背驼背拉桨：保持脊柱中立，用屈髋代替弯腰前倾。"),
        Seed("wg:stair-climber", "爬楼机", "Stair Climber", "stair-climber", "legs", "Legs", "Cardio", "Cardio", "duration", false, "exercises/legs/stair-climber/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手轻扶扶手保持平衡，身体直立微前倾，核心收紧。\n全脚掌踩实踏板，重心随之上移，不要用脚尖踮。\n每一步充分蹬伸髋膝，感受臀腿发力。\n保持稳定节奏，避免忽快忽慢。", "把体重压在扶手上，等于卸掉负荷，手臂只做平衡。\n身体过度前倾或用脚尖小步快蹬。\n步幅过小只用膝盖发力。"),
        Seed("ex-chest-06", "哑铃飞鸟", "Dumbbell Fly", "dumbbell-fly", "chest", "Chest", "Shoulders", "Dumbbell", "weight_reps", false, "exercises/chest/dumbbell-fly/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0056-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧平凳，双脚踩地，双手各握哑铃举在胸口上方，手肘微弯固定。\n保持手肘角度不变，沿弧线把哑铃向身体两侧缓缓打开。\n打开到胸口有舒服拉伸感即停，感受胸肌被拉开。\n用胸肌发力沿原弧线把哑铃合拢回来，顶端想象夹紧胸部。\n打开时吸气、合拢时呼气，全程速度放慢不靠惯性。", "手肘角度越做越大变成推：手肘的弯度全程锁死，只动肩带不做推伸。\n哑铃下放过深猛拉肩关节：打开到胸口舒服的拉伸位置就停，宁浅勿深。\n重量太大靠身体晃动抬起来：减轻重量，让胸肌单独完成合拢发力。"),
        Seed("wg:incline-cable-fly", "上斜绳索夹胸", "Incline Cable Fly", "incline-cable-fly", "chest", "Chest", "Shoulders", "Cable", "weight_reps", false, "exercises/chest/incline-cable-fly/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0060-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "把滑轮调到最低位，坐在30到45度的上斜凳上，或以低向高的方向站立夹胸。\n一手一个把手，手肘微弯锁定，肩胛骨下沉贴凳。\n用上胸发力把手臂沿弧线向内上方合拢，想象胸上部被夹紧。\n顶端停一秒挤压上胸，再控制速度缓慢放回。\n合拢时呼气、打开时吸气，全程保持绳索有张力。", "滑轮高度设错变成练下胸：把滑轮调到低位，让拉力方向朝向锁骨和上胸。\n手肘伸直拉扯肩关节：手肘保持微弯固定，用胸肌而不是手臂发力。\n还原时完全泄力：放回时控制住绳索，不让配重重重砸回底座。"),
        Seed("wg:decline-dumbbell-press", "下斜哑铃卧推", "Decline Dumbbell Press", "decline-dumbbell-press", "chest", "Chest", "Triceps,Shoulders", "Dumbbell", "weight_reps", false, "exercises/chest/decline-dumbbell-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0052-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "躺在下斜凳上，双腿勾稳固定轴，肩胛骨收紧贴凳。\n双手各握哑铃举在下胸两侧上方，手肘约45度角。\n沿弧线缓缓下放到下胸两侧同高，感受轻微拉伸。\n胸肌发力沿弧线推起，顶端哑铃靠拢但不相碰。\n下放吸气、推起呼气，两侧哑铃始终同步等速。", "腿没勾稳身体下滑重心乱：起手前固定好双腿，不稳就减轻重量。\n手肘过度外展肩部代偿：手肘保持约45度夹角，推起时胸口主动发力。\n下放太深猛拉肩膀：降到舒服拉伸的位置就停，控制幅度。"),
        Seed("wg:smith-machine-bench-press", "史密斯卧推", "Smith Machine Bench Press", "smith-machine-bench-press", "chest", "Chest", "Triceps,Shoulders", "Machine", "weight_reps", false, "exercises/chest/smith-machine-bench-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0078-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧平凳，调整位置让杠铃轨迹正好对准中胸上方，肩胛骨收紧贴凳。\n双手握距略宽于肩，手腕中立，先解锁杠铃旋转保险。\n沿固定轨道缓慢下放到中胸，位置比自由卧推略低一点。\n发力沿轨道推起，感受胸肌主导发力，顶端不锁死手肘。\n下放吸气、推起呼气，结束时把杠铃转回保险挂钩再松手。", "凳子位置没对准轨道导致下放卡壳：先空杆试推一次，确认轨迹落在胸口正上方。\n放松手就松开杠铃的危险动作：结束前必须先旋转回保险位，确认挂稳才松手。\n靠轨道固定就不管姿势：肩胛骨收紧、双脚踩地这些基础要求一样不能省。"),
        Seed("wg:landmine-press", "地雷架推举", "Landmine Press", "landmine-press", "shoulders", "Shoulders", "Chest,Triceps", "Barbell", "weight_reps", false, "exercises/shoulders/landmine-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "杠铃一端顶在墙角或地雷架，另一端单手握在肩侧，身体呈半跪或分腿站姿\n收腹、肋骨下沉，将杠铃沿斜向上前方推出至手臂伸直\n顶端肩胛前伸，肩部上推时肘部略偏向身体中线方向\n缓慢屈肘收回杠铃至肩侧，全程躯干不旋转\n推起呼气，收回吸气，双脚或跪姿保持骨盆稳定", "腰椎反弓、肋骨外翻：收紧腹肌、臀部夹紧，推起时呼气帮助核心稳定\n躯干旋转借力：减轻重量，想象胸口始终朝正前方\n轨迹过于外展挤压肩关节：推起方向保持在肩前约45度，肩部疼痛立即减小幅度"),
        Seed("wg:chest-dip", "胸部双杠臂屈伸", "Chest Dip", "chest-dip", "chest", "Chest", "Triceps,Shoulders", "Bodyweight", "bodyweight_reps", false, "exercises/chest/chest-dip/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0054-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双手握杠撑起身体，身体微微前倾，膝盖可以微屈并拢，肩胛骨下沉。\n手肘自然外展，控制身体缓缓下降，直到胸口和肩部有拉伸感。\n下降角度以胸口舒适为限，肘部不要超过明显疼痛的位置。\n用胸肌发力把身体撑起，回到手臂接近伸直但不锁死。\n下降吸气、撑起呼气，全程身体保持前倾不要立直。", "身体立直变成练三头：保持躯干前倾30度左右，让胸口朝向地面才能练到胸。\n下降太深拉伤肩膀：降到肩部有轻微拉伸就停，深度循序渐进。\n靠蹬腿甩身借力上撑：收紧核心控制身体，用胸肌和手臂匀速撑起。"),
        Seed("wg:weighted-dip", "负重双杠臂屈伸", "Weighted Dip", "weighted-dip", "arms", "Triceps", "Chest,Shoulders", "Bodyweight", "weight_reps", false, "exercises/arms/weighted-dip/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "用腰带挂好配重片，双手握杠撑直手臂，肩胛下沉锁定\n躯干略前倾，缓慢屈肘下沉至上臂约与地面平行\n呼气发力撑起至手臂伸直，全程身体保持稳定不摆动\n配重从较轻开始，动作完全稳定后再逐步加重", "自重动作还不稳定就急于加负重，受伤风险高\n下沉过深加上额外负重，肩关节压力剧增\n挂片晃动导致身体摇摆，失去对动作的控制"),
        Seed("wg:machine-shoulder-press", "器械肩推", "Machine Shoulder Press", "machine-shoulder-press", "shoulders", "Shoulders", "Triceps", "Machine", "weight_reps", false, "exercises/shoulders/machine-shoulder-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "调节座椅高度使把手与肩同高或略低，背部与头部贴紧靠背\n双手握把，肘部在手腕正下方，垂直向上推起至手臂接近伸直\n顶端不锁死肘关节，肩胛保持稳定下沉\n缓慢下放至肘约90度，配重不完全落回\n推起呼气，下放吸气，肋骨收紧不外翻", "座椅过低导致推举角度变成上斜且腰椎受压：调整把手与肩同高，背贴靠垫\n拱背离椅借力：减轻配重，主动贴紧靠背并收腹\n下放过深肩前受压：控制行程至肘90度左右，感到肩前牵拉不适即减小幅度"),
        Seed("wg:standing-dumbbell-press", "站姿哑铃推举", "Standing Dumbbell Press", "standing-dumbbell-press", "shoulders", "Shoulders", "Triceps,Core", "Dumbbell", "weight_reps", false, "exercises/shoulders/standing-dumbbell-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与肩同宽站立，收腹夹臀，哑铃举至肩侧，掌心朝前，肘在腕下方\n垂直向上推起哑铃至头顶手臂伸直，肩胛向上锁定但不耸肩\n顶端哑铃接近头顶正上方，身体无左右晃动\n控制下放回肩侧，全程核心维持腰椎中立\n推起呼气，下放吸气", "腰部反弓、肋骨外翻：收腹夹臀，肋骨下沉，重量过大时改坐姿推举\n身体晃动、单侧借力：减轻重量，两臂同步推起，可收紧臀部帮助稳定\n耸肩顶起：肩胛稳定下沉，以肘为引导向上"),
        Seed("wg:push-press", "借力推举", "Push Press", "push-press", "shoulders", "Shoulders", "Triceps,Quads", "Barbell", "weight_reps", false, "exercises/shoulders/push-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "杠铃架于锁骨前，握距略宽于肩，肘部指向前下方，双脚与肩同宽\n微微屈膝下蹲约四分之一深度，随即快速蹬地伸髋伸膝\n借助腿部驱动力将杠铃沿直线推过头顶，手臂在顶端完全伸直锁定\n杠铃落回锁骨同时微屈膝缓冲，衔接下一次动作\n蹬起时爆发呼气，下落吸气，核心全程绷紧", "先推后蹬、变成纯手臂推举：先屈膝蓄力再爆发蹬伸，蹬与推几乎同时启动\n下蹲过深变成深蹲推举：屈膝幅度控制在四分之一左右，以快速反弹为目的\n顶部未锁定、杠铃前落：推至头顶正上方，肩胛上锁、手臂完全伸直再落杠"),
        Seed("wg:machine-lateral-raise", "器械侧平举", "Machine Lateral Raise", "machine-lateral-raise", "shoulders", "Shoulders", "Upper Back", "Machine", "weight_reps", false, "exercises/shoulders/machine-lateral-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "调节座椅与挡臂垫高度，上臂贴住挡垫，胸口贴靠背\n以肘部外侧为发力点向侧上方抬起手臂至与肩同高\n顶端停顿感受中束收缩，肩胛保持下沉\n缓慢控制回放，保留张力不完全卸力\n抬起呼气，回放吸气，全程躯干贴靠垫不后仰", "挡垫位置不当导致用肩峰顶起：先调节坐垫高度使上臂中段贴垫，肘部对准挡垫\n耸肩借斜方肌：肩膀下沉远离耳朵，抬臂时肘尖向上引导\n回放过快卸力：2-3秒控制回放，配重不完全落回"),
        Seed("wg:cable-front-raise", "绳索前平举", "Cable Front Raise", "cable-front-raise", "shoulders", "Shoulders", "Chest", "Cable", "weight_reps", false, "exercises/shoulders/cable-front-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0008-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "背对绳索架站立，低位滑轮，双手或单手握把手置于大腿前，向前一步保持张力\n肘微屈固定，肩前束发力直臂前抬至与肩同高，手腕中立\n顶端停顿一秒，躯干不后仰\n缓慢控制回放，保留绳索张力不完全卸力\n抬起呼气，回放吸气，核心收紧", "身体后仰借力：减轻配重，收腹站稳，双脚前后分立更易保持平衡\n耸肩代偿：沉肩，以肩前束带动手臂抬起\n回放过快失去张力：控制在2-3秒回放，底部不停死"),
        Seed("wg:plate-front-raise", "杠铃片前平举", "Plate Front Raise", "plate-front-raise", "shoulders", "Shoulders", "Chest", "Plate", "weight_reps", false, "exercises/shoulders/plate-front-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手握住杠铃片两侧边缘（三点位或12点位），片垂于大腿前\n肘微屈，肩前束发力将杠铃片平举至与肩同高，片保持水平不倾斜\n顶端停顿感受前束收缩，躯干稳定不后仰\n缓慢下放回起始位，全程握紧不滑脱\n抬起呼气，下放吸气", "杠铃片晃动、借惯性甩起：放慢速度，核心收紧，选轻一些的杠铃片\n耸肩、斜方肌代偿：沉肩抬臂，肘略高于腕\n握持滑脱：三点位握法（拇指在片内侧）更稳，掌心干燥无汗再上手"),
        Seed("ex-shoulder-05", "俯身反向飞鸟", "Bent-Over Rear Delt Raise", "bent-over-rear-delt-raise", "shoulders", "Rear Delts", "Upper Back", "Dumbbell", "weight_reps", false, "exercises/shoulders/bent-over-rear-delt-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与肩同宽，屈髋俯身至上身接近水平，背部平直，核心收紧\n哑铃垂于肩下，肘微屈固定，肩胛先向脊柱收拢\n以肘为引导向两侧上方打开至与背部同高，手腕放松\n顶端停顿感受后束挤压，缓慢下放控制\n打开呼气，下放吸气，头颈与脊柱保持一条直线", "弓腰起身借力：屈髋角度固定，可前额支撑在斜凳上完成，减轻重量\n耸肩用上背代偿：肩胛先沉再收，肘略高于腕，注意力放在肘尖\n甩动幅度过大：抬至与肩平即停，控制节奏感受挤压"),
        Seed("wg:cable-rear-delt-fly", "绳索后束飞鸟", "Cable Rear Delt Fly", "cable-rear-delt-fly", "shoulders", "Rear Delts", "Upper Back", "Cable", "weight_reps", false, "exercises/shoulders/cable-rear-delt-fly/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "绳索滑轮调至与肩同高或面部高度，交叉握住两侧把手（左手抓右、右手抓左）\n后退一步站稳，肘微屈固定，后束发力将把手向两侧后方拉开\n拉开至手臂与肩同高、身体呈T形，肩胛向脊柱收紧停顿\n缓慢控制回放，保留张力不完全卸力\n拉开呼气，回放吸气，躯干稳定不转体", "转体或后仰借力：减轻配重，收腹站稳，想象躯干是一块木板\n耸肩、上背代偿：肩膀下沉，以肘尖为引导向后拉开而非手拉\n回放过快卸力：2-3秒控制回放，两侧始终有张力"),
        Seed("wg:pendlay-row", "彭德利划船", "Pendlay Row", "pendlay-row", "back", "Back", "Biceps,Rear Delts", "Barbell", "weight_reps", false, "exercises/back/pendlay-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "与杠铃划船更水平的俯身姿态：屈髋至上身接近平行地面，杠铃每次下放到地面停顿。\n背部平直中立，膝微屈，肩胛先收紧再启动。\n爆发但受控地把杠铃拉向下腹位置，肘部贴近身体。\n杠铃触地短暂停顿消除借力，再进行下一次。\n选择比常规划船更轻的重量，确保姿态稳定。", "下背弓起：减小重量，保持脊柱中立，若难以维持就改回常规划船。\n杠铃不停顿、用反弹借力：每次触地停顿，消除弹震借力。"),
        Seed("wg:inverted-row", "反向划船", "Inverted Row", "inverted-row", "back", "Back", "Biceps,Core", "Bodyweight", "bodyweight_reps", false, "exercises/back/inverted-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0086-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "把横杠或杠铃架调至约腰部高度，双手略宽于肩正握，身体伸直成一条斜线，脚跟着地。\n肩胛先向后下方收紧，肘部贴近身体把胸口拉向横杠。\n胸口轻触或接近横杠时停顿一秒，缓慢下放至手臂伸直。\n核心与臀部收紧，保持头到脚一条直线，不塌腰不撅臀。\n想增加难度可把脚垫高或身体放得更平。", "塌腰、身体折成两截：收紧核心和臀部，保持刚性直线。\n耸肩、只用手臂拉：先收肩胛再屈肘，用背部完成动作。"),
        Seed("wg:meadows-row", "梅多斯划船", "Meadows Row", "meadows-row", "back", "Back", "Biceps,Rear Delts", "Barbell", "weight_reps", false, "exercises/back/meadows-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "杠铃一端顶在墙角或地锚，另一端装片，站在装片端侧面，内侧脚在前外侧脚在后呈分腿站姿。\n俯身一手撑在同侧大腿或膝上，另一手哑铃式握住杠铃杆末端，背部平直。\n肩胛先下沉收紧，肘部贴身把杠铃末端拉向髋部方向。\n顶端挤压背部一秒，缓慢下放至充分伸展。\n换边进行，两侧训练量对称，躯干保持稳定不旋转。", "躯干旋转借力：固定髋部朝前，动作只发生在肩胛和手臂。\n握杆端过重导致身体被拽歪：减轻重量，保持支撑侧稳定。"),
        Seed("wg:single-arm-cable-row", "单臂绳索划船", "Single-Arm Cable Row", "single-arm-cable-row", "back", "Back", "Biceps,Rear Delts", "Cable", "weight_reps", false, "exercises/back/single-arm-cable-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧对或正对绳索，单手握把手，坐姿或站姿均可，脊柱中立核心收紧。\n肩胛先向后下方收紧，肘部贴近身体把把手拉向腹部侧面。\n顶端感受背部挤压一秒，缓慢还原让肩胛充分前伸。\n躯干保持稳定，不向对侧旋转借力。\n换侧训练，保持两侧幅度和重量一致。", "躯干旋转甩动借力：减轻重量，固定躯干，让背部独立完成动作。\n肩胛始终锁死不做全程伸展：还原时让肩胛前伸充分拉开再拉回。"),
        Seed("wg:wide-grip-lat-pulldown", "宽握高位下拉", "Wide-Grip Lat Pulldown", "wide-grip-lat-pulldown", "back", "Lats", "Biceps", "Cable", "weight_reps", false, "exercises/back/wide-grip-lat-pulldown/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "采用宽握正握横杆，大腿固定挡垫下，坐直、脊柱中立。\n肩胛先下沉后收，肘部向下向外引导拉杆。\n把横杆拉向锁骨上缘位置，感受背阔肌和上背收缩。\n顶端停顿，缓慢还原至充分伸展，肩胛保持控制。\n躯干稳定，仅允许轻微后倾。", "握得过宽导致肩部挤压、幅度受限：宽握以肘部能顺畅下降为准，不必追求过宽。\n身体大幅后仰借力：减轻重量，躯干固定，肘部引导。"),
        Seed("wg:neutral-grip-pull-up", "中立握引体向上", "Neutral-Grip Pull-up", "neutral-grip-pull-up", "back", "Lats", "Biceps,Core", "Bodyweight", "bodyweight_reps", false, "exercises/back/neutral-grip-pull-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0090-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双手采用掌心相对的中立握把手，悬挂时肩胛先下沉收紧。\n肘部向下引导把身体拉至下巴过杆，中立握对肩部更友好。\n顶端停顿一秒，缓慢下放至手臂接近伸直。\n核心收紧，身体稳定不摆动。\n适合肩部不适者替代正握引体，节奏控制与标准引体一致。", "摆动借力、下放失控：收紧核心，控制离心阶段。\n肩胛不激活直接拉：每次先做肩胛下沉再发力。"),
        Seed("wg:assisted-chin-up", "辅助反握引体向上", "Assisted Chin-up", "assisted-chin-up", "arms", "Biceps", "Lats", "Machine", "assisted_bodyweight", false, "exercises/arms/assisted-chin-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "在辅助引体机上设好配重，反握单杠与肩同宽，膝盖跪上垫板\n肩胛先下沉收紧，呼气屈肘把身体向上拉至下巴过杠\n缓慢下放至手臂接近伸直，保持肩背不松塌\n全程大臂向躯干方向收紧，感受二头与背部的发力", "辅助配重过大，动作被机器带起来失去训练价值\n靠身体摆动借力上拉，二头刺激不足\n下放失控被垫板弹起，离心阶段没有意义"),
        Seed("wg:weighted-chin-up", "负重反握引体向上", "Weighted Chin-up", "weighted-chin-up", "arms", "Biceps", "Lats", "Bodyweight", "weight_reps", false, "exercises/arms/weighted-chin-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "用腰带挂好配重片，反握单杠与肩同宽，身体稳定悬垂\n肩胛下沉收紧后发力上拉，下巴过杠，肘部向躯干方向压\n缓慢下放至手臂接近伸直，控制离心阶段\n配重循序渐进，能标准完成多次自重引体后再加重", "自重引体尚未扎实就加负重，动作变形受伤风险大\n靠蹬腿摆身借力，负重下借力更危险\n下放过快被重量拉扯肩肘，离心失控"),
        Seed("wg:rack-pull", "架上硬拉", "Rack Pull", "rack-pull", "back", "Back", "Glutes,Hamstrings", "Barbell", "weight_reps", false, "exercises/back/rack-pull/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "杠铃放在架上的膝上或大腿中部高度，双脚与髋同宽站在杠下。\n屈髋俯身握杠，肩胛收紧、背部平直中立，杠铃贴近身体。\n蹬地伸髋把杠铃拉起至站立位，臀部收紧锁定位，杠铃全程贴腿。\n有控制地下放回架上，不要砸放。\n全程脊柱中立，杠铃路径贴近小腿和大腿。", "弓腰拉起：减小重量、收紧核心、保持背部平直，杠铃贴腿走直线。\n锁定时腰部过度后仰：顶端臀部收紧即可，不要向后超伸腰椎。"),
        Seed("wg:back-extension", "背部伸展", "Back Extension", "back-extension", "core", "Lower Back", "Glutes,Hamstrings", "Bodyweight", "bodyweight_reps", false, "exercises/core/back-extension/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0103-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "髋部靠在罗马椅垫上，双脚固定，身体前倾下垂\n双手抱胸或置于头侧，背部平直预备\n收紧臀部和下背，缓慢抬起躯干至与腿呈一条直线\n顶点稍停，不要过度后仰反弓腰椎\n控制速度缓慢下放，全程呼吸自然", "抬得过高、过度反弓腰椎，挤压下背部\n用爆发力甩起躯干，应慢起慢落\n动作全程憋气，应保持自然呼吸节奏"),
        Seed("wg:dumbbell-shrug", "哑铃耸肩", "Dumbbell Shrug", "dumbbell-shrug", "back", "Upper Back", "Forearms", "Dumbbell", "weight_reps", false, "exercises/back/dumbbell-shrug/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0005-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双手各持一哑铃自然站立，手臂伸直、肩部下沉为起点。\n肩胛垂直向上耸起，顶端停顿挤压一秒。\n缓慢下放还原，让斜方肌充分拉开。\n手臂全程不弯，发力只来自肩带上提。\n核心收紧，头颈保持中立，不做绕环。", "用颈部前探或手臂弯举代偿：肩胛垂直上下移动，手臂保持伸直。\n幅度过小、只做小幅颠动：做到完整耸肩幅度并在顶端停顿。"),
        Seed("ex-leg-02", "高脚杯深蹲", "Goblet Squat", "goblet-squat", "legs", "Quads", "Glutes,Core", "Dumbbell", "weight_reps", false, "exercises/legs/goblet-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手捧住哑铃或壶铃于胸前，肘部贴近身体内侧。\n双脚与肩同宽略外展，核心收紧。\n屈髋屈膝同步下蹲至大腿平行或更低，膝盖与脚尖同向。\n脚掌均匀发力站起，髋膝同步伸直，保持哑铃贴胸。", "肘部下垂导致杠铃下坠拉弯躯干，肘应保持朝下贴肋。\n膝盖内扣，与脚尖不同向。\n核心松弛、身体前倾或塌腰。"),
        Seed("wg:smith-machine-squat", "史密斯深蹲", "Smith Machine Squat", "smith-machine-squat", "legs", "Quads", "Glutes,Core", "Machine", "weight_reps", false, "exercises/legs/smith-machine-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0124-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "杠铃置于斜方肌上部，双脚略向前站出，与肩同宽。\n解锁杠铃，核心收紧，屈髋屈膝同步下蹲。\n下蹲至大腿平行或更低，膝盖与脚尖同向。\n脚掌发力蹬起，髋膝同步站直，顶端重新锁回安全销。", "躯干过度前倾或塌腰，核心应全程绷紧。\n膝盖内扣。\n站距与杠铃轨迹不匹配导致重心失衡。"),
        Seed("wg:belt-squat", "腰带深蹲", "Belt Squat", "belt-squat", "legs", "Quads", "Glutes", "Machine", "weight_reps", false, "exercises/legs/belt-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "腰带扣在髋部两侧，站上平台双脚与肩同宽。\n核心收紧，屈髋屈膝同步下蹲至大腿平行。\n保持躯干竖直，膝盖与脚尖同向。\n脚掌发力站起，髋膝同步伸直。", "下蹲过深导致骨盆翻转、腰部弯曲。\n膝盖内扣或核心松弛。\n腰带挂偏导致负重不均。"),
        Seed("wg:sumo-deadlift", "相扑硬拉", "Sumo Deadlift", "sumo-deadlift", "core", "Posterior Chain", "Glutes,Quads", "Barbell", "weight_reps", false, "exercises/core/sumo-deadlift/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚宽于肩、脚尖外展约45度，杠铃贴近小腿\n屈髋下潜握杠，背部平直，膝盖与脚尖方向一致\n蹬地起立，髋部前推，髋膝同步伸展至站直\n杠铃全程贴身上行，臀部在顶点收紧\n下放时先屈髋后屈膝，沿原路控制落回", "膝盖内扣，与脚尖方向不一致，膝关节压力增大\n弓背起杠，腰椎失去中立位\n站距过窄没有发挥相扑站姿的髋部优势"),
        Seed("wg:trap-bar-deadlift", "六角杠硬拉", "Trap Bar Deadlift", "trap-bar-deadlift", "core", "Posterior Chain", "Quads,Grip", "Barbell", "weight_reps", false, "exercises/core/trap-bar-deadlift/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站入六角杠中间，双脚与髋同宽，杠贴近小腿\n屈髋屈膝握住两侧把手，背部平直、肩胛收紧\n蹬地起立，髋膝同步伸展，重心均匀落在全脚掌\n站直后臀部收紧，然后先屈髋后屈膝控制下放\n全程腰椎中立，呼吸配合发力节奏", "重心偏前脚掌或脚跟，身体前后失衡\n弓背或耸肩起杠，下背部代偿\n起立过猛向后仰身，顶点过度伸展腰椎"),
        Seed("wg:lying-leg-curl", "俯卧腿弯举", "Lying Leg Curl", "lying-leg-curl", "legs", "Hamstrings", "Calves", "Machine", "weight_reps", false, "exercises/legs/lying-leg-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0117-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "俯卧于器械上，滚轴贴住小腿后侧踝上方，双手握紧把手。\n髋部与胸部贴紧垫面，膝盖对齐机器转轴。\n屈膝把滚轴拉向臀部，顶端停顿收紧腘绳肌。\n缓慢放回，全程控制速度。", "髋部翘起借力，臀腰离开垫面说明重量过大。\n下放失控砸落。\n头部过度抬起导致颈部紧张。"),
        Seed("wg:nordic-hamstring-curl", "北欧腿弯举", "Nordic Hamstring Curl", "nordic-hamstring-curl", "legs", "Hamstrings", "Glutes,Calves", "Bodyweight", "bodyweight_reps", false, "exercises/legs/nordic-hamstring-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "跪姿，脚踝被固定或由同伴压住，躯干大腿保持一条直线。\n核心与臀部收紧，缓慢前倾下落，尽量延缓弯曲膝盖。\n身体降到极限后，用腘绳肌发力把身体拉回直立。\n动作全程手随时准备撑地保护。", "塌腰或髋部先塌，躯干应保持从头到膝一条直线。\n下落速度失控摔向地面。\n全程靠手臂撑地完成，腘绳肌没有实际参与。"),
        Seed("wg:single-leg-romanian-deadlift", "单腿罗马尼亚硬拉", "Single-Leg Romanian Deadlift", "single-leg-romanian-deadlift", "legs", "Hamstrings", "Glutes,Core", "Dumbbell", "weight_reps", false, "exercises/legs/single-leg-romanian-deadlift/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "单手持哑铃站立，另一侧腿作为支撑，核心收紧。\n以髋为铰链向后推臀，同时另一条腿向后伸直抬起。\n躯干与后腿接近一条直线，保持背部平直，哑铃垂直下放。\n腘绳肌充分拉伸后，用臀部发力站直。\n完成次数后换边。", "骨盆旋转歪斜，髋部应始终保持正对前方。\n弓背下放，腰椎失去中立位。\n支撑腿膝盖过度内扣或晃动。"),
        Seed("wg:reverse-lunge", "后撤箭步蹲", "Reverse Lunge", "reverse-lunge", "legs", "Quads", "Glutes,Hamstrings", "Dumbbell", "weight_reps", false, "exercises/legs/reverse-lunge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0129-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双脚与髋同宽站立，双手持哑铃于体侧，核心收紧。\n一条腿向后撤一大步，前腿屈膝下沉。\n后膝接近地面，前膝与脚尖同向，躯干正直。\n前腿发力蹬地收回，换腿交替进行。", "躯干前倾塌腰，核心应保持收紧。\n前膝内扣或过度超过脚尖。\n后撤步幅过小导致膝盖压力集中。"),
        Seed("wg:split-squat", "分腿蹲", "Split Squat", "split-squat", "legs", "Quads", "Glutes,Core", "Dumbbell", "weight_reps", false, "exercises/legs/split-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "前后分腿站立，前后脚距离约一大步，双手持哑铃于体侧。\n核心收紧，躯干保持正直，垂直下蹲。\n后膝下沉接近地面，前膝与脚尖同向。\n前腿发力站起，完成次数后换腿。", "重心过多压向后腿，力量应主要由前腿承担。\n躯干前倾或左右摇摆。\n前膝内扣。"),
        Seed("wg:cable-kickback", "绳索后踢腿", "Cable Kickback", "cable-kickback", "legs", "Glutes", "Hamstrings", "Cable", "weight_reps", false, "exercises/legs/cable-kickback/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0112-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "绳索套在脚踝，双手扶住器械，上身微前倾，核心收紧。\n保持骨盆稳定不旋转，臀部发力把腿向后上方踢起。\n顶端停顿一秒收紧臀部，踢腿高度以骨盆不翻转为准。\n缓慢放回，完成次数后换腿。", "腰部反弓代替臀部发力，骨盆应保持稳定。\n踢腿过高导致骨盆翻转、腰椎代偿。\n利用摆动惯性甩腿，应控制还原。"),
        Seed("wg:hip-abduction-machine", "髋外展机", "Hip Abduction Machine", "hip-abduction-machine", "legs", "Glutes", "Core", "Machine", "weight_reps", false, "exercises/legs/hip-abduction-machine/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐进器械，双腿外侧抵住挡板，双手握住把手，背部贴紧靠背。\n核心收紧，臀部发力把双腿向外打开。\n打开到最大幅度停顿一秒，感受臀部外侧收缩。\n缓慢合拢还原，不让配重片砸落。", "用身体后仰或前倾借力，躯干应贴紧靠背。\n合拢过快失去张力。\n幅度过小，未做到最大外展。"),
        Seed("wg:single-leg-glute-bridge", "单腿臀桥", "Single-Leg Glute Bridge", "single-leg-glute-bridge", "legs", "Glutes", "Hamstrings", "Bodyweight", "bodyweight_reps", false, "exercises/legs/single-leg-glute-bridge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧屈膝，一腿抬起伸直或屈膝抱胸，另一脚踩实地面。\n核心收紧保持骨盆水平，臀部发力把髋顶起。\n顶端肩髋呈一条直线，收紧臀部一秒，骨盆不向一侧倾斜。\n缓慢下放，臀部轻触地面重复。", "骨盆向一侧倾斜旋转，应保持两侧髋同高。\n腰椎过伸顶端后仰。\n支撑脚过远导致腘绳肌代偿。"),
        Seed("wg:barbell-glute-bridge", "杠铃臀桥", "Barbell Glute Bridge", "barbell-glute-bridge", "legs", "Glutes", "Hamstrings,Core", "Barbell", "weight_reps", false, "exercises/legs/barbell-glute-bridge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧屈膝，杠铃加护垫压在髋部，双脚踩实与肩同宽。\n核心收紧，臀部发力顶着杠铃把髋向上顶起。\n顶端肩髋呈一条直线，停顿一秒收紧臀部。\n缓慢下放，臀部不完全落地。", "腰椎过伸代替臀部收紧。\n杠铃滚压到腹部，护垫应固定在髋部。\n下放过快失控。"),
        Seed("wg:dumbbell-glute-bridge", "哑铃臀桥", "Dumbbell Glute Bridge", "dumbbell-glute-bridge", "legs", "Glutes", "Hamstrings,Core", "Dumbbell", "weight_reps", false, "exercises/legs/dumbbell-glute-bridge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧屈膝，哑铃横放压在髋部，双手扶稳。\n双脚踩实与肩同宽，核心收紧。\n臀部发力把髋顶起至肩髋一条直线，停顿一秒。\n缓慢下放，臀部轻触地面重复。", "顶端腰椎过伸后仰。\n哑铃滑落，双手应始终扶稳。\n双脚过远导致发力部位偏移。"),
        Seed("wg:dumbbell-hip-thrust", "哑铃臀推", "Dumbbell Hip Thrust", "dumbbell-hip-thrust", "legs", "Glutes", "Hamstrings", "Dumbbell", "weight_reps", false, "exercises/legs/dumbbell-hip-thrust/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "肩胛上背靠住凳边，哑铃压在髋部，双脚踩实与肩同宽。\n核心收紧，下巴微收，臀部发力向上顶起髋部。\n顶端躯干与大腿接近平行，膝盖约90度，收紧臀部一秒。\n有控制地下放，臀部不完全落地。", "顶端腰椎过伸代替臀部收紧。\n哑铃压到腹部或肋骨位置。\n双脚站位过远导致腘绳肌代偿。"),
        Seed("wg:smith-machine-hip-thrust", "史密斯臀推", "Smith Machine Hip Thrust", "smith-machine-hip-thrust", "legs", "Glutes", "Hamstrings,Core", "Machine", "weight_reps", false, "exercises/legs/smith-machine-hip-thrust/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "肩胛上背靠住凳边，杠铃垫护垫压在髋部，双脚踩实。\n解开安全销，核心收紧，臀部发力向上顶起。\n顶端躯干与大腿接近平行，停顿一秒收紧臀部。\n缓慢下放，顶端锁回安全销。", "腰椎过伸代偿，顶端应以臀部收紧为终点。\n杠铃位置压到腹部。\n下放失控砸落。"),
        Seed("wg:smith-machine-romanian-deadlift", "史密斯罗马尼亚硬拉", "Smith Machine Romanian Deadlift", "smith-machine-romanian-deadlift", "legs", "Hamstrings", "Glutes,Lower Back", "Machine", "weight_reps", false, "exercises/legs/smith-machine-romanian-deadlift/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "面向杠铃站立，双脚与髋同宽，杠铃贴住大腿前侧。\n解开安全销，核心收紧，膝盖微屈固定。\n以髋为铰链向后推臀，杠铃沿大腿滑向下，背部保持平直。\n腘绳肌充分拉伸后发力站直，顶端锁回安全销。", "弓背下放，腰椎失去中立位。\n膝盖随动作屈伸，应保持角度固定。\n下放过深导致腰部代偿。"),
        Seed("ex-leg-03", "哑铃罗马尼亚硬拉", "Dumbbell Romanian Deadlift", "dumbbell-romanian-deadlift", "legs", "Hamstrings", "Glutes,Lower Back", "Dumbbell", "weight_reps", false, "exercises/legs/dumbbell-romanian-deadlift/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手持哑铃于体侧，双脚与髋同宽站立，膝盖微屈固定。\n核心收紧，以髋为铰链向后推臀，哑铃贴腿垂直下放。\n背部保持平直，腘绳肌充分拉伸后发力站直。\n顶端收紧臀部，哑铃全程贴近身体。", "弓背或圆肩下放，腰椎失去中立位。\n膝盖角度变化变成深蹲。\n哑铃离身过远增加腰部负担。"),
        Seed("wg:kettlebell-romanian-deadlift", "壶铃罗马尼亚硬拉", "Kettlebell Romanian Deadlift", "kettlebell-romanian-deadlift", "legs", "Hamstrings", "Glutes,Lower Back", "Kettlebell", "weight_reps", false, "exercises/legs/kettlebell-romanian-deadlift/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手持壶铃于体前，双脚与髋同宽站立，膝盖微屈固定。\n核心收紧，以髋为铰链向后推臀，壶铃贴腿下放。\n背部平直，腘绳肌充分拉伸后发力站直。\n顶端收紧臀部，壶铃全程贴近身体中线。", "弓背下放，腰椎失去中立位。\n壶铃前移离身，应贴腿运动。\n膝盖随动作改变角度。"),
        Seed("wg:cable-pull-through", "绳索屈髋拉伸", "Cable Pull-Through", "cable-pull-through", "legs", "Glutes", "Hamstrings,Lower Back", "Cable", "weight_reps", false, "exercises/legs/cable-pull-through/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "背对绳索，双手持绳从两腿间穿过，向前迈出一步站稳。\n屈髋向后推臀，躯干前倾，保持背部平直，绳索从腿间后拉。\n臀部发力向前推髋站直，顶端收紧臀部。\n缓慢屈髋还原，全程控制。", "弓背屈髋，腰椎失去中立位。\n用下蹲代替屈髋，膝盖过度前移。\n顶端腰椎过伸后仰。"),
        Seed("wg:machine-glute-kickback", "器械后踢腿", "Machine Glute Kickback", "machine-glute-kickback", "legs", "Glutes", "Hamstrings", "Machine", "weight_reps", false, "exercises/legs/machine-glute-kickback/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "单膝跪撑于器械垫上，双手扶稳把手，核心收紧。\n另一条腿向后蹬入滚轴，臀部发力把腿向后上方踢起。\n顶端停顿一秒收紧臀部，骨盆保持稳定不旋转。\n缓慢放回，完成次数后换腿。", "腰部反弓代偿，骨盆应保持稳定。\n踢腿过高导致骨盆翻转。\n利用惯性甩腿，应控制还原。"),
        Seed("wg:cable-standing-hip-abduction", "站姿绳索髋外展", "Cable Standing Hip Abduction", "cable-standing-hip-abduction", "legs", "Glutes", "Core", "Cable", "weight_reps", false, "exercises/legs/cable-standing-hip-abduction/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "绳索套在外侧腿的脚踝，内侧手扶住器械站稳，核心收紧。\n保持骨盆正对前方，外侧腿向外侧抬起。\n抬到最大幅度停顿一秒，收紧臀部外侧。\n缓慢放回，完成次数后换腿。", "身体向对侧倾斜借力，躯干应保持竖直。\n骨盆旋转代偿。\n利用摆动惯性甩腿。"),
        Seed("wg:cable-standing-hip-adduction", "站姿绳索髋内收", "Cable Standing Hip Adduction", "cable-standing-hip-adduction", "legs", "Adductors", "Core,Glutes", "Cable", "weight_reps", false, "exercises/legs/cable-standing-hip-adduction/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "绳索套在靠近器械一侧腿的脚踝，外侧手扶稳器械，核心收紧。\n保持骨盆稳定，大腿发力向身体中线收腿。\n收过身体中线位置停顿一秒，感受大腿内侧收缩。\n缓慢向外放回，完成次数后换腿。", "躯干侧倾借力，应保持身体竖直。\n放回过快失去张力。\n幅度过小，未收过中线。"),
        Seed("wg:hip-adduction-machine", "髋内收机", "Hip Adduction Machine", "hip-adduction-machine", "legs", "Adductors", "Core", "Machine", "weight_reps", false, "exercises/legs/hip-adduction-machine/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐进器械，双腿内侧抵住挡板，背部贴紧靠背。\n核心收紧，大腿内侧发力把双腿向内合拢。\n合拢到最大幅度停顿一秒。\n缓慢打开还原，不让配重片砸落。", "身体后仰前倾借力，应贴紧靠背。\n打开过快失去控制。\n幅度过小，未合拢到位。"),
        Seed("wg:smith-machine-bulgarian-split-squat", "史密斯保加利亚分腿蹲", "Smith Machine Bulgarian Split Squat", "smith-machine-bulgarian-split-squat", "legs", "Quads", "Glutes,Core", "Machine", "weight_reps", false, "exercises/legs/smith-machine-bulgarian-split-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "后脚脚背搭在凳上，杠铃置于斜方肌上部并解锁。\n核心收紧，身体垂直下沉，前膝与脚尖同向。\n下蹲至前大腿接近平行地面。\n前腿发力站起，完成后锁回安全销并换腿。", "前膝内扣或过度超过脚尖。\n躯干过度前倾、核心松弛。\n失衡时杠铃脱轨，应选用可控重量。"),
        Seed("wg:smith-machine-reverse-lunge", "史密斯后撤箭步蹲", "Smith Machine Reverse Lunge", "smith-machine-reverse-lunge", "legs", "Quads", "Glutes,Hamstrings,Core", "Machine", "weight_reps", false, "exercises/legs/smith-machine-reverse-lunge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "杠铃置于斜方肌上部并解锁，双脚与髋同宽站立。\n核心收紧，一条腿向后撤一大步，前腿屈膝下沉。\n后膝接近地面，前膝与脚尖同向，躯干正直。\n前腿发力站起，完成次数后换腿并锁回安全销。", "躯干前倾或塌腰。\n前膝内扣。\n撤步过小导致膝盖压力集中。"),
        Seed("wg:smith-machine-split-squat", "史密斯分腿蹲", "Smith Machine Split Squat", "smith-machine-split-squat", "legs", "Quads", "Glutes,Core", "Machine", "weight_reps", false, "exercises/legs/smith-machine-split-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "杠铃置于斜方肌上部并解锁，前后分腿站立，距离约一大步。\n核心收紧，躯干正直，垂直下蹲。\n后膝下沉接近地面，前膝与脚尖同向。\n前腿发力站起，完成后换腿并锁回安全销。", "重心压向后腿，应由前腿承担主要负荷。\n躯干前倾塌腰。\n前膝内扣。"),
        Seed("wg:heel-elevated-goblet-squat", "垫脚高脚杯深蹲", "Heel-Elevated Goblet Squat", "heel-elevated-goblet-squat", "legs", "Quads", "Glutes,Core", "Dumbbell", "weight_reps", false, "exercises/legs/heel-elevated-goblet-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "脚跟垫上杠铃片，双手捧住哑铃或壶铃于胸前。\n双脚与肩同宽，核心收紧。\n屈髋屈膝同步下蹲至大腿平行或更低，膝盖对准脚尖方向。\n前脚掌与脚跟均匀发力站起，髋膝同步伸直。", "膝盖过度前移但仍需保持与脚尖同向，不得内扣。\n核心松弛导致躯干前倾。\n垫高物不稳导致重心晃动。"),
        Seed("wg:dumbbell-sumo-squat", "哑铃相扑深蹲", "Dumbbell Sumo Squat", "dumbbell-sumo-squat", "legs", "Glutes", "Quads,Adductors,Hamstrings", "Dumbbell", "weight_reps", false, "exercises/legs/dumbbell-sumo-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚宽于肩、脚尖外展约45度，双手持哑铃垂于体前。\n核心收紧，屈髋屈膝同步下蹲，膝盖对准脚尖方向打开。\n下蹲至大腿平行或更低，背部保持平直。\n脚掌发力站起，髋膝同步伸直，顶端收紧臀部。", "膝盖内收，必须始终对准脚尖方向打开。\n躯干过度前倾、弓背。\n站距不够宽导致动作变成普通深蹲。"),
        Seed("wg:dumbbell-sumo-deadlift", "哑铃相扑硬拉", "Dumbbell Sumo Deadlift", "dumbbell-sumo-deadlift", "core", "Posterior Chain", "Glutes,Quads,Adductors", "Dumbbell", "weight_reps", false, "exercises/core/dumbbell-sumo-deadlift/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚宽于肩、脚尖外展，哑铃竖直置于两脚之间\n屈髋下潜，双手握住哑铃，背部平直\n蹬地起立，髋部前推，髋膝同步伸展站直\n哑铃贴近身体上行，顶点臀部收紧\n控制下放，先屈髋后屈膝，哑铃沿原路落回", "哑铃离身体太远，重心前移增加腰椎负荷\n膝盖内扣，未与脚尖外展方向对齐\n弓背起铃或猛拉发力，腰椎受压"),
        Seed("wg:front-foot-elevated-split-squat", "前脚垫高分腿蹲", "Front-Foot Elevated Split Squat", "front-foot-elevated-split-squat", "legs", "Quads", "Glutes,Core", "Dumbbell", "weight_reps", false, "exercises/legs/front-foot-elevated-split-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "前脚踩在低垫高物上，后脚平踩地面，前后分腿站立。\n双手持哑铃于体侧，核心收紧，躯干正直。\n垂直下蹲，后膝下沉接近地面，前膝与脚尖同向。\n前腿发力站起，完成次数后换腿。", "前脚垫高后重心不稳，应放慢速度控制。\n躯干前倾塌腰。\n前膝内扣或过度超过脚尖。"),
        Seed("wg:deficit-reverse-lunge", "低位后撤箭步蹲", "Deficit Reverse Lunge", "deficit-reverse-lunge", "legs", "Glutes", "Quads,Hamstrings,Core", "Dumbbell", "weight_reps", false, "exercises/legs/deficit-reverse-lunge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "前脚站在低垫高平台上，双手持哑铃于体侧。\n核心收紧，一条腿向后撤步下蹲，前膝与脚尖同向。\n后膝下沉至最低位，保持躯干正直。\n前腿发力站起回到平台，完成次数后换腿。", "平台过高导致失衡与髋部代偿。\n躯干前倾塌腰。\n下落失控砸向地面。"),
        Seed("wg:dumbbell-lateral-lunge", "哑铃侧向箭步蹲", "Dumbbell Lateral Lunge", "dumbbell-lateral-lunge", "legs", "Quads", "Glutes,Adductors,Hamstrings", "Dumbbell", "weight_reps", false, "exercises/legs/dumbbell-lateral-lunge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚并拢站立，双手持哑铃于体前或体侧。\n一条腿向侧方跨出一大步，重心移向该腿并屈膝下蹲。\n侧蹲腿膝盖对准脚尖方向，另一腿伸直，背部平直。\n侧蹲腿发力蹬地收回，换边交替。", "侧蹲腿膝盖内扣，应始终对准脚尖方向。\n躯干过度前倾弓背。\n跨步过小导致膝盖压力过大。"),
        Seed("wg:dumbbell-curtsy-lunge", "哑铃屈膝箭步蹲", "Dumbbell Curtsy Lunge", "dumbbell-curtsy-lunge", "legs", "Glutes", "Quads,Hamstrings,Core", "Dumbbell", "weight_reps", false, "exercises/legs/dumbbell-curtsy-lunge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与髋同宽站立，双手持哑铃于体侧，核心收紧。\n一条腿向后向对侧撤步，呈交叉步姿态。\n双膝屈曲下沉，前膝对准脚尖方向，躯干正直。\n前腿发力站起收回，换腿交替。", "骨盆旋转过度，核心应保持稳定控制方向。\n前膝内扣或压力过大。\n交叉步幅不稳导致失衡。"),
        Seed("wg:landmine-squat", "地雷架深蹲", "Landmine Squat", "landmine-squat", "legs", "Quads", "Glutes,Core", "Barbell", "weight_reps", false, "exercises/legs/landmine-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "杠铃一端扛在肩前，斜握于胸前，站在地雷架一端前侧。\n双脚与肩同宽，核心收紧。\n屈髋屈膝同步下蹲，杠铃斜向稳定住躯干，膝盖与脚尖同向。\n脚掌发力站起，髋膝同步伸直。", "躯干过度前倾压向杠铃。\n膝盖内扣。\n握杠位置不稳导致杠端晃动。"),
        Seed("wg:landmine-romanian-deadlift", "地雷架罗马尼亚硬拉", "Landmine Romanian Deadlift", "landmine-romanian-deadlift", "legs", "Hamstrings", "Glutes,Lower Back", "Barbell", "weight_reps", false, "exercises/legs/landmine-romanian-deadlift/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手持杠铃一端于胸前，双脚与髋同宽站立，膝盖微屈固定。\n核心收紧，以髋为铰链向后推臀，杠端沿身体下放。\n背部保持平直，腘绳肌充分拉伸后臀部发力站直。\n顶端收紧臀部，杠端全程贴近身体。", "弓背下放，腰椎失去中立位。\n膝盖角度变化变成蹲姿。\n杠端离身过远增加腰部负担。"),
        Seed("wg:kettlebell-swing", "壶铃摆荡", "Kettlebell Swing", "kettlebell-swing", "legs", "Glutes", "Hamstrings,Core,Cardio", "Kettlebell", "weight_reps", false, "exercises/legs/kettlebell-swing/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "壶铃置于身前地面，屈髋俯身握把，背部平直。\n向后摆壶铃至两腿之间，髋膝微屈蓄力。\n臀部爆发发力向前推髋，把壶铃甩至胸口高度。\n壶铃下落时顺势屈髋缓冲，连续流畅完成。", "用手臂或肩膀抬壶铃，力量应来自髋部爆发。\n下蹲完成动作，摆荡本质是屈髋不是深蹲。\n顶端腰椎过伸后仰。"),
        Seed("wg:glute-focused-back-extension", "臀向背部伸展", "Glute-Focused Back Extension", "glute-focused-back-extension", "legs", "Glutes", "Hamstrings,Lower Back", "Bodyweight", "bodyweight_reps", false, "exercises/legs/glute-focused-back-extension/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "调整罗马椅使髋部转轴对准髋关节，双脚固定。\n臀部收紧，身体下沉至最低位，保持背部平直。\n用臀部与腘绳肌发力把躯干抬至与腿呈一条直线。\n顶端收紧臀部一秒，不刻意后仰过伸。\n缓慢下放重复。", "顶端腰椎过伸后仰代替臀部收紧。\n弓背完成动作，全程应保持背中立。\n用腰部竖脊肌主导发力而非臀部。"),
        Seed("wg:reverse-hyperextension", "反向挺身", "Reverse Hyperextension", "reverse-hyperextension", "legs", "Glutes", "Hamstrings,Lower Back", "Machine", "bodyweight_reps", false, "exercises/legs/reverse-hyperextension/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "俯卧于反向挺身机上，双手握紧把手，腹部贴紧垫面。\n核心收紧，臀部发力把双腿向后上方抬起。\n抬至躯干与腿接近平齐或略高，停顿一秒收紧臀部。\n缓慢下放双腿，不靠惯性摆动。", "抬高过猛导致腰椎过伸，应控制顶端幅度。\n依靠摆动惯性甩腿而非臀部发力。\n腹部离开垫面，躯干应保持稳定。"),
        Seed("wg:donkey-calf-raise", "驴式提踵", "Donkey Calf Raise", "donkey-calf-raise", "legs", "Calves", "", "Machine", "weight_reps", false, "exercises/legs/donkey-calf-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0275-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "站在踏板或台阶边缘，前脚掌踩实、脚跟悬空，上身俯身扶稳支架。\n保持腰背平直、核心收紧，膝盖自然伸直或微屈并全程固定。\n脚跟尽量下沉感受小腿拉伸，再发力踮起到最高点，顶端停顿一秒。\n下降时缓慢有控制，让小腿全程保持张力。\n呼吸：下沉时吸气，踮起时呼气。", "靠身体弹振借力快速起伏——改为慢起慢落，全程可控。\n膝盖屈伸晃动参与发力——固定膝关节，只让踝关节活动。\n动作幅度过小只做半程——下沉到底、踮起到顶，做全幅度。"),
        Seed("wg:leg-press-calf-raise", "腿举提踵", "Leg Press Calf Raise", "leg-press-calf-raise", "legs", "Calves", "", "Machine", "weight_reps", false, "exercises/legs/leg-press-calf-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0273-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "坐在腿举机上，双脚前掌踩在踏板下缘，脚跟悬空，双腿蹬至接近伸直但不锁膝。\n松开安全销，用前掌将踏板蹬起，保持膝关节角度固定不动。\n脚跟尽量向下沉，感受小腿充分拉伸，稍停一秒。\n前掌发力将脚跟尽量上提，踮到最高点，在顶峰收缩小腿。\n缓慢放下脚跟回到最低点，完成规定次数后锁回安全销。", "用膝盖屈伸借力：变成腿举而不是提踵，膝关节角度应全程固定。\n动作幅度过小：脚跟既不沉到底也不踮到顶，小腿刺激大打折扣。\n重量过大导致臀部离开坐垫或脚跟弹震，容易伤膝伤踝。"),
        Seed("wg:wall-sit", "靠墙静蹲", "Wall Sit", "wall-sit", "legs", "Quads", "Glutes,Core", "Bodyweight", "duration", false, "exercises/legs/wall-sit/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "背靠墙站立，双脚向前走出一大步，与肩同宽。\n沿墙下滑，直到大腿与地面平行、膝关节约呈90度，小腿尽量与地面垂直。\n腰背和后脑贴紧墙面，双手自然下垂或扶在大腿上。\n保持该姿势，均匀呼吸，坚持规定时间。\n时间到后用腿部发力沿墙站起，不要猛然弹起。", "膝关节超过脚尖过多或内扣，压力集中在膝盖，应让小腿接近垂直、膝盖对准脚尖方向。\n用手撑大腿或身体前倾借力，降低股四头肌负荷。\n憋气坚持，应保持匀速呼吸，呼吸不稳往往说明姿势已经变形。"),
        Seed("wg:jump-squat", "跳跃深蹲", "Jump Squat", "jump-squat", "legs", "Quads", "Glutes,Calves", "Bodyweight", "bodyweight_reps", false, "exercises/legs/jump-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与肩同宽站立，核心收紧，先做一次半蹲蓄力。\n腿部爆发发力向上垂直跳起，落地时前脚掌先着地。\n落地瞬间立即屈髋屈膝缓冲，顺势进入下一次半蹲。\n连续完成规定次数，全程保持躯干挺直、膝盖对准脚尖。\n落地越轻越好，若无法保持姿势质量即停止。", "落地膝盖内扣或直腿硬着陆，冲击集中在膝关节，应屈膝缓冲、膝盖对准脚尖。\n跳起时弯腰低头，重心前倾，失去爆发方向，应保持躯干挺直垂直起跳。\n组内动作变形后仍硬撑次数，爆发训练讲究质量而非数量。"),
        Seed("wg:incline-dumbbell-curl", "上斜哑铃弯举", "Incline Dumbbell Curl", "incline-dumbbell-curl", "arms", "Biceps", "Forearms", "Dumbbell", "weight_reps", false, "exercises/arms/incline-dumbbell-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0214-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "将可调凳调至30-45度上斜，背部贴凳坐下，双手各持哑铃垂于身体两侧\n手臂自然垂在肩后方，这是与站立弯举最大的不同，二头起始即被拉长\n呼气屈肘弯举哑铃至肩前，大臂保持垂直固定不前移\n顶端挤压二头，缓慢下放到完全伸直的位置再重复", "大臂随动作向前抬高，长头的拉伸优势丢失\n耸肩用三角肌前束代偿发力\n下放不完全，二头没有在拉长位获得充分刺激"),
        Seed("wg:concentration-curl", "集中弯举", "Concentration Curl", "concentration-curl", "arms", "Biceps", "Forearms", "Dumbbell", "weight_reps", false, "exercises/arms/concentration-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0220-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "坐于凳上，一手握哑铃，同侧手肘抵在同侧大腿内侧固定\n呼气屈肘将哑铃弯举至胸前，手腕保持中立\n顶端用力挤压二头一秒，缓慢下放至手臂接近伸直\n另一只手可扶对侧膝盖或抵住大臂帮助稳定，全程躯干不扭转", "肘部离开大腿失去固定支点，变成自由甩举\n身体向发力侧倾斜扭转借力\n下放过快没有控制，失去离心训练效果"),
        Seed("ex-arm-01", "EZ 杠弯举", "EZ-Bar Curl", "ez-bar-curl", "arms", "Biceps", "Forearms", "Barbell", "weight_reps", false, "exercises/arms/ez-bar-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0226-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "站立双手握EZ杠的波浪弯位，掌心朝内斜向，肩宽握距\n大臂贴紧躯干固定，呼气屈肘将杠弯举至肩前\n顶端挤压二头一秒，缓慢下放至手臂接近伸直\n手腕在弯位上保持自然，不额外翻折", "身体后仰甩杠借力，腰部代偿\n大臂随动作前后摆动，变成肩部参与\n握位错误导致手腕反折受压，EZ杠应握弯位而非直杆处"),
        Seed("wg:spider-curl", "蜘蛛弯举", "Spider Curl", "spider-curl", "arms", "Biceps", "Forearms", "Dumbbell", "weight_reps", false, "exercises/arms/spider-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0245-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "俯卧在上斜凳的靠背斜面（胸口贴凳、手臂垂向地面），双手各持哑铃\n大臂垂直地面固定，肘部不前后移动\n呼气屈肘将哑铃弯举至最高点，顶峰挤压二头\n缓慢下放至手臂完全伸直，让二头在悬垂位充分拉长再重复", "身体在凳上滑动、胸口离开凳面，失去稳定支撑\n大臂随惯性前后摆动，动作变成荡哑铃\n顶端耸肩或手腕翻折，刺激转移到肩腕"),
        Seed("wg:rope-hammer-curl", "绳索锤式弯举", "Rope Hammer Curl", "rope-hammer-curl", "arms", "Biceps", "Forearms", "Cable", "weight_reps", false, "exercises/arms/rope-hammer-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0216-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "滑轮调至低位，双手握绳柄两侧，掌心相对呈锤握\n向后退一步让绳索保持张力，大臂固定在躯干两侧\n呼气屈肘沿弧线弯举，顶端绳柄略微向外分开挤压\n缓慢放回但不让配重片完全落定，保持张力连续", "身体后仰用重心对抗拉力，借力明显\n肘部前移离开躯干，大臂不再固定\n底端配重片落定卸力，丢失绳索持续张力"),
        Seed("wg:drag-curl", "拖曳弯举", "Drag Curl", "drag-curl", "arms", "Biceps", "Forearms", "Barbell", "weight_reps", false, "exercises/arms/drag-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0222-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "站立宽握杠铃垂于体前，肘部主动向后上方移动\n让杠铃全程贴着躯干向上\"拖\"，肘部带动大臂略微后移\n顶端挤压二头，沿原路径贴身缓慢下放\n这个动作刻意避免大臂前抬，肘的位置变化是动作精髓", "像普通弯举一样大臂前抬，动作变成常规弯举\n杠铃离开躯干悬空，失去\"贴身拖曳\"的要领\n重量过大导致身体后仰借力，轨迹变形"),
        Seed("wg:rope-tricep-pushdown", "绳索绳柄下压", "Rope Tricep Pushdown", "rope-tricep-pushdown", "arms", "Triceps", "Shoulders", "Cable", "weight_reps", false, "exercises/arms/rope-tricep-pushdown/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0206-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "滑轮调至高位，双手握绳柄两端，上臂贴紧躯干固定\n呼气肘部不动将绳柄向下、向身体两侧压开，手臂完全伸直时绳柄略向外分开\n顶端挤压三头一秒，缓慢屈肘回到起始位\n躯干微前倾稳定，肘部全程不漂移", "大臂离开躯干前后摆动，变成俯身压重\n身体重量下压借力，肩胸参与过多\n末端没有向外分开绳柄，三头顶峰收缩不完整"),
        Seed("wg:dumbbell-skull-crusher", "双哑铃碎颅者", "Two Dumbbell Skullcrusher", "dumbbell-skull-crusher", "arms", "Triceps", "Shoulders", "Dumbbell", "weight_reps", false, "exercises/arms/dumbbell-skull-crusher/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0181-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧平凳，双手各持一只哑铃举在胸口上方，掌心相对\n大臂保持垂直固定，只弯曲肘部将哑铃缓慢下放至头部两侧\n呼气用三头将哑铃举回顶端，手臂伸直不锁死肘\n全程肘部内收稳定，大臂位置不动", "大臂随下放前后摆动，变成推类动作\n哑铃下放过深过快，砸向头部或失控\n肘部外张，肩关节和手腕承受额外压力"),
        Seed("wg:single-dumbbell-skullcrusher", "单哑铃碎颅者", "Single Dumbbell Skullcrusher", "single-dumbbell-skullcrusher", "arms", "Triceps", "Shoulders", "Dumbbell", "weight_reps", false, "exercises/arms/single-dumbbell-skullcrusher/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧平凳，双手共同托住一只哑铃的一端举在胸口上方\n大臂垂直固定，缓慢屈肘将哑铃下放至额头后方\n呼气用三头发力举回顶端，肘部全程内收不外张\n双手均衡发力，避免一侧突然泄力让哑铃偏向", "双手发力不均，哑铃歪斜失控\n下放过深砸向面部，风险高\n大臂摇摆借力，三头刺激被肩胸替代"),
        Seed("wg:dumbbell-overhead-tricep-extension", "哑铃过顶臂屈伸", "Dumbbell Overhead Tricep Extension", "dumbbell-overhead-tricep-extension", "arms", "Triceps", "Shoulders", "Dumbbell", "weight_reps", false, "exercises/arms/dumbbell-overhead-tricep-extension/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0194-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "坐姿（最好有靠背的凳）双手共同托住一只哑铃顶端，举过头顶伸直手臂\n大臂贴近头部两侧垂直固定，肘部指向天花板\n呼气前臂发力将哑铃举回最高点，肘部尽量不外扩\n缓慢屈肘让哑铃下沉到脑后，充分拉伸三头长头再重复", "大臂前后摆动、肘部不固定，肩部代偿\n腰部反弓、核心松懈，脊柱压力大\n下放幅度太小，长头得不到充分拉长"),
        Seed("wg:single-arm-dumbbell-tricep-extension", "单臂哑铃臂屈伸", "Single Arm Dumbbell Tricep Extension", "single-arm-dumbbell-tricep-extension", "arms", "Triceps", "Shoulders", "Dumbbell", "weight_reps", false, "exercises/arms/single-arm-dumbbell-tricep-extension/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐姿或站姿，单手持哑铃举过头顶伸直手臂，掌心朝前或相对\n大臂贴近头部垂直固定，只移动前臂\n呼气伸直手臂将哑铃举到最高点，挤压三头\n缓慢屈肘下放到脑后，全程肘部指向上方不外张", "大臂歪斜摆动，肘部向侧面漂移\n躯干向对侧倾斜借力，核心失稳\n下放过快失控，哑铃靠近头部存在风险"),
        Seed("wg:bench-dip", "凳上臂屈伸", "Bench Dip", "bench-dip", "arms", "Triceps", "Chest,Shoulders", "Bodyweight", "bodyweight_reps", false, "exercises/arms/bench-dip/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0162-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "双手撑在凳/箱边缘，指尖朝前，双腿前伸脚跟触地，臀部悬空离凳\n缓慢屈肘下沉身体，肘部朝后方弯曲，直到上臂约与地面平行\n呼气发力撑起回到手臂伸直，顶峰挤压三头\n肩胛全程下沉收紧，躯干贴近凳子不要远离", "臀部远离凳子下沉过深，肩部被过度拉伸易受伤\n耸肩含胸，肩胛失稳压力全在肩关节\n屈肘时肘部向外张开，三头刺激减少且肘部受压"),
        Seed("wg:tricep-kickback", "俯身臂屈伸", "Tricep Kickback", "tricep-kickback", "arms", "Triceps", "Shoulders", "Dumbbell", "weight_reps", false, "exercises/arms/tricep-kickback/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0204-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "俯身（可单手撑凳支撑）背部平直，大臂抬至与躯干平行并贴紧体侧固定\n前臂自然下垂，这是起始位\n呼气前臂向后上方摆动，直到手臂完全伸直，挤压三头一秒\n缓慢控制着让前臂回到下垂位置，全程大臂不动", "大臂下垂随动作摆动，变成整个手臂后甩\n俯身时弓背或抬头，脊柱失去中立位\n用惯性甩起哑铃而非三头主动收缩，末端不挤压"),
        Seed("wg:wrist-extension", "腕伸展", "Wrist Extension", "wrist-extension", "arms", "Forearms", "", "Dumbbell", "weight_reps", false, "exercises/arms/wrist-extension/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "前臂放在桌面或大腿上固定，手腕悬出边缘，反握哑铃（掌心朝下）\n手腕缓慢下垂让哑铃向指背方向下沉\n呼气用力伸腕（背伸）将哑铃向上抬到最高点\n顶峰停顿挤压前臂外侧，缓慢下放重复", "前臂离开支撑面翘起，变成整臂发力\n重量过大用甩腕完成，腕关节极易受伤\n速度过快幅度失控，失去对前臂伸肌的孤立刺激"),
        Seed("wg:farmer-carry", "农夫行走", "Farmer Carry", "farmer-carry", "arms", "Forearms", "Upper Back,Core", "Dumbbell", "distance_duration", false, "exercises/arms/farmer-carry/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚站稳，双手各持大重量哑铃垂于体侧，肩胛下沉、胸背挺直\n核心和握力收紧，目视前方开始行走\n步幅适中、步频稳定，躯干不左右摇晃，肩不耸不塌\n走完规定距离后屈髋放下哑铃，不要弯腰甩放", "弯腰驼背或身体侧倾代偿，脊柱受压\n耸肩含胸，肩胛失稳且斜方上部过度紧张\n放下哑铃时弯腰甩落，腰部容易拉伤"),
        Seed("ex-core-02", "卷腹", "Crunch", "crunch", "core", "Core", "", "Bodyweight", "bodyweight_reps", false, "exercises/core/crunch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0291-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧屈膝，双手轻扶头侧或胸前，腰椎贴地\n呼气收紧腹肌，肩胛离开地面，胸椎向骨盆方向卷起\n顶点稍停感受腹肌收缩，不要用手拉头\n吸气缓慢下放，肩胛轻触地面再进行下一次\n全程腰部贴地，用腹肌发力而非颈部", "双手用力拉扯颈部，颈椎受力疼痛\n腰部离地或骨盆翘起，腰椎失去贴地支撑\n靠惯性快速起身，腹肌收缩不充分"),
        Seed("wg:reverse-crunch", "反向卷腹", "Reverse Crunch", "reverse-crunch", "core", "Core", "", "Bodyweight", "bodyweight_reps", false, "exercises/core/reverse-crunch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0287-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧屈膝抬起，大腿垂直地面，腰椎贴地压实\n呼气收紧腹肌，骨盆向胸腔方向卷起，臀部离地\n膝盖向胸口方向卷收，顶点稍停\n吸气缓慢下放，腰椎始终贴地不拱起\n动作由腹肌主导，不要靠腿部摆动", "用腿的惯性摆动代替骨盆卷起，腹部发力不足\n下放时腰椎离地反弓，失去贴地支撑\n幅度过大变成举腿，骨盆没有卷起"),
        Seed("ex-core-04", "俄罗斯转体", "Russian Twist", "russian-twist", "core", "Core", "Shoulders", "Bodyweight", "bodyweight_reps", false, "exercises/core/russian-twist/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐地屈膝，脚跟轻触地面，上身后倾约45度，腰椎挺直不塌\n双手合握于胸前，收紧腹部保持身体稳定\n呼气，用腹肌带动躯干向一侧旋转\n吸气回到中间，再呼气转向另一侧，交替进行\n全程骨盆稳定，旋转来自胸椎和腹肌而非手臂甩动", "弓腰塌背坐姿，腰椎失去中立位\n靠手臂甩动代替躯干旋转，腹肌没有主导\n憋气或呼吸紊乱，应一转一呼配合节奏"),
        Seed("wg:bicycle-crunch", "自行车卷腹", "Bicycle Crunch", "bicycle-crunch", "core", "Core", "Legs", "Bodyweight", "bodyweight_reps", false, "exercises/core/bicycle-crunch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"source\":{\"name\":\"Everkinetic\",\"url\":\"https://github.com/everkinetic/data/blob/main/dist/svg/0284-tension.svg\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\",\"changes\":\"Rasterized on a transparent 512 × 512 canvas, recolored for monochrome display, and vector-traced.\"}}", "仰卧，双手轻扶头侧，双腿抬离地面，腰椎贴地\n呼气卷起上身，一侧肘部转向对侧膝盖，同时另一条腿伸直\n左右交替如蹬自行车，节奏缓慢可控\n每侧顶点稍停感受腹斜肌收缩\n全程腰部贴地，不用手拉头，呼吸均匀", "追求速度快速蹬踏，动作变形且腹肌参与度下降\n腰部离地反弓，腰椎失去贴地支撑\n用手拉扯颈部，颈椎受力"),
        Seed("wg:mountain-climber", "登山跑", "Mountain Climber", "mountain-climber", "core", "Core", "Shoulders,Legs", "Bodyweight", "duration", false, "exercises/core/mountain-climber/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "起始位为高位平板支撑，手腕在肩正下方，身体呈直线\n收紧腹部与臀部，骨盆保持稳定不上下晃动\n双腿交替快速向胸口方向提膝，节奏均匀\n提膝时呼气、还原时吸气，保持呼吸连续\n肩部保持在手腕正上方，重心不后移", "塌腰或撅臀，骨盆随动作大幅晃动\n重心后移变成蹲姿，核心张力丢失\n憋气赶速度，应保持连续呼吸节奏"),
        Seed("ex-core-03", "死虫式", "Dead Bug", "dead-bug", "core", "Core", "Legs", "Bodyweight", "bodyweight_reps", false, "exercises/core/dead-bug/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，双臂伸直指向天花板，双腿屈膝90度抬起，腰椎贴地\n呼气收紧腹肌，将腰椎牢牢压向地面\n缓慢伸直对侧手臂与腿放下，保持腰部不离地\n吸气缓慢收回，换另一侧交替进行\n全程骨盆稳定不晃动，动作越慢越有效", "伸腿时腰部拱起离地，骨盆失去稳定\n动作速度过快，失去对腰椎的控制\n憋气，应配合肢体伸展节奏持续呼吸"),
        Seed("wg:bird-dog", "鸟狗式", "Bird Dog", "bird-dog", "core", "Core", "Glutes,Shoulders", "Bodyweight", "bodyweight_reps", false, "exercises/core/bird-dog/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "四点跪姿，手腕在肩下、膝盖在髋下，背部平直\n收紧腹部，腰椎保持中立，骨盆不歪斜\n缓慢伸直对侧手臂与腿，抬至与躯干同高\n顶点保持2-3秒，感受臀部和核心发力\n缓慢收回换边交替，全程身体不左右晃动", "手脚抬得过高导致塌腰或身体倾斜\n骨盆旋转、髋部歪斜，核心未保持稳定\n速度过快失去控制，应用最慢速度完成"),
        Seed("wg:pallof-press", "抗旋转推举", "Pallof Press", "pallof-press", "core", "Core", "Shoulders", "Cable", "weight_reps", false, "exercises/core/pallof-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧对绳索或弹力带锚点站立，双手握把手于胸前\n远离锚点方向侧移一步制造张力，收紧腹部与臀部\n呼气缓慢将把手向前推出至手臂伸直\n抵抗旋转力保持躯干正对前方2-3秒\n吸气缓慢收回至胸前，完成次数后换边", "躯干被拉力旋转扭转，核心抗旋失败\n耸肩或手腕弯曲，肩部代偿发力\n憋气，推出与收回应配合呼吸节奏"),
        Seed("wg:cable-woodchop", "绳索伐木", "Cable Woodchop", "cable-woodchop", "core", "Core", "Shoulders", "Cable", "weight_reps", false, "exercises/core/cable-woodchop/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧对绳索锚点站立，双脚宽于肩，膝盖微屈，双手握把手于高位\n收紧腹部，腰椎中立，吸气预备\n呼气用腹斜肌带动躯干向对侧下方斜向拉拽，类似伐木\n后腿随转动自然伸展，重心平稳转移\n缓慢回到起始位置，完成次数后换边", "用手臂拉拽代替躯干旋转，腹斜肌参与不足\n旋转时腰椎过度弯曲，失去中立位\n重心大幅偏移失去平衡，应保持下肢稳定"),
        Seed("wg:half-kneeling-pallof-press", "半跪抗旋转推举", "Half-Kneeling Pallof Press", "half-kneeling-pallof-press", "core", "Core", "Glutes,Shoulders", "Cable", "weight_reps", false, "exercises/core/half-kneeling-pallof-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "半跪姿：内侧膝着地，外侧腿在前屈膝90度，侧对绳索锚点\n收紧臀部与前腿臀部，骨盆摆正不旋转\n双手握把手于胸前，制造张力后呼气缓慢前推\n手臂伸直后保持躯干稳定2-3秒，抵抗旋转\n吸气缓慢收回，完成次数后换边换姿势", "骨盆朝锚点方向旋转，髋部未锁住\n前腿膝盖内扣或塌腰，下肢基础不稳\n憋气，推出保持与收回都应持续呼吸"),
        Seed("wg:cable-pallof-hold", "绳索抗旋转保持", "Cable Pallof Hold", "cable-pallof-hold", "core", "Core", "Glutes,Shoulders", "Cable", "duration", false, "exercises/core/cable-pallof-hold/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧对绳索锚点站立，双手握把手于胸前，制造张力\n收紧腹部与臀部，躯干正对前方\n缓慢将把手推至身体正前方伸直手臂\n保持等长对抗，全程躯干不旋转，骨盆稳定\n自然呼吸坚持规定时间后换边", "身体被拉力逐渐旋转，抗旋位置丢失\n耸肩或过度挺胸，肩颈代偿\n憋气硬撑，应全程保持均匀呼吸"),
        Seed("wg:hanging-knee-raise", "悬垂屈膝举腿", "Hanging Knee Raise", "hanging-knee-raise", "core", "Core", "Grip", "Pull-up Bar", "bodyweight_reps", false, "exercises/core/hanging-knee-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手握杠悬垂，肩胛收紧下沉，身体不晃\n呼气收紧腹肌，屈膝向胸口方向抬起\n骨盆微微后倾卷起，膝盖越过髋部高度\n吸气缓慢下放，控制身体不摆荡\n全程保持肩部稳定，用腹肌主导发力", "靠摆荡惯性甩腿，核心发力不足\n骨盆未后倾，只屈髋不卷腹，腰椎反弓\n下放过快失控，肩部和腰椎受冲击"),
        Seed("wg:captains-chair-knee-raise", "罗马椅屈膝举腿", "Captain's Chair Knee Raise", "captains-chair-knee-raise", "core", "Core", "Shoulders", "Machine", "bodyweight_reps", false, "exercises/core/captains-chair-knee-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "前臂撑于罗马椅托板，背部贴紧靠垫，肩部下沉\n收紧腹部，腰椎贴住靠垫\n呼气屈膝向胸口抬起，骨盆微微卷起\n顶点稍停感受腹肌收缩\n吸气缓慢下放，全程不靠惯性摆荡", "背部离开靠垫、塌腰，腰椎失去支撑\n耸肩或肩部耸起承重，肩颈代偿\n下放过快靠摆荡，腹肌没有控制"),
        Seed("wg:decline-sit-up", "下斜仰卧起坐", "Decline Sit-Up", "decline-sit-up", "core", "Core", "Quads", "Bench", "bodyweight_reps", false, "exercises/core/decline-sit-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧于下斜凳，双脚固定于滚轴，双手轻扶头侧或抱胸\n收紧腹部，腰椎贴向凳面\n呼气卷起躯干直至坐直或接近坐直\n顶点稍停，吸气缓慢下放，控制下降速度\n全程用腹肌主导，不用爆发力弹起", "下放过快自由落体，腰椎受冲击\n双手拉扯颈部，颈椎受力\n骨盆离凳、腰部反弓，失去贴地稳定"),
        Seed("wg:weighted-crunch", "负重卷腹", "Weighted Crunch", "weighted-crunch", "core", "Core", "", "Plate", "weight_reps", false, "exercises/core/weighted-crunch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧屈膝，双手将杠铃片或哑铃抱持于胸前，腰椎贴地\n呼气收紧腹肌，肩胛离地卷起上身\n顶点稍停感受腹肌强烈收缩\n吸气缓慢下放，重量全程贴胸不晃\n选择能保持动作质量的重量，循序渐进", "重量过大导致腰部离地或借力猛起\n把重量压在颈部或用手臂甩起，腹肌参与不足\n憋气发力，应呼气卷起、吸气还原"),
        Seed("wg:weighted-russian-twist", "负重俄罗斯转体", "Weighted Russian Twist", "weighted-russian-twist", "core", "Core", "Shoulders", "Dumbbell", "weight_reps", false, "exercises/core/weighted-russian-twist/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐地屈膝，脚跟轻触地面，上身后倾45度，腰椎挺直\n双手抱持哑铃或杠铃片于胸前，收紧腹部\n呼气用腹斜肌带动躯干向一侧旋转，重量随身体移动\n吸气回正，再呼气转向另一侧交替\n全程骨盆与下肢稳定，旋转来自躯干", "重量过大导致弓腰塌背，腰椎失去中立位\n用手臂甩动重量代替躯干旋转\n憋气，每次旋转应配合呼气"),
        Seed("wg:dumbbell-side-bend", "哑铃体侧屈", "Dumbbell Side Bend", "dumbbell-side-bend", "core", "Core", "Grip", "Dumbbell", "weight_reps", false, "exercises/core/dumbbell-side-bend/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "单手持哑铃站立，另一手扶头侧或叉腰，双脚与肩同宽\n收紧腹部，骨盆与躯干保持正面朝前\n呼气向持铃一侧缓慢侧屈，感受对侧腹斜肌拉长\n吸气用对侧腹斜肌发力缓慢拉直身体\n完成次数后换手，全程身体不前后倾", "躯干前后倾或骨盆旋转，变成复合代偿动作\n用爆发力快速侧屈甩动，失去控制\n两侧训练量不等，应左右等量对称完成"),
        Seed("wg:elliptical", "椭圆机", "Elliptical", "elliptical", "legs", "Legs", "Cardio", "Cardio", "duration", false, "exercises/legs/elliptical/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站上椭圆机踏板，双手轻握扶手，双脚全脚掌贴住踏板。\n由腿部带动踏板沿轨道滑行，手脚协调前后推拉。\n保持躯干直立、核心收紧，不要把体重全部压在扶手上。\n通过调节阻力和坡度控制强度，保持规定的心率区间或时长。\n结束前逐渐降低强度缓走几分钟，再下机。", "踮脚尖踩踏板，长期会让小腿过度紧张，应全脚掌受力。\n整个人趴在扶手上，腿部做功大幅减少，训练效果打折。\n幅度小、频率乱地乱蹬，应保持稳定步幅和节奏。"),
        Seed("wg:swimming", "游泳", "Swimming", "swimming", "back", "Back", "Shoulders,Cardio", "Cardio", "distance_duration", false, "exercises/back/swimming/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "自由泳等泳姿中保持核心稳定、身体沿纵轴滚动，划水由背部和肩带动。\n入水后先做抱水、再向后推水，肘部保持高位（高肘抱水）。\n呼吸侧转时躯干整体滚动，不要抬头过高打断身体流线。\n打腿从髋部发力，幅度适中，保持身体位置平稳。\n初学者注意换气节奏与放松，避免因紧张而耸肩。", "直臂划水、肘部下沉：练习高肘抱水，让背部和肩带参与发力。\n耸肩紧张、脖子僵硬：放松肩颈，保持流线型与均匀呼吸。"),
        Seed("wg:jump-rope", "跳绳", "Jump Rope", "jump-rope", "legs", "Calves", "Cardio,Shoulders", "Cardio", "duration", false, "exercises/legs/jump-rope/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "选择长度合适的绳：双脚踩绳中点，手柄拉直到胸口附近为宜。\n双手握柄置于髋侧，用手腕小幅度摇绳，肘部贴近身体。\n前脚掌起跳，跳起高度刚好让绳通过即可，约2-3厘米。\n前脚掌轻落地，膝盖微屈缓冲，保持节奏连续跳。\n初学者可采用跳一下摇一圈的节奏，熟练后再提速或做双摇。", "跳得过高、用手臂大幅抡绳，浪费体力且节奏易断，应小跳并用腕发力。\n全脚掌或脚跟着地，冲击大、易伤膝踝，应前脚掌落地。\n落地时膝盖僵直不缓冲，长期训练易造成下肢劳损。"),
        Seed("wg:assault-bike", "风阻单车", "Assault Bike", "assault-bike", "legs", "Legs", "Cardio,Shoulders", "Cardio", "distance_duration", false, "exercises/legs/assault-bike/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "调节座椅高度，蹬到最低点时膝盖仍保留微弯，握把高度与肩齐平。\n双脚踩住踏板，双手握住活动把手，同时蹬腿和推拉把手。\n四肢协调发力，保持稳定节奏，阻力随输出自动增大。\n按训练计划做匀速有氧或间歇冲刺，注意保持躯干稳定不左右晃。\n结束时逐步降低强度，等踏板减速后再下机。", "座椅过高或过低导致膝盖完全伸直或过度弯曲，应按蹬踏最低点留微弯调整。\n只蹬腿不推拉把手，风阻单车要求四肢同时做功。\n冲刺时身体大幅摇摆借力，既降效率又伤腰背。"),
        Seed("wg:skierg", "滑雪机", "SkiErg", "skierg", "back", "Back", "Triceps,Core,Cardio", "Cardio", "distance_duration", false, "exercises/back/skierg/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与髋同宽站稳，双手握把手，起始时手臂伸直、躯干略前倾。\n发力顺序：先屈髋俯身用躯干和背部带动，再屈肘把把手拉向下腹方向。\n把手拉到位后手臂前送还原，躯干略抬起，回到起始位。\n全程核心收紧，背部平直，用髋部主导的节奏驱动。\n拉桨有力、还原放松，保持均匀稳定的节奏。", "只用手臂猛拉：以髋部屈伸带动，背部和躯干主导发力。\n弓背驼背：保持脊柱中立，用屈髋代替弯腰。"),
        Seed("wg:hiking", "徒步", "Hiking", "hiking", "legs", "Legs", "Glutes,Cardio", "Cardio", "distance_duration", false, "exercises/legs/hiking/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "选择符合体能的路线和坡度，穿登山鞋并背适量负重。\n上坡时身体略前倾，步幅小而稳，全脚掌或前掌踏实着地，善用登山杖分担腿部压力。\n下坡时重心放低、膝盖微屈，侧身或之字形下行，减少膝关节冲击。\n保持匀速行进，定时补水补能，根据心率与呼吸调整节奏。\n结束后做小腿、股四头肌和腘绳肌的拉伸放松。", "下坡直腿猛踏、脚步过快，膝关节承受数倍体重的冲击，易引发膝痛。\n背包过重或路线超出体能，后半程姿势变形、肌肉疲劳易扭伤。\n忽视补水和路面观察，踩到湿滑乱石导致崴脚。"),
        Seed("wg:treadmill-incline-walk", "跑步机上坡走", "Treadmill Incline Walk", "treadmill-incline-walk", "legs", "Legs", "Glutes,Cardio", "Cardio", "distance_duration", false, "exercises/legs/treadmill-incline-walk/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "跑步机设定坡度（如8%-12%）与快走速度（约5-6.5公里/小时）。\n站上跑带后保持躯干直立、核心收紧，双眼平视前方。\n全脚掌滚动式落地，步幅自然，手臂配合摆动。\n全程不扶扶手：扶手会显著降低腿部实际做功，若需扶说明坡度或速度过大。\n结束前逐步降坡降速缓走几分钟再下机。", "扒着扶手身体后仰走，等效坡度归零，练不到臀腿。\n坡度速度设得过高导致弯腰驼背、小碎步，应以后背挺直、步态完整为准。\n速度过快变成小跑，失去上坡走对臀腿的针对性刺激。"),
        Seed("wg:battle-ropes", "战绳", "Battle Ropes", "battle-ropes", "shoulders", "Shoulders", "Core,Cardio", "Cardio", "duration", false, "exercises/shoulders/battle-ropes/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚前后分立或平行站立，屈膝微蹲，核心收紧，双手各握一端绳\n以肩为轴快速交替上下挥动，形成连续波浪传至绳末端\n肩胛保持稳定，挥动幅度固定，肘微屈\n保持呼吸节奏不憋气，每组15-40秒全力或按训练计划\n结束时缓慢减速停绳，甩手放松肩臂", "耸肩驼背、只用小臂：肩下沉，以肩关节带动大臂挥动，全程挺胸收腹\n下背塌陷：屈膝降低重心，臀部后坐，核心绷紧\n憋气导致过早力竭：短促有节奏地呼吸（如每次挥动呼一口），全程不憋"),
        Seed("wg:incline-push-up", "上斜俯卧撑", "Incline Push-up", "incline-push-up", "chest", "Chest", "Triceps,Shoulders,Core", "Bodyweight", "bodyweight_reps", false, "exercises/chest/incline-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手撑在稳固的凳子或台阶上，间距略宽于肩，脚在后身体成一条斜线。\n收紧腹部和臀部，保持核心刚性。\n手肘约45度角弯曲，身体整体向凳子下降到胸口接近凳面。\n胸肌发力把身体推回起始位置，手肘不锁死。\n下降吸气、推起呼气，全程头颈与脊柱保持一条线。", "凳子不稳打滑晃动：选择靠墙或不会滑动的稳固支撑面，先测试稳定性。\n塌腰或撅臀破坏直线：收紧核心和臀部，从脚到头保持一条斜线。\n下降太快用惯性弹起：控制下放速度，推起靠胸肌发力而非反弹。"),
        Seed("wg:knee-push-up", "跪姿俯卧撑", "Knee Push-up", "knee-push-up", "chest", "Chest", "Triceps,Shoulders,Core", "Bodyweight", "bodyweight_reps", false, "exercises/chest/knee-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双膝跪在垫子上，双手撑地略宽于肩，大腿到头保持一条斜线。\n收紧腹部和臀部，膝盖到头保持整体稳定不塌。\n手肘约45度角弯曲，胸部缓缓下降接近地面。\n胸肌发力推起身体，回到手臂接近伸直的位置。\n下降吸气、推起呼气，髋部不要比肩先塌下去。", "只动上半身髋部塌陷：收紧腹部，让肩膀和膝盖同步下降同步推起。\n手肘完全打开平贴地面：手肘保持约45度，与躯干自然夹角。\n臀部高高翘起借力：髋部随身体整体移动，保持膝盖到头一条斜线。"),
        Seed("wg:wide-push-up", "宽距俯卧撑", "Wide Push-up", "wide-push-up", "chest", "Chest", "Shoulders,Triceps,Core", "Bodyweight", "bodyweight_reps", false, "exercises/chest/wide-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手撑地，间距比标准俯卧撑更宽，大约肩宽的1.5倍。\n从头到脚保持一条直线，核心收紧撑住躯干。\n手肘向两侧打开，身体下降到胸口接近地面。\n用胸肌外沿发力推起，感受胸部两侧被挤压。\n下降吸气、推起呼气，肩部保持稳定不下沉耸肩。", "手距太宽给肩部过大压力：控制在肩宽1.5倍左右，肩部不适就收窄一点。\n塌腰导致腰部代偿：收紧腹部和臀部，保持平板姿态。\n下降幅度不足只在浅层移动：降到胸口接近地面再做满推起。"),
        Seed("ex-arm-04", "钻石俯卧撑", "Diamond Push-up", "diamond-push-up", "arms", "Triceps", "Chest,Shoulders,Core", "Bodyweight", "bodyweight_reps", false, "exercises/arms/diamond-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "俯撑姿态，双手食指拇指相触呈钻石形置于胸口正下方\n身体从头到脚踝保持一条直线，核心收紧\n呼气屈肘下沉胸部，肘部贴向躯干两侧\n发力推起回到手臂伸直，全程不塌腰不撅臀", "塌腰撅臀，核心失稳腰部代偿受压\n肘部向外大幅张开，肩肘压力增大\n手位过于靠近脸部或离胸口太远，腕肩受力异常"),
        Seed("wg:decline-push-up", "下斜俯卧撑", "Decline Push-up", "decline-push-up", "chest", "Chest", "Shoulders,Triceps,Core", "Bodyweight", "bodyweight_reps", false, "exercises/chest/decline-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚垫高放在稳固的凳子或台阶上，双手撑地略宽于肩。\n收紧腹部和臀部，从头到脚保持一条下斜直线，核心刚性拉满。\n手肘约45度角弯曲，身体下降到胸口接近地面。\n胸肌发力把身体推起，肩部保持稳定不下沉。\n下降吸气、推起呼气，垫高越高难度越大，量力选择高度。", "垫高物不稳导致脚滑动：选靠墙或固定的支撑面，先试稳再开始。\n核心松掉塌腰：腹部臀部持续收紧，身体不折成两段。\n下降太深压迫肩部：降到胸口有控制的位置即停，不硬压到底。"),
        Seed("wg:pike-push-up", "尖角俯卧撑", "Pike Push-up", "pike-push-up", "shoulders", "Shoulders", "Triceps,Chest,Core", "Bodyweight", "bodyweight_reps", false, "exercises/shoulders/pike-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "从俯卧撑姿势开始，双手略宽于肩，双脚向手方向走近使臀部抬高，身体呈倒V形\n头部位于双手之间偏后，屈肘将头顶向地面方向下放\n肘部约向45度外展下落，至头顶轻触或接近地面\n肩部与三头发力推回起始的倒V形，手臂完全伸直\n下放吸气，推起呼气，核心收紧保持背部平直", "身体下沉变成普通俯卧撑：保持臀部处于最高点，髋角固定，肩在手腕上方移动\n肘部过度外展成T形：肘约45度指向斜外侧，与推举轨迹一致\n塌腰：收腹夹臀，下放全程背部平直，能力不足时缩短下放深度"),
        Seed("wg:feet-elevated-pike-push-up", "垫脚尖角俯卧撑", "Feet-Elevated Pike Push-up", "feet-elevated-pike-push-up", "shoulders", "Shoulders", "Triceps,Chest,Core", "Bodyweight", "bodyweight_reps", false, "exercises/shoulders/feet-elevated-pike-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚放在稳固的凳或箱上，双手略宽于肩撑地，臀部抬高使身体接近垂直倒V形\n肩部位于手腕正上方，屈肘控制下放，头顶向两手之间地面靠近\n至头接近地面后，肩与三头发力垂直推回顶端\n推至手臂完全伸直，肩胛在顶端充分上推锁定\n下放吸气，推起呼气，全程核心绷紧不塌腰", "抬脚过高失去倒V形、变成倒立推不完全：臀部保持最高点，肩始终在腕上方，高度循序渐进\n肘部大外展或内扣：肘约45度向外，与肩推轨迹一致\n凳子不稳或滑动：选用防滑稳固的箱凳，靠墙或在有人保护下练习"),
        Seed("wg:archer-push-up", "弓箭手俯卧撑", "Archer Push-up", "archer-push-up", "chest", "Chest", "Triceps,Shoulders,Core", "Bodyweight", "bodyweight_reps", false, "exercises/chest/archer-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手撑地，间距比肩宽很多，一只手在胸侧、另一只手伸直在远端。\n核心收紧保持平板姿态，身体向主力手一侧下沉。\n主力手弯曲承重，另一只手臂保持伸直，像弓箭手开弓一样。\n主力侧胸肌发力把身体推回中间，两侧交替练习。\n下降吸气、推起呼气，全程身体保持一条线不旋转。", "身体旋转代偿重心：收紧核心， hips和肩膀朝向地面不要扭动。\n两侧强度差距大只做舒适侧：左右交替且次数对称，弱侧先做保证同等强度。\n伸直手那只弯曲泄力：辅助手全程保持伸直，只靠主力侧发力。"),
        Seed("wg:typewriter-push-up", "打字机俯卧撑", "Typewriter Push-up", "typewriter-push-up", "chest", "Chest", "Triceps,Shoulders,Core", "Bodyweight", "bodyweight_reps", false, "exercises/chest/typewriter-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手撑地宽于肩，身体下降到胸口接近地面的低位。\n保持低位不动，把身体重量向一侧手横移过去。\n横移到该侧胸肌被挤压后，再横移滑向另一侧，像打字机滑梭。\n两侧滑移完成后发力推回起始位置，算完成一次。\n全程核心收紧，下降和滑移时控制呼吸节奏，不憋气。", "低位支撑不稳塌腰：收紧腹部臀部，躯干保持平板，撑不住就缩短滑移时间。\n滑移时身体蹭地用手臂拖行：保持身体离地有支撑，靠手臂承担重量左右移。\n只做单侧滑行不平衡：左右两侧都要滑到位，次数对称。"),
        Seed("wg:explosive-push-up", "爆发俯卧撑", "Explosive Push-up", "explosive-push-up", "chest", "Chest", "Triceps,Shoulders,Core", "Bodyweight", "bodyweight_reps", false, "exercises/chest/explosive-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "先摆好标准俯卧撑姿势，双手略宽于肩，核心收紧保持刚性。\n控制身体快速下降到胸口接近地面。\n用胸肌爆发力把身体猛推起，双手可以离地一小段。\n落地时手肘微弯缓冲， immediately衔接下一次下放。\n推起呼气、下降吸气，力量不足时先练普通俯卧撑打好基础。", "落地手肘锁死震伤关节：落地时手肘微屈主动缓冲，像弹簧一样接住。\n基础力量不够硬做：普通俯卧撑能标准完成多组后再练爆发式。\n下降阶段彻底放松砸下去：下降仍要有控制，爆发力用在推起的瞬间。"),
        Seed("wg:hindu-push-up", "印度俯卧撑", "Hindu Push-up", "hindu-push-up", "chest", "Chest", "Shoulders,Triceps,Core", "Bodyweight", "bodyweight_reps", false, "exercises/chest/hindu-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "起始为下犬式：手脚撑地，臀部抬高，身体呈倒V形，眼看脚尖方向。\n头部和胸部沿一条弧线向前下方压过去，接近地面。\n继续前送，身体过渡到上犬式：胸部展开，手臂撑直，髋部贴近地面。\n沿原路把身体推回倒V起始位，连贯完成整个波浪轨迹。\n下压时吸气、回推时呼气，全程动作像波浪一样流畅。", "轨迹变成直线俯卧撑：记住是俯冲划弧的波浪路线，胸贴近地面再抬头挺身。\n腰部塌陷或肩膀耸起：全程收紧核心，肩胛骨保持稳定不下坠。\n速度太快动作变形：放慢节奏，把每个阶段的过渡做完整。"),
        Seed("wg:scapular-push-up", "肩胛俯卧撑", "Scapular Push-up", "scapular-push-up", "back", "Upper Back", "Chest,Shoulders,Core", "Bodyweight", "bodyweight_reps", false, "exercises/back/scapular-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手撑地成俯卧撑起始位，手臂伸直，身体从头到脚保持一条直线。\n保持肘角不变，主动让两块肩胛骨向中间收拢（胸部略下沉）。\n再把肩胛向外推开（上背部略微拱起），一收一推缓慢交替。\n全程核心收紧，身体不塌腰、不撅臀。\n动作幅度不大是正常的，重点是肩胛的主动控制。", "屈肘变成小幅俯卧撑：肘角保持不变，只有肩胛在移动。\n塌腰或耸肩：收紧核心，颈肩放松，肩胛主导运动。"),
        Seed("wg:push-up-shoulder-tap", "俯卧撑拍肩", "Push-up Shoulder Tap", "push-up-shoulder-tap", "core", "Core", "Chest,Shoulders,Triceps", "Bodyweight", "bodyweight_reps", false, "exercises/core/push-up-shoulder-tap/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "起始位为俯卧撑高位，手腕在肩下，身体呈直线\n双脚略宽于肩增加稳定基础\n收紧腹部与臀部，骨盆保持水平不旋转\n单手离地轻拍对侧肩，缓慢放回后换手交替\n全程呼吸均匀，髋部晃动越小越好", "髋部左右大幅摇摆，骨盆失去稳定\n塌腰或撅臀，腰椎失去中立位\n拍肩速度过快失去控制，应缓慢完成"),
        Seed("wg:wall-push-up", "靠墙俯卧撑", "Wall Push-up", "wall-push-up", "chest", "Chest", "Triceps,Shoulders", "Wall", "bodyweight_reps", false, "exercises/chest/wall-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "面对墙站立，距离一臂左右，双手撑墙略宽于肩，高度与胸平齐。\n脚跟着地站稳，收紧腹部，身体保持一条斜线。\n手肘约45度角弯曲，身体向墙面倾过去，胸口接近墙面。\n胸肌发力把身体推回直立，手肘不锁死。\n推起呼气、下降吸气，站得越远难度越大。", "踮脚或脚离地借力：双脚全掌踩实地面，身体整体前倾完成动作。\n塌腰撅臀身体打折：收紧腹部，从脚到头保持一条直线。\n只靠手臂推墙不管胸：下降时想象胸口贴近墙面，推起时感受胸肌收紧。"),
        Seed("wg:wall-walk", "靠墙爬行", "Wall Walk", "wall-walk", "shoulders", "Shoulders", "Core,Chest,Triceps", "Wall", "bodyweight_reps", false, "exercises/shoulders/wall-walk/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "面墙俯卧撑姿势起始，双脚沿墙向上走，同时双手逐步向墙靠近\n双脚爬至臀部以上高度、身体接近贴墙倒立时停住，收紧腹臀保持身体成直线\n双手继续向墙靠近至胸口贴近墙面\n按原路手脚交替退回地面，全程控制速度\n上爬时正常呼吸不憋气，全程核心绷紧", "塌腰、腹部下沉：全程收腹夹臀，身体保持一条直线\n头部前探撞墙：保持头在双臂之间中立位，与墙面保持一小段距离\n下落时失控跌落：倒退时手脚交替缓慢进行，全程预留退路，初学者在垫上进行并有人保护"),
        Seed("wg:wall-handstand-push-up", "靠墙倒立撑", "Wall Handstand Push-up", "wall-handstand-push-up", "shoulders", "Shoulders", "Triceps,Core,Chest", "Wall", "bodyweight_reps", false, "exercises/shoulders/wall-handstand-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "面墙手倒立：双手离墙约15-30厘米撑地，蹬墙或爬墙进入倒立，身体成直线，脚跟轻靠墙\n屈肘控制下放，头顶向地面靠近，肘约45度外展\n下放至可控最低点（头轻触垫面），肩与三头发力推回\n推至手臂完全伸直，肩胛上推，身体保持直线\n下放吸气，推起呼气，全程呼吸连贯不憋气", "塌腰拱背变成香蕉形：收腹夹臀，从手腕到脚尖保持一条直线\n下放过深超出肩部控制能力：先在地面标记可控深度（用书本垫头），逐步加深\n落地失控：先掌握安全下法（落地式或下墙），在垫上练习并有人保护，肩痛立即停止"),
        Seed("wg:handstand-push-up", "倒立撑", "Handstand Push-up", "handstand-push-up", "shoulders", "Shoulders", "Triceps,Core,Chest", "Bodyweight", "bodyweight_reps", false, "exercises/shoulders/handstand-push-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "在能稳定自由倒立的基础上进行，双手与肩同宽撑地，身体垂直成一条直线\n屈肘控制下放，肘约45度外展，头顶向地面靠近\n到可控最低点后，肩与三头发力垂直推回顶端\n顶端手臂完全伸直，肩胛上推锁定，重心稳定在手腕上方\n下放吸气，推起呼气，通过持续微调手指压力维持平衡", "倒立不稳就强行加推举：先能在自由倒立保持60秒以上再练习推举，先做部分行程\n塌腰或腿部前甩打破直线：收腹夹臀绷直脚尖，用手指抓地和肩部微调平衡\n无保护练习摔落：在垫上进行，掌握落地保护技术，疲劳时立即停止"),
        Seed("wg:chair-dip", "椅子臂屈伸", "Chair Dip", "chair-dip", "arms", "Triceps", "Chest,Shoulders", "Chair", "bodyweight_reps", false, "exercises/arms/chair-dip/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "背对稳固的椅子，双手撑住椅面前缘，指尖朝前，双腿前伸或屈膝\n缓慢屈肘下沉身体，肘部朝后方弯曲，臀部贴近椅子垂直下沉\n呼气发力撑起至手臂伸直，挤压三头\n肩胛下沉收紧，全程躯干贴近椅子", "椅子不稳固打滑或倾倒，务必确认安全后再做\n下沉过深肩部被过度拉伸，肩前侧易拉伤\n耸肩、肘部外张，压力转移到肩关节"),
        Seed("wg:doorway-row", "门框划船", "Doorway Row", "doorway-row", "back", "Back", "Biceps,Upper Back,Core", "Doorway", "bodyweight_reps", false, "exercises/back/doorway-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "面对门框站立，双手抓住门框两侧（约胸口高度），双脚前移让身体后倾成斜线。\n保持身体从头到脚一条直线，肩胛先向后收紧。\n屈肘把胸口拉向门框，感受上背收缩，顶端停顿。\n缓慢伸臂还原，身体回到初始倾斜角度。\n调整脚的位置控制身体倾角来增减难度。", "塌腰、臀部后坐断线：收紧核心和臀部，保持刚性直线。\n只用手臂拉：先收肩胛再屈肘，用背部主导。"),
        Seed("wg:towel-row", "毛巾划船", "Towel Row", "towel-row", "back", "Back", "Biceps,Upper Back,Core", "Towel", "bodyweight_reps", false, "exercises/back/towel-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "把毛巾绕在稳固的柱子或门把手上，双手握住两端，身体后倾成斜线，手臂伸直。\n保持从头到脚一条直线，核心收紧。\n肩胛先收紧，再把毛巾拉向胸口方向，肘部贴近身体。\n顶端停顿感受上背收缩，缓慢伸臂还原。\n调整身体倾角或握点高度来控制难度。", "身体折角、塌腰：保持刚性直线，臀部收紧。\n靠手腕拧毛巾借力：握稳后由肩胛和肘部完成拉的动作。"),
        Seed("wg:prone-y-raise", "俯卧 Y 字抬起", "Prone Y Raise", "prone-y-raise", "back", "Upper Back", "Rear Delts,Shoulders", "Bodyweight", "bodyweight_reps", false, "exercises/back/prone-y-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "俯卧在垫子或斜凳上，双臂伸直举过头顶呈 Y 字形，拇指朝上。\n肩胛先向内下方收紧，再把双臂整体抬离地面。\n顶端感受上背和肩后束收缩，停顿一至两秒。\n缓慢下放还原，保持控制。\n颈部保持中立，不要抬头过高。", "用耸肩或甩动抬臂：肩胛先启动，缓慢控制，不要靠惯性。\n头部过度后仰：眼睛看向地面，颈脊保持一条线。"),
        Seed("wg:prone-t-raise", "俯卧 T 字抬起", "Prone T Raise", "prone-t-raise", "back", "Upper Back", "Rear Delts,Shoulders", "Bodyweight", "bodyweight_reps", false, "exercises/back/prone-t-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "俯卧，双臂向两侧平伸呈 T 字形，拇指朝上。\n肩胛先向脊柱方向收紧，再把双臂抬离地面。\n顶端感受上背中部和肩后束收缩，停顿一至两秒。\n缓慢下放，全程控制，不靠甩动。\n颈部中立，呼吸自然。", "手臂弯曲或用手代偿：保持手臂伸直，发力来自肩胛收紧。\n抬得过快过高靠惯性：小幅、慢速、有停顿地完成。"),
        Seed("wg:superman", "超人式", "Superman", "superman", "core", "Lower Back", "Glutes,Upper Back,Hamstrings", "Bodyweight", "bodyweight_reps", false, "exercises/core/superman/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "俯卧，双臂前伸过头，双腿伸直，额头轻触地面\n呼气收紧下背与臀部，同时抬起双臂双腿和胸口\n抬起至腹部仍贴地的最大幅度，保持1-2秒\n吸气缓慢放下，颈部保持中立不抬头\n全程动作缓慢可控，腰椎不承受弹震", "抬得过高、腹部离地过度反弓腰椎\n颈部过度后仰抬头，颈椎受压\n用爆发力快速起落，应慢起慢落"),
        Seed("wg:superman-hold", "超人式保持", "Superman Hold", "superman-hold", "core", "Lower Back", "Glutes,Upper Back,Hamstrings", "Bodyweight", "duration", false, "exercises/core/superman-hold/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "俯卧，双臂前伸，双腿伸直，额头轻触地面\n呼气收紧下背与臀部，抬起双臂双腿与胸口\n保持在腹部贴地的等长位置，腰椎不反弓过度\n全程自然呼吸不憋气，坚持规定时间\n缓慢放下，放松几秒后再进行下一组", "为延长时间抬得过高，腰椎过度受压\n憋气硬撑，应保持均匀呼吸\n颈部抬起后仰，颈椎失去中立位"),
        Seed("wg:reverse-snow-angel", "反向雪天使", "Reverse Snow Angel", "reverse-snow-angel", "back", "Upper Back", "Rear Delts,Lower Back,Shoulders", "Bodyweight", "bodyweight_reps", false, "exercises/back/reverse-snow-angel/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "俯卧，双臂伸直放在身体两侧或头顶前方，额头贴地或看向地面。\n肩胛先收紧，双臂缓慢沿弧线从体侧划向头顶方向（如画雪天使）。\n全程手臂尽量不触地，保持上背持续收缩。\n划到头顶后再缓慢划回体侧，动作匀速控制。\n颈部保持中立，核心微收。", "动作过快靠惯性：放慢速度，让上背全程维持张力。\n抬头耸肩：眼睛看向地面，肩部放松下沉，由肩胛主导。"),
        Seed("wg:dead-hang", "悬垂", "Dead Hang", "dead-hang", "arms", "Forearms", "Lats,Shoulders,Core", "Pull-up Bar", "duration", false, "exercises/arms/dead-hang/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手与肩同宽正握单杠，身体自然悬垂\n肩胛保持轻微下沉激活，不耸肩也不完全松掉\n手臂伸直，全身放松但核心微收，均匀呼吸\n坚持到规定时间，落地时屈膝缓冲", "耸肩缩脖子，肩部紧张代偿且易疲劳受伤\n身体大幅摆动，失去稳定悬垂的训练目的\n下杠时直接松手跳落，落地无缓冲易伤膝盖脚踝"),
        Seed("wg:active-hang", "主动悬垂", "Active Hang", "active-hang", "back", "Lats", "Upper Back,Forearms,Core", "Pull-up Bar", "duration", false, "exercises/back/active-hang/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手略宽于肩握单杠悬挂，先放松悬挂一瞬感受肩部被拉开。\n随后肩胛主动下沉收紧，把身体拉高几厘米，肩部离开耳朵方向。\n保持这个收紧的悬挂姿态，核心微收、身体不晃。\n按时间保持，呼吸自然，不要憋气。\n这是引体向上和肩部健康的基础动作，做到可控的时长即可。", "一直死挂放松耸肩：全程保持肩胛下沉收紧的主动状态。\n身体前后晃动：收紧核心，双腿并拢或微屈，保持静止。"),
        Seed("wg:scapular-pull-up", "肩胛引体向上", "Scapular Pull-up", "scapular-pull-up", "back", "Lats", "Upper Back,Forearms,Core", "Pull-up Bar", "bodyweight_reps", false, "exercises/back/scapular-pull-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "握杠悬挂，手臂伸直，从放松悬挂开始。\n肩胛主动下沉收紧，把身体小幅拉高，肘部保持伸直。\n顶端停顿一至两秒，缓慢下放回放松悬挂。\n全程手臂不弯，动作只发生在肩胛。\n这是建立引体向上肩胛启动能力的基础练习。", "屈肘变成小幅引体：手臂始终伸直，只用肩胛下沉发力。\n幅度追求过大：几厘米的小幅位移即可，重点是肩胛控制。"),
        Seed("wg:negative-pull-up", "离心引体向上", "Negative Pull-up", "negative-pull-up", "back", "Lats", "Biceps,Upper Back,Forearms", "Pull-up Bar", "bodyweight_reps", false, "exercises/back/negative-pull-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "借助凳子或跳跃到达引体向上顶端（下巴过杆）位置。\n缓慢下放，用 3-5 秒控制离心过程直到手臂接近伸直。\n下放全程保持肩胛收紧、身体稳定不晃。\n回到顶端可再次借助凳子或跳跃，重复完成。\n适合还不能完成标准引体的人建立力量。", "下放过快失去控制：放慢离心速度到 3 秒以上才有训练价值。\n肩部松弛塌陷：全程肩胛保持收紧，避免肩部被硬拉。"),
        Seed("wg:commando-pull-up", "对握引体向上", "Commando Pull-up", "commando-pull-up", "back", "Lats", "Biceps,Upper Back,Core", "Pull-up Bar", "bodyweight_reps", false, "exercises/back/commando-pull-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手沿单杠前后错位握杠（一手在前一手在后），身体侧对杠悬挂。\n肩胛先下沉收紧，把身体向上拉并略向一侧偏移，让头从杠的一侧越过。\n顶端停顿，缓慢下放回到悬挂。\n换侧或每次交替越过方向，保持两侧均衡训练。\n核心收紧防止身体扭转摆动。", "身体扭转甩动借力：收紧核心，动作由背部和手臂完成。\n两侧训练量不对称：交替进行，保证左右均衡。"),
        Seed("wg:l-sit-pull-up", "L 坐引体向上", "L-Sit Pull-up", "l-sit-pull-up", "back", "Lats", "Biceps,Core,Forearms", "Pull-up Bar", "bodyweight_reps", false, "exercises/back/l-sit-pull-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "握杠悬挂后抬起双腿至与地面平行（L 形），核心收紧固定姿态。\n肩胛先下沉，肘部引导把身体拉至下巴过杆，同时保持 L 姿不塌。\n顶端停顿，缓慢下放，双腿全程保持水平。\n呼吸配合，避免憋气。\n先确认能稳定完成多个标准引体和悬垂举腿再尝试此变式。", "L 姿塌陷、腿逐渐下垂：核心力量不足时先分别练好引体和悬垂举腿。\n摆动借力：固定躯干和腿，减小速度，以控制为先。"),
        Seed("wg:towel-pull-up", "毛巾引体向上", "Towel Pull-up", "towel-pull-up", "back", "Lats", "Biceps,Forearms,Upper Back", "Towel", "bodyweight_reps", false, "exercises/back/towel-pull-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "把毛巾搭在单杠上，双手分别握住毛巾两端，悬挂时肩胛先下沉收紧。\n握力和前臂会大量参与，握稳后肘部引导把身体拉至下巴过杆。\n顶端停顿，缓慢下放至手臂接近伸直。\n全程核心收紧、身体不摆动。\n毛巾要绕杠固定牢靠，确认承重安全后再开始。", "握力先于背部力竭：握力不足时先练握力，或缩短组次保证动作质量。\n毛巾滑动移位：每次开始前确认毛巾缠绕稳固、两端长度合适。"),
        Seed("wg:bodyweight-squat", "自重深蹲", "Bodyweight Squat", "bodyweight-squat", "legs", "Quads", "Glutes,Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/bodyweight-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与肩同宽或略宽，脚尖自然外展15-30度，手臂前平举平衡。\n屈髋屈膝同时下蹲，臀部向后坐，膝盖对准脚尖方向。\n下蹲至大腿与地面平行或更低，保持腰背挺直、重心落在全脚掌。\n脚跟发力站起，站直时臀部收紧。\n完成规定次数，全程保持呼吸节奏：下蹲吸气、起身呼气。", "膝盖内扣，长期会给膝关节带来异常应力，应有意识让膝盖对准脚尖。\n脚跟离地、重心前移到脚尖，应将重心保持在全脚掌。\n弯腰弓背或过度前倾，核心失稳，下蹲时应像坐椅子一样向后坐。"),
        Seed("wg:pistol-squat", "手枪深蹲", "Pistol Squat", "pistol-squat", "legs", "Quads", "Glutes,Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/pistol-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "单腿站立，另一条腿伸直前抬，双臂前伸维持平衡。\n支撑腿屈髋屈膝缓慢下蹲，非支撑腿全程伸直不触地。\n蹲至最低点（臀部接近脚跟），保持腰背挺直、支撑脚全脚掌贴地。\n腿部发力站起，回到单腿站立姿态。\n先扶支撑物练习降低难度，逐步过渡到完全徒手。", "支撑脚跟离地或脚尖外撇借力，说明踝关节活动度不足，应先练踝部灵活性。\n下蹲速度失控直接砸到底，失去离心控制，容易伤膝。\n躯干大幅前倾含胸，用身体重量代偿，应尽量挺直躯干保持重心在支撑腿上。"),
        Seed("wg:assisted-pistol-squat", "辅助手枪深蹲", "Assisted Pistol Squat", "assisted-pistol-squat", "legs", "Quads", "Glutes,Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/assisted-pistol-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "面对稳固支撑物（门框、TRX、栏杆）单腿站立，另一条腿伸直前抬。\n双手轻握支撑物，单腿缓慢下蹲，用支撑物分担部分体重。\n蹲至能力范围内的最低点，保持支撑脚全脚掌贴地、腰背挺直。\n发力站起，逐渐减少手的拉力。\n随力量提升降低辅助力度，向徒手手枪深蹲过渡。", "靠手臂猛拉起身，辅助变成主要动力源，应让腿承担大部分发力。\n蹲得太深超出控制能力，底部姿势崩塌，深度应随能力逐步增加。\n支撑腿膝盖内扣，需始终对准脚尖方向。"),
        Seed("wg:shrimp-squat", "虾式深蹲", "Shrimp Squat", "shrimp-squat", "legs", "Quads", "Glutes,Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/shrimp-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "单腿站立，另一条腿屈膝，同侧手从身后握住该脚背，使后脚贴近臀部。\n保持躯干直立，支撑腿缓慢屈膝下蹲。\n蹲至后侧膝盖轻轻接近地面，全程腰背挺直、重心落在支撑腿。\n支撑腿发力站起回到站立位。\n完成一侧规定次数后换腿，初期可靠墙或扶物辅助平衡。", "躯干过度前倾来平衡，削弱股四头肌刺激，应尽量保持上身直立。\n支撑膝盖过度超过脚尖且失控下坠，应控制离心速度。\n后腿拉着身体旋转、髋部歪斜，应保持骨盆正对前方。"),
        Seed("wg:cossack-squat", "哥萨克深蹲", "Cossack Squat", "cossack-squat", "legs", "Quads", "Glutes,Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/cossack-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚远宽于肩站立，脚尖略外展。\n重心移向一侧，该腿屈膝下蹲，另一腿伸直、脚尖翘起，形成侧向弓步蹲姿。\n蹲至屈膝腿大腿平行地面或更低，伸直腿的腘绳肌有拉伸感，蹲姿腿的脚跟不抬起。\n腿部发力推起，重心回到中间。\n左右交替完成规定次数。", "蹲姿侧脚跟抬起或脚尖离地，说明活动度不够，幅度应循序渐进。\n屈膝腿膝盖内扣，应让膝盖始终对准脚尖方向。\n弯腰驼背低头，应保持躯干挺直、核心收紧。"),
        Seed("wg:sissy-squat", "西西深蹲", "Sissy Squat", "sissy-squat", "legs", "Quads", "Core,Calves", "Bodyweight", "bodyweight_reps", false, "exercises/legs/sissy-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与髋同宽站立，一手扶固定物辅助平衡。\n脚跟抬起、以前掌支撑，膝盖向前移动，同时躯干与大腿保持一条直线向后倾斜。\n缓慢下蹲，膝盖继续前送，身体整体后倾形成一条斜线。\n蹲至能力所及深度（膝盖接近地面为极限），感受股四头肌充分收缩。\n股四头肌发力站起回到起始位，全程保持身体斜线不折断。", "屈髋弯腰、上半身与大腿折成直角，失去该动作对股四头肌的孤立拉伸刺激。\n下蹲过快砸到膝盖，应全程缓慢控制，尤其离心阶段。\n负重大或幅度超出关节能力，膝盖前端疼痛时应立即减小深度。"),
        Seed("ex-leg-05", "箭步蹲", "Forward Lunge", "forward-lunge", "legs", "Quads", "Glutes,Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/forward-lunge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚并拢站立，核心收紧。\n一腿向前迈出一大步，前脚全脚掌落地。\n身体垂直下沉，前腿膝盖对准脚尖、约呈90度，后腿膝盖接近地面但不触地。\n前腿脚跟发力蹬地站起，收腿回到起始位。\n两腿交替完成规定次数。", "前膝超过脚尖过多且重心前压，膝关节压力剧增，应身体垂直下落。\n前膝内扣或外撇，应始终对准脚尖方向。\n后膝砸地，失去离心控制，容易撞伤膝盖。"),
        Seed("wg:lateral-lunge", "侧向箭步蹲", "Lateral Lunge", "lateral-lunge", "legs", "Quads", "Glutes,Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/lateral-lunge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚并拢站立，核心收紧。\n一腿向侧方迈出一大步，脚尖朝前或略外展。\n重心移向迈出腿，屈髋屈膝侧向下蹲，蹲姿腿膝盖对准脚尖，另一腿伸直、脚尖翘起。\n蹲至大腿与地面接近平行，感受内侧腿的拉伸。\n蹲姿腿发力推起，收腿回到起始位，左右交替。", "蹲姿侧脚跟离地或脚尖外撇过度，力线偏移伤膝，应全脚掌受力、膝盖对准脚尖。\n弯腰弓背代替屈髋，应保持腰背挺直、臀部后坐。\n下蹲深度不足只做形式上的侧移，应蹲到大腿接近平行才有训练价值。"),
        Seed("wg:curtsy-lunge", "屈膝箭步蹲", "Curtsy Lunge", "curtsy-lunge", "legs", "Glutes", "Quads,Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/curtsy-lunge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与髋同宽站立，双手叉腰或持哑铃垂于体侧。\n一腿向后斜撤，越过身体中线落到对侧后方，呈交叉蹲姿。\n身体垂直下沉，前腿膝盖对准前方，感受臀部外侧的收缩。\n前腿发力站起，收腿回到起始位。\n两腿交替完成规定次数。", "撤步距离过近导致前膝不稳、力线歪斜，撤步应足够远让重心稳定。\n躯干过度旋转前倾，应保持骨盆与肩膀基本朝前。\n膝盖内扣，交叉蹲姿尤其要注意前膝对准脚尖方向。"),
        Seed("wg:skater-squat", "滑冰者深蹲", "Skater Squat", "skater-squat", "legs", "Quads", "Glutes,Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/skater-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "单腿站立，另一条腿屈膝后伸，脚尖点地于支撑腿后方斜侧（类似滑冰姿势）。\n双臂前伸或胸前合抱维持平衡，躯干略前倾但腰背挺直。\n支撑腿缓慢屈膝下蹲，后伸腿随之向后延展但不承担体重。\n蹲至能力所及深度，保持髋部水平不旋转。\n支撑腿发力站起，完成一侧后换腿。", "后侧脚偷偷承重分担负荷，应保持它仅轻点地维持平衡。\n骨盆旋转倾斜，应锁住髋部朝正前方。\n下蹲失控幅度过大，应先在可保持平衡与力线的深度内练习。"),
        Seed("wg:single-leg-box-squat", "单腿箱式深蹲", "Single-Leg Box Squat", "single-leg-box-squat", "legs", "Quads", "Glutes,Hamstrings,Core", "Box", "bodyweight_reps", false, "exercises/legs/single-leg-box-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "背对稳固的箱子或凳子单腿站立，另一腿伸直前抬，双臂前伸平衡。\n支撑腿屈髋屈膝缓慢下蹲，臀部向后坐向箱面。\n轻触箱面（不完全坐实）即发力站起，全程支撑脚全脚掌贴地。\n起身至单腿站立，臀部收紧。\n完成一侧规定次数后换腿，箱子高度随能力逐步降低。", "一屁股坐实箱面再弹起，失去张力，应轻触即起。\n支撑脚跟离地或膝盖内扣，力线破坏易伤膝。\n下蹲速度过快用惯性起身，应全程缓慢控制离心。"),
        Seed("wg:step-down", "下台阶", "Step-Down", "step-down", "legs", "Quads", "Glutes,Hamstrings,Calves", "Box", "bodyweight_reps", false, "exercises/legs/step-down/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站在稳固的箱子或台阶上，单脚支撑，另一腿悬空于箱侧。\n悬空腿缓慢向下探，支撑腿屈膝降低身体，直到悬空脚轻触地面。\n支撑腿发力站起，回到箱面上的站立位，全程手臂前伸平衡。\n悬空脚只轻触地面不承重，立即再次下探。\n完成一侧规定次数后换腿，箱子高度随能力调整。", "落地腿承重借力蹬起，应让支撑腿独立完成全部工作。\n下落速度失控直接砸到底，离心阶段必须缓慢受控。\n支撑膝盖内扣或躯干歪斜，应保持膝盖对准脚尖、髋部水平。"),
        Seed("ex-leg-06", "提踵", "Calf Raise", "calf-raise", "legs", "Calves", "", "Bodyweight", "bodyweight_reps", false, "exercises/legs/calf-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚与髋同宽站立，可手扶稳固物平衡，前脚掌踩实地面。\n脚跟尽量上提至最高点，顶峰收缩小腿一秒。\n缓慢放下脚跟至最低点，让小腿充分拉伸，脚跟可略低于前掌水平（站在台阶边缘时）。\n按节奏重复完成规定次数。\n全程膝盖保持伸直但不锁死。", "动作幅度小、快速弹震式做，应完整上提与下沉并控制节奏。\n屈膝借力变成弹跳，膝盖应保持稳定伸直。\n重心偏到脚趾外侧，力线歪斜，应前掌均匀受力。"),
        Seed("wg:single-leg-calf-raise", "单腿提踵", "Single-Leg Calf Raise", "single-leg-calf-raise", "legs", "Calves", "Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/single-leg-calf-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "单腿前掌站在台阶边缘，脚跟悬空，另一脚勾在支撑腿小腿后，手扶固定物平衡。\n脚跟下沉到最低点，充分拉伸小腿。\n前掌发力将脚跟提到最高点，顶峰收缩一秒。\n缓慢还原到最低点。\n完成一侧规定次数后换腿。", "扶重物过多把体重卸掉，应只用手扶维持平衡，重量留在支撑腿。\n膝盖弯曲借力，支撑腿应保持伸直。\n脚跟下沉不彻底，幅度不完整，刺激大减。"),
        Seed("wg:glute-bridge-march", "臀桥抬腿", "Glute Bridge March", "glute-bridge-march", "legs", "Glutes", "Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/glute-bridge-march/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧屈膝，双脚踩地，抬起髋部成臀桥姿态，肩髋膝呈一条直线。\n保持髋部水平不塌，一侧腿屈膝向胸口抬起。\n该脚缓慢落回踩地，再换另一侧抬腿。\n左右交替完成规定次数，臀肌持续收紧维持桥姿。\n结束时缓慢放回髋部落地。", "抬腿瞬间髋部下沉或歪斜，应锁住臀桥姿态、骨盆保持水平。\n用腰部反弓顶起代替臀肌发力，应在顶端夹紧臀部。\n抬腿过高导致腰代偿，屈膝抬至大腿接近垂直即可。"),
        Seed("wg:frog-pump", "蛙式臀桥", "Frog Pump", "frog-pump", "legs", "Glutes", "Hamstrings", "Bodyweight", "bodyweight_reps", false, "exercises/legs/frog-pump/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，双脚脚掌相对合拢（蛙式），双膝向两侧打开，脚跟靠近臀部。\n脚跟和上背撑地，臀部发力将髋部向上顶起。\n顶端用力夹紧臀部，稍停一秒。\n缓慢放下髋部回到接近地面的位置，不停留即开始下一次。\n连续完成规定次数，保持短促节奏。", "用腰椎反弓代替臀肌顶髋，顶端应靠夹紧臀部发力。\n膝盖过度内收，应保持双膝外展、脚掌合拢的姿态。\n顶端不停留快速甩动，失去顶峰收缩意义。"),
        Seed("wg:donkey-kick", "驴踢腿", "Donkey Kick", "donkey-kick", "legs", "Glutes", "Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/donkey-kick/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "四点跪姿，双手位于肩下，双膝位于髋下，核心收紧保持腰背平直。\n一侧腿屈膝约90度，用臀部发力将大腿向后上方抬起，脚掌朝上。\n抬至大腿与地面平行或略高、与躯干接近平齐的位置，顶端夹紧臀部。\n有控制地放下回到起始位。\n完成一侧规定次数后换腿。", "过度抬高导致腰椎塌陷反弓，抬到臀部夹紧即可，腰背始终平直。\n腿向侧面打开借力，应保持发力方向正后方上方。\n用甩腿惯性完成，应慢起慢落、全程臀肌控制。"),
        Seed("wg:fire-hydrant", "消防栓式", "Fire Hydrant", "fire-hydrant", "legs", "Glutes", "Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/fire-hydrant/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "四点跪姿，双手位于肩下，双膝位于髋下，核心收紧腰背平直。\n保持屈膝约90度，一侧腿向身体侧方抬起，像消防栓开阀。\n抬至大腿与地面接近平行，感受臀部外侧收缩，稍停。\n有控制地放下回到起始位。\n完成一侧规定次数后换腿。", "躯干向对侧大幅倾斜代偿，应保持骨盆稳定、上身不动。\n腰椎反弓塌腰，全程核心收紧保持背平。\n甩腿借惯性，应缓慢抬起与放下。"),
        Seed("wg:clamshell", "蚌式开合", "Clamshell", "clamshell", "legs", "Glutes", "Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/clamshell/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧卧，双膝屈曲叠放约90度，双脚并拢，头枕手臂或枕在手侧。\n保持双脚相触，上方膝盖向上打开像蚌壳张开。\n打开至最大幅度，感受臀部外侧收缩，稍停一秒。\n缓慢合拢回到起始位。\n完成一侧规定次数后换边，可在膝上方加弹力带增加阻力。", "骨盆向后翻滚代替髋外展，应保持骨盆垂直地面稳定不动。\n幅度小而快地乱开合，应慢开慢合并在顶端停顿。\n双脚分离借力，双脚全程保持相触。"),
        Seed("wg:hip-airplane", "髋部飞机式", "Hip Airplane", "hip-airplane", "legs", "Glutes", "Hamstrings,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/hip-airplane/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "单腿站立，另一腿向后伸直抬起，双手可前伸或抱胸，躯干前倾至与地面约45度并保持腰背平直。\n锁住髋部，通过髋关节内旋带动骨盆和肩膀向一侧旋转。\n反向做髋外旋，把骨盆和肩膀旋到另一侧。\n像飞机螺旋桨一样左右缓慢摆动数次，支撑腿和骨盆保持稳定。\n回到直立位，完成一侧后换腿。", "躯干屈曲弓背代替屈髋前倾，应保持腰背平直的髋铰链。\n靠腰和肩乱转而髋部不动，旋转必须来自支撑侧髋关节。\n支撑腿膝盖乱晃内扣，应锁住膝盖对准脚尖。"),
        Seed("wg:side-lying-hip-abduction", "侧卧髋外展", "Side-Lying Hip Abduction", "side-lying-hip-abduction", "legs", "Glutes", "Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/side-lying-hip-abduction/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧卧，身体呈一条直线，下方手臂枕头或撑地，下侧腿屈膝稳定身体。\n上侧腿伸直、脚尖朝前或微内旋，臀部外侧发力将腿向侧上方抬起。\n抬至约45度或略高，感受臀中肌收缩，稍停一秒。\n缓慢放下，腿不落地即开始下一次。\n完成一侧规定次数后换边。", "腿外旋、脚尖朝上抬起，目标肌群变成髋屈肌，应保持脚尖朝前。\n骨盆后倒甩腿，应锁住骨盆只用髋关节活动。\n抬得过高导致腰部代偿，控制在臀肌可主导的幅度内。"),
        Seed("wg:side-lying-leg-raise", "侧卧抬腿", "Side-Lying Leg Raise", "side-lying-leg-raise", "legs", "Glutes", "Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/side-lying-leg-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧卧，身体呈一条直线，核心收紧，下侧腿屈膝作支撑。\n上侧腿伸直，臀部外侧发力将整条腿向侧上方抬起。\n抬至约45度，稍停一秒感受臀部收缩。\n缓慢放下，脚接近地面但不落地即开始下一次。\n完成一侧规定次数后换边。", "躯干前后晃动或骨盆翻转借力，应保持身体呈一条稳定直线。\n腿抬得过高导致腰椎侧弯代偿，幅度以臀部主导为限。\n放下时完全放松砸落，应全程有控制。"),
        Seed("wg:lying-hamstring-walkout", "仰卧腘绳肌行走", "Lying Hamstring Walkout", "lying-hamstring-walkout", "legs", "Hamstrings", "Glutes,Core", "Bodyweight", "bodyweight_reps", false, "exercises/legs/lying-hamstring-walkout/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，双臂放体侧，双腿抬起屈髋约90度（或伸直指向天花板）。\n一腿保持抬起，另一腿缓慢向前下方放低，腘绳肌有控制地延展。\n将该腿拉回，换另一腿放低，像在空中交替行走。\n全程下背部紧贴地面，不因腿部放低而拱起。\n交替完成规定次数。", "放腿过低导致下背离地拱起，腰椎代偿，放低幅度以腰部贴地为准。\n腿部自由落体无离心控制，腘绳肌应缓慢延展。\n速度过快变成摆动，失去核心与腘绳肌的控制训练意义。"),
        Seed("wg:towel-hamstring-curl", "毛巾腿弯举", "Towel Hamstring Curl", "towel-hamstring-curl", "legs", "Hamstrings", "Glutes,Core", "Towel", "bodyweight_reps", false, "exercises/legs/towel-hamstring-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧于光滑地面（或在脚跟下垫毛巾），屈膝，脚跟踩在毛巾上。\n臀部抬起成臀桥，肩、髋、膝呈一条直线并保持住。\n脚跟发力将毛巾向臀部方向拉动，屈膝收腿，感受腘绳肌强烈收缩。\n缓慢将毛巾推回远处伸直双腿，臀桥姿态全程不塌。\n重复完成规定次数。", "髋部下塌塌腰，臀桥姿态一旦破坏立即停止调整，应夹紧臀部维持。\n用手臂或腰部代偿拉动，发力应来自腘绳肌屈膝。\n回放速度失控，离心阶段缓慢推出才能充分刺激。"),
        Seed("wg:stability-ball-hamstring-curl", "健身球腿弯举", "Stability Ball Hamstring Curl", "stability-ball-hamstring-curl", "legs", "Hamstrings", "Glutes,Core", "Stability Ball", "bodyweight_reps", false, "exercises/legs/stability-ball-hamstring-curl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，双臂放体侧撑地，双脚脚踝置于健身球上，双腿伸直，臀部抬起成桥。\n夹紧臀部保持肩髋踝一条直线。\n屈膝将球向臀部方向滚动，直到膝盖接近胸口方向，感受腘绳肌收缩。\n缓慢将球推回远处，回到直腿臀桥姿态。\n重复完成规定次数。", "髋部在滚动中下塌，应全程夹臀保持桥姿，塌了立即停止。\n球左右乱晃失去控制，动作应在一个平面上稳定进行。\n只靠屈髋代偿，发力重点是屈膝收球，腘绳肌主导。"),
        Seed("wg:banded-glute-bridge", "弹力带臀桥", "Banded Glute Bridge", "banded-glute-bridge", "legs", "Glutes", "Hamstrings,Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-glute-bridge/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧屈膝，将弹力带绕在大腿上段（膝盖上方），双脚踩地略宽于肩，膝盖对抗弹力带向外打开。\n脚跟发力将髋部顶起至肩髋膝一条直线。\n顶端用力夹紧臀部，同时膝盖持续外展对抗弹力带，稍停一秒。\n缓慢放下髋部回到接近地面的位置。\n重复完成规定次数。", "膝盖向内塌被弹力带拉拢，应全程外展对抗弹力带。\n腰椎过度反弓顶髋，顶端以夹紧臀部为限，不要追求顶得更高。\n髋部落地完全放松再猛弹起，应有控制地完成每一次。"),
        Seed("wg:banded-hip-thrust", "弹力带臀推", "Banded Hip Thrust", "banded-hip-thrust", "legs", "Glutes", "Hamstrings,Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-hip-thrust/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "上背部靠在稳固的长凳或箱沿上，弹力带绕过髋部两端踩压在脚下或固定于重物，坐姿屈膝双脚踩实地面。\n臀部发力将髋部顶起至躯干与地面平行、肩髋膝一条直线。\n顶端夹紧臀部，下巴微收，躯干不要过度反弓，稍停一秒。\n有控制地放下髋部回到起始位。\n重复完成规定次数。", "顶端腰椎过度伸展挺肚子，发力以夹臀为终点，肋骨下压。\n弹力带位置偏移到腹部或绕腿，应固定在髋部折痕处。\n下放砸落、节奏失控，离心阶段缓慢完成。"),
        Seed("wg:banded-frog-pump", "弹力带蛙式臀桥", "Banded Frog Pump", "banded-frog-pump", "legs", "Glutes", "Hamstrings", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-frog-pump/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，脚掌相对合拢、双膝外展成蛙式，弹力带绕过大腿上段。\n脚跟与上背撑地，臀肌发力对抗弹力带将髋部顶起。\n顶端夹紧臀部，稍停一秒。\n缓慢放下髋部，臀肌不停张即开始下一次。\n连续完成规定次数。", "膝盖塌向内侧被弹力带压拢，应全程保持外展对抗。\n腰椎反弓代偿顶髋，应锁定核心、以夹臀完成顶端收缩。\n幅度过小只做小幅颠动，应每次顶到髋部完全伸展。"),
        Seed("wg:banded-clamshell", "弹力带蚌式开合", "Banded Clamshell", "banded-clamshell", "legs", "Glutes", "Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-clamshell/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧卧，双膝屈曲叠放约90度，弹力带绕在膝盖上方的大腿处。\n保持双脚相触、骨盆垂直稳定。\n上方膝盖向上打开，对抗弹力带张力像蚌壳张开。\n打开至最大幅度稍停一秒，感受臀部外侧收缩。\n缓慢合拢回到起始位，完成一侧后换边。", "骨盆翻滚借力开腿，应保持骨盆锁住不动。\n弹力带过紧导致姿势崩塌，应选择能标准完成全程的阻力。\n双脚分开借力，双脚全程相触。"),
        Seed("wg:banded-lateral-walk", "弹力带侧向行走", "Banded Lateral Walk", "banded-lateral-walk", "legs", "Glutes", "Quads,Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-lateral-walk/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "弹力带绕在膝盖上方或脚踝处，屈髋微蹲成半蹲预备姿，腰背挺直。\n膝盖对抗弹力带向外撑开，保持张力不塌。\n向一侧横移一步，另一腿跟上一半距离，全程保持半蹲姿态和带的张力。\n向规定方向连续横移数步，再反向移回。\n全程保持躯干稳定、重心低。", "直立行走带子松掉，应始终保持半蹲与带张力。\n并步时双脚靠得太近让张力消失，跟进步幅保持一半距离。\n膝盖内扣，两膝始终向外对抗弹力带。"),
        Seed("wg:banded-monster-walk", "弹力带怪物行走", "Banded Monster Walk", "banded-monster-walk", "legs", "Glutes", "Quads,Hamstrings,Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-monster-walk/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "弹力带绕在脚踝处（或小腿下段），屈髋微蹲、腰背挺直、膝盖外撑保持张力。\n向前斜方迈一大步，再向另一侧斜前方迈步，呈之字形前进。\n每步落地后膝盖重新外撑恢复带张力。\n按规定步数前进后，以同样方式之字形后退返回。\n全程保持半蹲、核心收紧。", "直立迈步、膝盖内扣，应保持屈髋位且膝盖始终外撑。\n步幅过小带子松脱，每一步都要维持张力。\n弯腰驼背或重心乱晃，应锁定躯干稳定。"),
        Seed("wg:banded-squat", "弹力带深蹲", "Banded Squat", "banded-squat", "legs", "Quads", "Glutes,Hamstrings,Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-squat/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "弹力带踩在脚下绕过肩后（或绕在大腿上段做外展抗阻），双脚与肩同宽站立。\n屈髋屈膝下蹲至大腿接近平行，膝盖对准脚尖。\n若带绕肩：起身时对抗带的纵向拉力；若带绕腿：全程膝盖外展对抗。\n脚跟发力站起，顶端夹紧臀部。\n重复完成规定次数。", "膝盖内扣，弹力带绕腿时尤其要全程外撑。\n被弹力带拉拽导致躯干前倾弓背，应收紧核心保持中立。\n下蹲深度不足或节奏过快，蹲到位、控制速度。"),
        Seed("wg:banded-donkey-kick", "弹力带驴踢腿", "Banded Donkey Kick", "banded-donkey-kick", "legs", "Glutes", "Hamstrings,Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-donkey-kick/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "四点跪姿，弹力带一端固定，另一端绕在一侧脚掌上（或绕过脚底踩住）。\n核心收紧保持腰背平直。\n该腿屈膝约90度，臀部发力向后上方踢腿，对抗弹力带张力。\n抬至大腿与躯干接近平齐，顶端夹紧臀部稍停。\n有控制地收回，完成一侧后换腿。", "抬腿过高导致塌腰，腰背必须保持平直。\n腿向外侧撇借弹力方向，发力应保持正后上方。\n弹腿惯性完成，应慢踢慢收全程控制。"),
        Seed("wg:banded-fire-hydrant", "弹力带消防栓式", "Banded Fire Hydrant", "banded-fire-hydrant", "legs", "Glutes", "Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-fire-hydrant/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "四点跪姿，弹力带绕在膝盖上方的大腿处（或一端固定一端绕腿）。\n核心收紧，保持腰背平直、骨盆稳定。\n一侧腿保持屈膝约90度，向外上方抬起对抗弹力带，像消防栓开阀。\n抬至能力所及幅度，稍停感受臀部外侧收缩。\n缓慢收回，完成一侧后换腿。", "躯干向对侧倾斜代偿，应保持上身稳定不动。\n塌腰或骨盆旋转，全程锁住核心与骨盆。\n甩腿借弹力回弹，抬起与收回都要有控制。"),
        Seed("wg:banded-kickback", "弹力带后踢腿", "Banded Kickback", "banded-kickback", "legs", "Glutes", "Hamstrings,Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-kickback/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "弹力带一端固定于低位，另一端绕在一侧脚踝上，面对固定点站立并扶稳支撑物。\n核心收紧、腰背平直，躯干可略前倾。\n该腿伸直向后上方踢起，对抗弹力带张力，感受臀部收缩。\n顶端夹紧臀部稍停一秒。\n有控制地收回，完成一侧规定次数后换腿。", "腰椎塌陷反弓追求抬得更高，抬到臀部主导的幅度即可。\n甩腿借弹性惯性，起落全程受控。\n骨盆旋转或身体大幅摇摆，应扶稳并锁住骨盆。"),
        Seed("wg:banded-standing-hip-abduction", "站姿弹力带髋外展", "Banded Standing Hip Abduction", "banded-standing-hip-abduction", "legs", "Glutes", "Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-standing-hip-abduction/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "弹力带一端固定，另一端绕在一侧脚踝上，侧对固定点站立，外侧腿为工作腿，扶稳支撑物。\n核心收紧，身体保持直立稳定。\n工作腿伸直向外侧抬起，对抗弹力带张力，脚尖保持朝前。\n抬至约45度稍停，感受臀部外侧收缩。\n缓慢收回，完成规定次数后换边。", "骨盆向对侧倾倒或躯干侧弯借力，应保持身体垂直稳定。\n腿外旋脚尖朝上，应保持脚尖朝前让臀中肌主导。\n抬腿过高甩动，幅度与速度都要受控。"),
        Seed("wg:banded-seated-hip-abduction", "坐姿弹力带髋外展", "Banded Seated Hip Abduction", "banded-seated-hip-abduction", "legs", "Glutes", "Core", "Resistance Band", "bodyweight_reps", false, "exercises/legs/banded-seated-hip-abduction/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐在凳上或椅上前半段，弹力带绕在膝盖上方大腿处，双脚踩地。\n上身直立、核心收紧，双手可扶住凳沿稳定骨盆。\n双膝向外打开对抗弹力带张力，感受臀部外侧收缩。\n打开至最大幅度稍停一秒。\n缓慢合拢回到起始位，重复完成规定次数。", "弯腰弓背或后仰借力，应保持上身直立。\n用惯性快速开合，应慢开慢合、顶端停顿。\n双脚离地或脚跟抬起借力，双脚全程踩实地面。"),
        Seed("wg:band-pull-apart", "弹力带拉开", "Band Pull-Apart", "band-pull-apart", "back", "Upper Back", "Rear Delts,Shoulders", "Resistance Band", "bodyweight_reps", false, "exercises/back/band-pull-apart/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手正握弹力带两端，手臂前平举伸直，与肩同高。\n肩胛先收紧，双手向两侧水平拉开弹力带至胸前展开。\n末端感受上背和肩后束强烈收缩，停顿一至两秒。\n缓慢有控制地合拢还原，保持弹力带张力不放松。\n手臂保持伸直，全程不耸肩。", "耸肩或用斜方肌上部代偿：肩部放松下沉，让肩胛中下部主导。\n弹力带过粗、靠甩动拉开：选择能全程控制的阻力，匀速完成。"),
        Seed("wg:banded-face-pull", "弹力带面拉", "Banded Face Pull", "banded-face-pull", "back", "Upper Back", "Rear Delts,Shoulders", "Resistance Band", "bodyweight_reps", false, "exercises/back/banded-face-pull/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "把弹力带固定在约脸高的锚点，双手握住两端向后退一步建立张力。\n肩胛先向后收紧，把带子两端拉向脸部两侧，手肘向外展开略高于肩。\n终点呈双臂外旋姿势（类似双臂做'投降'动作），感受上背与肩后束收缩。\n停顿一秒，缓慢还原，全程保持张力。\n躯干稳定，不要后仰借力。", "肘部下垂只向胸口拉：保持肘部外展高于肩，并加入外旋。\n重量过大身体后仰：减小张力，固定躯干，肩胛主导。"),
        Seed("wg:banded-row", "弹力带划船", "Banded Row", "banded-row", "back", "Back", "Biceps,Upper Back", "Resistance Band", "bodyweight_reps", false, "exercises/back/banded-row/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "弹力带固定在前方锚点或绕脚踩住，双手握两端，站姿或坐姿、脊柱中立。\n肩胛先向后下方收紧，肘部贴近身体把弹力带拉向腹部方向。\n顶端感受背部收缩停顿一秒，缓慢还原至手臂伸展。\n全程保持弹力带张力，不让其松弛。\n核心收紧，躯干不前后摇摆。", "靠身体后倾代替手臂拉：固定躯干，肩胛和肘部完成动作。\n还原时弹力带瞬间松弛：全程控制张力，缓慢还原。"),
        Seed("wg:banded-lat-pulldown", "弹力带高位下拉", "Banded Lat Pulldown", "banded-lat-pulldown", "back", "Lats", "Biceps,Core", "Resistance Band", "bodyweight_reps", false, "exercises/back/banded-lat-pulldown/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "弹力带固定在高处锚点，可跪姿或坐姿握住两端，脊柱中立。\n肩胛先下沉后收，肘部向下向后引导拉带。\n把手拉向肩部两侧或锁骨方向，感受背阔肌收缩。\n顶端停顿，缓慢向上还原让背部充分伸展。\n核心收紧保持躯干稳定，不后仰借力。", "身体大幅后仰借力：减小张力，固定躯干，肘部引导。\n只用手臂拉：先做肩胛下沉再屈肘，背阔肌主导。"),
        Seed("wg:banded-pallof-press", "弹力带抗旋转推举", "Banded Pallof Press", "banded-pallof-press", "core", "Core", "Glutes,Shoulders", "Resistance Band", "bodyweight_reps", false, "exercises/core/banded-pallof-press/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧对弹力带锚点站立，双手握带于胸前，制造张力\n收紧腹部与臀部，躯干正对前方\n呼气缓慢向前推出至手臂伸直\n抵抗旋转力保持2-3秒，躯干不动\n吸气缓慢收回，完成次数后换边", "被弹力带拉力旋转躯干，抗旋失败\n耸肩或手腕塌陷，肩部代偿\n憋气，推出保持与收回应配合呼吸"),
        Seed("wg:banded-woodchop", "弹力带伐木", "Banded Woodchop", "banded-woodchop", "core", "Core", "Shoulders,Glutes", "Resistance Band", "bodyweight_reps", false, "exercises/core/banded-woodchop/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧对低位弹力带锚点站立，双脚宽于肩，膝盖微屈\n双手握带于低位，收紧腹部，腰椎中立\n呼气用腹斜肌带动躯干向对侧上方斜向拉起\n重心随转动平稳转移，后腿自然伸展\n缓慢有控制地回到起始位置，完成后换边", "靠手臂甩动弹力带，躯干旋转不足\n弹力带回弹过快失去控制，应缓慢回放\n旋转时弓腰，腰椎失去中立位"),
        Seed("wg:banded-dead-bug", "弹力带死虫式", "Banded Dead Bug", "banded-dead-bug", "core", "Core", "Glutes,Shoulders", "Resistance Band", "bodyweight_reps", false, "exercises/core/banded-dead-bug/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，双手分别拉住弹力带两端，手臂指向天花板，屈膝90度抬起\n呼气收紧腹肌，腰椎牢牢贴地\n缓慢伸直对侧手臂与腿，弹力带保持张力\n吸气缓慢收回，换对侧交替进行\n全程骨盆稳定，腰部不离地", "伸腿时腰部拱起离地，骨盆失去稳定\n弹力带张力过大导致手臂被拉偏，肩部代偿\n憋气，应配合伸展与收回节奏持续呼吸"),
        Seed("wg:hollow-body-hold", "空心保持", "Hollow Body Hold", "hollow-body-hold", "core", "Core", "Quads", "Bodyweight", "duration", false, "exercises/core/hollow-body-hold/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，双臂伸直过头，双腿并拢伸直\n呼气收紧腹肌，腰椎压向地面\n缓慢抬起双臂双腿离地，身体呈浅浅的香蕉形\n下背部保持贴地，不塌不拱\n自然呼吸坚持规定时间，降低幅度以维持腰部贴地", "腰部离地反弓，腰椎失去贴地支撑\n抬得过高使腹肌张力消失，应保持核心持续紧张\n憋气硬撑，应全程保持均匀呼吸"),
        Seed("wg:hollow-rock", "空心摇摆", "Hollow Rock", "hollow-rock", "core", "Core", "Quads", "Bodyweight", "bodyweight_reps", false, "exercises/core/hollow-rock/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "先建立空心体位：仰卧、腰椎贴地、四肢伸直离地呈香蕉形\n收紧腹肌，保持身体刚性整体\n以腹部为支点前后小幅 rocking 摇摆\n全程腰部始终贴地不反弓，身体不松散\n自然呼吸，节奏均匀连贯", "腰部离地反弓，骨盆失去贴地支撑\n身体松散像绳子，四肢各自晃动而非整体摇摆\n摆幅过大失控，应保持小幅刚性摆动"),
        Seed("wg:v-up", "V 字起坐", "V-Up", "v-up", "core", "Core", "Quads", "Bodyweight", "bodyweight_reps", false, "exercises/core/v-up/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，双腿伸直，双臂伸直过头，腰椎贴地\n呼气同时抬起双腿与躯干，用腹肌卷起身体\n双手在顶点触碰脚尖或脚踝，身体呈V形\n吸气缓慢下放，四肢轻触地面再进行下一次\n全程控制速度，腰部尽量贴地，不用惯性甩起", "靠惯性猛甩四肢起落，腹肌主导不足\n下放时腰部反弓拍地，腰椎受冲击\n屈膝过多降低难度变形，应保持双腿伸直"),
        Seed("wg:flutter-kick", "交替摆腿", "Flutter Kick", "flutter-kick", "core", "Core", "Quads", "Bodyweight", "duration", false, "exercises/core/flutter-kick/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，双腿伸直抬离地面约15-30厘米，腰椎贴地\n双手置于体侧或臀部下方辅助稳定\n双腿上下小幅交替摆动，幅度约20-30厘米\n全程腰部牢牢压向地面，不反弓\n自然呼吸不憋气，节奏均匀", "腰部离地反弓，腰椎失去贴地支撑\n摆幅过大或速度过快失控\n憋气，应保持连续均匀呼吸"),
        Seed("wg:lying-leg-raise", "仰卧举腿", "Lying Leg Raise", "lying-leg-raise", "core", "Core", "Quads", "Bodyweight", "bodyweight_reps", false, "exercises/core/lying-leg-raise/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，双腿伸直并拢，双手置于体侧，腰椎贴地\n呼气收紧腹肌，缓慢抬起双腿至垂直或更高\n骨盆微微卷起，腰椎不拱起离地\n吸气缓慢下放，腿不触地即开始下一次\n全程控制速度，腰部始终贴住地面", "下放过快腰部反弓，是仰卧举腿最常见的腰椎代偿\n骨盆不卷起只抬腿，腹肌参与不足\n幅度过大超出控制能力，应缩小范围保持贴地"),
        Seed("wg:toe-touch", "触碰脚趾", "Toe Touch", "toe-touch", "core", "Core", "", "Bodyweight", "bodyweight_reps", false, "exercises/core/toe-touch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧，双腿伸直垂直于地面指向天花板，腰椎贴地\n呼气收紧腹肌，用腹肌卷起肩胛与上背\n双手伸向脚尖方向，顶点稍停\n吸气缓慢下放，肩胛轻触地面再重复\n全程腰部贴地，靠腹肌卷起而非手臂甩动", "用手臂甩动的惯性带动上身，腹肌发力不足\n腰部离地，骨盆失去贴地稳定\n速度过快失去控制，应缓慢卷起缓慢下放"),
        Seed("wg:heel-tap", "脚跟轻点", "Heel Tap", "heel-tap", "core", "Core", "", "Bodyweight", "bodyweight_reps", false, "exercises/core/heel-tap/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧屈膝，双脚平放，抬肩卷腹保持上背离地，腰椎贴地\n左右交替用同侧手触碰同侧脚跟\n每次触碰时腹斜肌明显收缩，身体小幅侧倾\n保持呼吸均匀，节奏缓慢可控\n全程骨盆不动，侧倾幅度不要过大", "侧倾幅度过大变成大幅度转体，腹斜肌张力丢失\n骨盆随身体晃动，失去贴地稳定\n肩部塌下休息，上背应全程保持卷起"),
        Seed("wg:plank-shoulder-tap", "平板拍肩", "Plank Shoulder Tap", "plank-shoulder-tap", "core", "Core", "Shoulders,Chest", "Bodyweight", "bodyweight_reps", false, "exercises/core/plank-shoulder-tap/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "起始位为高位平板，手腕在肩正下方，双脚略宽于肩\n收紧腹部与臀部，腰椎保持中立贴平\n骨盆保持水平，单手离地缓慢轻拍对侧肩\n缓慢放回，换手交替进行\n全程自然呼吸，髋部旋转和晃动越小越好", "髋部左右摇摆旋转，骨盆失去稳定\n塌腰撅臀，腰椎失去中立位\n速度过快求次数，应放慢保持质量"),
        Seed("wg:plank-jack", "平板开合跳", "Plank Jack", "plank-jack", "core", "Core", "Shoulders,Cardio", "Bodyweight", "duration", false, "exercises/core/plank-jack/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "起始位为高位平板，手腕在肩下，身体呈直线\n收紧腹部与臀部，腰椎贴平\n双脚像开合跳一样交替向外向内跳开并拢\n髋部保持稳定不上下起伏，肩部在手腕正上方\n呼吸保持连续均匀，节奏稳定", "塌腰或撅臀，落地时腰椎晃动\n髋部上下起伏过大，核心未锁住\n憋气赶速度，应保持连续呼吸"),
        Seed("wg:bear-plank", "熊式平板", "Bear Plank", "bear-plank", "core", "Core", "Quads,Shoulders", "Bodyweight", "duration", false, "exercises/core/bear-plank/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "四点跪姿起始，手腕在肩下、膝盖在髋下\n膝盖上提离地约3-5厘米，小腿与地面平行\n收紧腹部与臀部，腰椎保持中立\n保持等长支撑，全程呼吸均匀\n背部平直不塌不拱，骨盆稳定不歪斜", "臀部抬高变成下犬式，核心张力丢失\n塌腰或背部拱起，腰椎失去中立位\n憋气硬撑，应全程保持均匀呼吸"),
        Seed("wg:bear-crawl", "熊爬", "Bear Crawl", "bear-crawl", "core", "Core", "Shoulders,Quads,Cardio", "Bodyweight", "duration", false, "exercises/core/bear-crawl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "从熊式平板位开始，膝离地3-5厘米，背部平直\n对侧手脚同步移动，向前缓慢爬行\n全程膝盖保持贴近地面不抬高，腰椎中立\n收紧腹部，骨盆不左右晃动\n呼吸均匀，行进速度以保持姿势质量为先", "臀部抬高变成近似蹲走，核心张力丢失\n塌腰或身体大幅左右摇摆\n爬行过快失去控制，应放慢保持姿势质量"),
        Seed("wg:crab-walk", "蟹行", "Crab Walk", "crab-walk", "arms", "Triceps", "Glutes,Core,Shoulders", "Bodyweight", "duration", false, "exercises/arms/crab-walk/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐姿屈膝，双手置于身后地面指尖朝前，抬起臀部让身体呈桌面姿态\n保持臀部抬高、核心收紧，手脚交替向前爬行\n目视前方或略上，颈部保持中立，肩部稳定支撑\n走完规定距离后屈膝缓慢坐回地面", "臀部塌陷下垂，三头和核心的负荷大量转移\n颈部后仰目视后方，颈椎受压\n步幅过大身体摇晃，手腕承压不均易受伤"),
        Seed("wg:inchworm", "毛毛虫式", "Inchworm", "inchworm", "core", "Core", "Shoulders,Hamstrings,Chest", "Bodyweight", "bodyweight_reps", false, "exercises/core/inchworm/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站立位，双脚与髋同宽\n屈髋俯身，双手走向前方至高位平板位\n在平板位收紧核心保持一拍，腰椎平直\n双手小步走回或跳回，屈髋起身站立\n全程膝盖可微屈，腰背不过度下塌，呼吸自然", "走向平板位时塌腰，腰椎失去中立位\n动作速度过快，核心稳定环节被跳过\n腘绳肌柔韧不足却强行直腿触地，应屈膝完成"),
        Seed("wg:l-sit-hold", "L 坐保持", "L-Sit Hold", "l-sit-hold", "core", "Core", "Triceps,Quads,Shoulders", "Bodyweight", "duration", false, "exercises/core/l-sit-hold/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双手撑于平行杠或稳固支撑面，肩胛下沉推起身体\n呼气收紧腹肌，双腿伸直抬起至与地面平行\n骨盆微微后倾，腰椎不反弓\n保持等长支撑，全程自然呼吸不憋气\n力竭前缓慢放下双腿，避免突然垮落", "腰椎反弓塌腰，骨盆未后倾锁定\n耸肩撑肩，肩胛未下沉锁定\n憋气硬撑，应保持小幅度持续呼吸"),
        Seed("wg:seated-knee-tuck", "坐姿屈膝收腹", "Seated Knee Tuck", "seated-knee-tuck", "core", "Core", "Quads", "Bodyweight", "bodyweight_reps", false, "exercises/core/seated-knee-tuck/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "坐地，双手置于臀后撑地，上身微后倾，背部挺直\n双腿伸直抬离地面，收紧腹肌\n呼气屈膝把膝盖拉向胸口，骨盆微微卷起\n吸气缓慢伸直双腿，脚不触地再重复\n全程腰部保持挺直不塌，用腹肌主导收放", "弓腰塌背撑地，腰椎失去中立位\n靠手臂和惯性摆动代替腹肌收放\n下放过快失控，应缓慢伸腿保持张力"),
        Seed("wg:side-plank-hip-dip", "侧平板髋下沉", "Side Plank Hip Dip", "side-plank-hip-dip", "core", "Core", "Shoulders,Glutes", "Bodyweight", "bodyweight_reps", false, "exercises/core/side-plank-hip-dip/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "起始位为标准侧平板：单肘撑地，身体呈直线\n收紧腹侧与臀部，骨盆保持中立\n呼气缓慢将髋部向地面下沉但不触地\n吸气用腹斜肌把髋部拉回直线位置\n全程身体前后不倾倒，完成次数后换边", "髋部下沉时身体前倾或后倒，失去侧向直线\n下沉过深失去控制，应小幅可控\n憋气，下沉与回拉应配合呼吸"),
        Seed("wg:copenhagen-plank", "哥本哈根平板", "Copenhagen Plank", "copenhagen-plank", "core", "Core", "Quads,Glutes", "Bodyweight", "duration", false, "exercises/core/copenhagen-plank/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "侧卧，内侧小腿或脚踩在长凳上，外侧腿伸直叠放或悬空\n单肘撑地推起身体，头、髋、脚呈一条直线\n收紧腹侧、臀部与大腿内侧，骨盆不塌不转\n保持等长支撑，全程自然呼吸\n力竭前缓慢放下，完成时间后换边", "髋部下沉塌陷，内收肌与腹侧张力丢失\n支撑腿位置过高或肩肘错位，增加受伤风险\n憋气硬撑，应全程保持均匀呼吸"),
        Seed("wg:dragon-flag", "龙旗", "Dragon Flag", "dragon-flag", "core", "Core", "Lats,Quads", "Bodyweight", "bodyweight_reps", false, "exercises/core/dragon-flag/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "仰卧于稳固长凳或地面，双手过头抓住固定物\n呼气收紧腹肌，双腿与躯干作为整体抬起至竖直\n骨盆后倾，腰椎贴地，身体从头到脚保持刚性\n极其缓慢地下放整个身体，只让肩胛以上承重\n下放至接近地面但不触地，再拉回竖直，全程不塌腰", "下放时塌腰反弓，腰椎承受剪切力，这是龙旗最危险的问题\n身体分节折叠失去刚性，应整体像杠杆一样升降\n进度过快，应先从屈膝版本逐步过渡到直腿"),
        Seed("wg:burpee", "波比跳", "Burpee", "burpee", "legs", "Legs", "Chest,Shoulders,Core,Cardio", "Bodyweight", "bodyweight_reps", false, "exercises/legs/burpee/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站立开始，屈髋下蹲，双手撑地。\n双脚向后蹬跳成俯撑姿态，身体呈一条直线（可附加俯卧撑）。\n核心收紧保持躯干稳定，双脚跳回双手两侧。\n起身并垂直向上跳起，双手过头击掌（可简化为站起）。\n落地缓冲后立即进入下一次，按计划完成次数或时间。", "俯撑阶段塌腰撅臀，核心应锁住身体呈一条直线。\n落地膝盖内扣直腿硬着陆，应屈膝缓冲、对准脚尖。\n动作变形后仍冲刺次数，疲劳时宁可降速保质量。"),
        Seed("wg:half-burpee", "半程波比跳", "Half Burpee", "half-burpee", "core", "Core", "Legs,Shoulders,Cardio", "Bodyweight", "bodyweight_reps", false, "exercises/core/half-burpee/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "起始位为高位平板，身体呈直线，核心收紧\n双脚跳向双手方向落地呈蹲姿，胸口抬起\n双脚跳回平板位，腰椎不塌\n全程保持呼吸连续，节奏稳定\n落地时膝盖微屈缓冲，落地声越轻越好", "回跳平板位时塌腰，腰椎受冲击\n落地沉重不缓冲，膝盖和腰椎受力大\n憋气赶速度，应保持连续呼吸节奏"),
        Seed("wg:squat-thrust", "深蹲俯卧撑跳", "Squat Thrust", "squat-thrust", "core", "Core", "Legs,Shoulders,Cardio", "Bodyweight", "bodyweight_reps", false, "exercises/core/squat-thrust/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站立位，双脚与髋同宽\n屈髋下蹲，双手撑地\n双脚向后蹬出呈平板位，腰椎平直，核心收紧\n双脚跳回手侧呈蹲姿，然后起身站立\n全程呼吸连续，动作节奏均匀可控", "蹬出平板位时塌腰，腰椎失去中立位\n起身时弓背弯腰，应用腿部和髋部发力站起\n节奏过快失控，应保持每一步姿势质量"),
        Seed("wg:high-knees", "高抬腿", "High Knees", "high-knees", "legs", "Legs", "Core,Cardio", "Bodyweight", "duration", false, "exercises/legs/high-knees/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站立，核心收紧，身体略前倾但腰背挺直。\n原地或行进间交替将膝盖抬高至髋部高度。\n前脚掌快速着地，配合手臂前后摆动维持节奏。\n保持步频快、落地轻，持续规定时间或次数。\n结束前逐渐放慢过渡到原地踏步恢复。", "身体过度后仰弯腰，应保持躯干略前倾、核心收紧。\n全脚掌沉重着地，应前脚掌轻落地、快速反弹。\n膝盖抬不起来只做小碎步，膝盖应抬至髋部高度才有训练价值。"),
        Seed("wg:jumping-jack", "开合跳", "Jumping Jack", "jumping-jack", "legs", "Legs", "Shoulders,Calves,Cardio", "Bodyweight", "duration", false, "exercises/legs/jumping-jack/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "双脚并拢站立，双手垂于体侧。\n跳起同时双脚向两侧分开，双臂经体侧上举过头。\n再次跳起收回双脚并拢，手臂落回体侧。\n保持节奏连续完成规定时间或次数。\n全程前脚掌落地、膝盖微屈缓冲。", "落地沉重、膝盖僵直，应前脚掌着地屈膝缓冲。\n手臂举不到位只到胸前，动作幅度应完整。\n节奏过快导致姿势散乱，宁可稍慢保持动作标准。"),
        Seed("wg:skater-hop", "滑冰者跳", "Skater Hop", "skater-hop", "legs", "Legs", "Glutes,Calves,Cardio", "Bodyweight", "bodyweight_reps", false, "exercises/legs/skater-hop/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "单腿微蹲站立，核心收紧。\n向侧方爆发跳出，另一腿在身后交叉点地缓冲，呈滑冰者落地姿势。\n落地腿屈膝屈髋缓冲，膝盖对准脚尖。\n立即从落地腿向反方向爆发跳回。\n左右交替连续完成，像滑冰一样侧向流动。", "落地膝盖内扣，侧向落地的力线控制是关键，膝盖对准脚尖。\n落地缓冲不足直腿硬着陆，应屈膝屈髋充分吸收冲击。\n停留过久失去连续性，缓冲后尽快衔接下一次跳跃。"),
        Seed("wg:lateral-shuffle", "侧向滑步", "Lateral Shuffle", "lateral-shuffle", "legs", "Legs", "Glutes,Calves,Cardio", "Bodyweight", "duration", false, "exercises/legs/lateral-shuffle/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "屈髋半蹲，腰背挺直，重心放低，双臂自然张开平衡。\n向一侧连续快速滑步移动，前脚先动、后脚跟随，双脚不交叉。\n移动中保持半蹲高度和带张力般的双膝外撑姿态（不加负重时同样保持膝盖对准脚尖）。\n到达规定距离后反向滑回。\n全程重心低、节奏快、落地轻。", "直起身变成直立碎步，应全程保持半蹲低重心。\n双脚交叉绊步，应侧步跟随、永不交叉。\n膝盖内扣，滑步中始终保持膝盖对准脚尖方向。"),
        Seed("wg:fast-feet", "快速脚步", "Fast Feet", "fast-feet", "legs", "Calves", "Legs,Cardio", "Bodyweight", "duration", false, "exercises/legs/fast-feet/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "屈髋微蹲成运动预备姿势，重心在前脚掌，腰背挺直。\n双脚以最快频率交替小幅点地，像踩烫脚一样快速转换。\n手臂自然摆动配合节奏，重心保持低而稳。\n持续规定时间，保持步频不下降。\n结束前放慢频率过渡恢复。", "站直做高频踏步，必须在屈髋半蹲位完成才能练到下肢。\n步幅过大变成小跑，应是小幅、高频的原地点地。\n重心高、脚跟着地，重心压在前脚掌并保持低姿。"),
        Seed("wg:sprawl", "俯身跳", "Sprawl", "sprawl", "legs", "Legs", "Core,Shoulders,Cardio", "Bodyweight", "bodyweight_reps", false, "exercises/legs/sprawl/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站立开始，屈髋俯身，双手撑地，双脚向后蹬出，身体贴向地面（胸口轻触或接近地面）。\n核心收紧保持身体呈一条直线，避免塌腰。\n双脚蹬地跳回双手附近。\n起身站直，可起身时向上跳起增强强度。\n连续完成规定次数，保持动作完整与落地缓冲。", "塌腰撅臀趴地，俯撑阶段必须锁紧核心保持直线。\n起身弯腰弓背搬运身体，应屈膝下蹲再站起保护腰部。\n速度优先导致姿势崩坏，波比类动作质量永远优先于速度。"),
        Seed("wg:seal-jack", "海豹跳", "Seal Jack", "seal-jack", "chest", "Chest", "Shoulders,Legs,Cardio", "Bodyweight", "duration", false, "exercises/chest/seal-jack/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站立，双脚并拢，双臂在胸前伸直并拢，像海豹合掌。\n跳跃时双脚向两侧分开，同时双臂向两侧打开到与肩同高，胸口有展开感。\n再次跳起时双脚并拢收回，双臂在体前合拢，感受胸肌内收挤压。\n保持节奏连续跳跃，落地屈膝缓冲。\n开合时配合呼吸，动作连贯不憋气。", "落地膝盖锁死不缓冲：落地时屈膝轻踩，像猫一样安静落地。\n手臂不打开只动腿：双臂要完整开合，让胸肌参与外展和内收。\n节奏太快动作变形：保持匀速，先做对幅度再加快频率。"),
        Seed("wg:cat-cow-stretch", "猫牛式", "Cat-Cow Stretch", "cat-cow-stretch", "mobility", "Mobility", "Back,Core", "Bodyweight", "duration", true, "exercises/mobility/cat-cow-stretch/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "四点跪姿，手腕在肩下、膝盖在髋下\n吸气时缓慢塌腰抬头进入牛式，胸椎延展\n呼气时缓慢拱背低头进入猫式，脊柱逐节拱起\n缓慢流畅地在两个体位间交替，配合呼吸节奏\n全程动作轻柔，不去追求按压疼痛的极限", "动作速度过快，脊柱没有逐节活动\n颈部过度后仰或猛低头，颈椎受压\n憋气，每个体位转换都应配合一次呼吸"),
        Seed("wg:arm-circles", "绕臂", "Arm Circles", "arm-circles", "shoulders", "Shoulders", "Chest,Upper Back,Mobility", "Bodyweight", "duration", true, "exercises/shoulders/arm-circles/frame-1.svg", "{\"creator\":\"Bryl Lim\",\"creatorUrl\":\"https://bryllim.com\",\"license\":\"CC BY-SA 4.0\",\"licenseUrl\":\"https://creativecommons.org/licenses/by-sa/4.0/\"}", "站立双脚与肩同宽，双臂侧平举至与肩同高，掌心向下\n向前绕环：手臂伸直画圈，由小圈逐渐加大，绕10-20秒\n向后绕环同样进行10-20秒\n绕环时肩胛保持放松下沉，躯干稳定不晃动\n保持自然呼吸，不要憋气", "耸肩、颈部紧张：肩膀下沉远离耳朵，颈肩放松\n幅度过大速度过猛：从小圈匀速开始逐渐加大，热身用中小幅度即可\n弯肘代替直臂绕环：手臂保持伸直，以肩关节为轴画完整圆圈"),
